/** One line per queryable ls_* table: dimension, grain, pk, join edges. Inject on every SQL turn. */
export const LIGHTSPEED_TABLE_INDEX = "Every source_lightspeed table also carries the platform envelope columns: tenant_id, connection_id, source_record_id, tombstone (soft delete — always filter false), mapping_version (pack generation — always pin via the pack CTE), ingested_at, first_ingested_at, source_updated_at, source_version, namespaced_source_key, external_account_reference, payload_hash, payload_batch_id, sync_run_id.\n\nEvery queryable Lightspeed table lives in source_lightspeed and starts with ls_. There are no other queryable tables in that schema (older unprefixed names are retired and empty).\nFormat: table — grain. pk: primary key. joins: fk_column→target_table.\n\n[catalogue]\nls_catalog_vendor_items — one product entry in one configured vendor catalogue. pk: catalog_vendor_item_id\nls_categories — one category node in the item category tree. pk: category_id\nls_images — one product image, attached to EITHER an item or a matrix (exactly one of the two). pk: image_id. joins: item_id→ls_items, item_matrix_id→ls_item_matrices\nls_item_attribute_sets — one attribute-set definition (the schema of a matrix's variant axes). pk: item_attribute_set_id\nls_item_components — one component line: the link between one assembly/box item and one of the items it is made from. pk: item_component_id\nls_item_fees — one configured item fee definition. pk: item_fee_id\nls_item_matrices — one matrix — one variant family of items (e.g. one jersey that exists in five sizes). pk: item_matrix_id. joins: category_id→ls_categories, tax_class_id→ls_tax_classes, manufacturer_id→ls_manufacturers, season_id→ls_seasons, item_attribute_set_id→ls_item_attribute_sets\nls_item_prices — one price level amount on one item — the unique key is (item_id, use_type_id), not item_id alone. pk: item_id, use_type_id. joins: item_id→ls_items\nls_item_shops — one item's stock record at one location; shop_id = 0 is the account-wide aggregate, so use it alone for whole…. pk: item_shop_id. joins: item_id→ls_items, shop_id→ls_shops, category_id→ls_categories, manufacturer_id→ls_manufacturers\nls_item_vendor_nums — one vendor-specific SKU: one item as catalogued by one vendor. pk: item_vendor_num_id. joins: item_id→ls_items, vendor_id→ls_vendors\nls_items — one catalogue item — a single sellable SKU. pk: item_id. joins: category_id→ls_categories, tax_class_id→ls_tax_classes, item_matrix_id→ls_item_matrices, manufacturer_id→ls_manufacturers, season_id→ls_seasons, item_attribute_set_id→ls_item_attribute_sets\nls_manufacturers — one manufacturer (brand). pk: manufacturer_id\nls_options — one account option: a name/value pair the account has turned on. pk: name\nls_price_levels — one price level definition on the account. pk: price_level_id\nls_seasons — one season label. pk: season_id\nls_serialized — one serial-number record — one physical serialized unit, whether it came from stock or was logged as a custom…. pk: serialized_id. joins: item_id→ls_items, sale_line_id→ls_sale_lines, customer_id→ls_customers\nls_tag_groups — one tag group name for the account. pk: name\nls_tags — one tag in the account's tag vocabulary. pk: tag_id\n\n[customers]\nls_contact_emails — one row per email address held on a contact. pk: contact_id, contact_email. joins: contact_id→ls_contacts\nls_contact_phones — one row per phone number held on a contact. pk: contact_id, contact_phone. joins: contact_id→ls_contacts\nls_contact_websites — one row per website URL held on a contact. pk: contact_id, contact_website. joins: contact_id→ls_contacts\nls_contacts — one row per Contact record (the single contact block attached to a Customer, CreditAccount or ShipTo). pk: contact_id. joins: ship_to_id→ls_ship_tos\nls_credit_accounts — one row per credit account: either a customer store account or a gift card. pk: credit_account_id. joins: customer_id→ls_customers, contact_id→ls_contacts\nls_custom_field_choices — one row per selectable option on a single_choice or multi_choice custom field. pk: custom_field_choice_id. joins: custom_field_id→ls_custom_fields\nls_custom_fields — one row per custom field definition available on customers. pk: custom_field_id\nls_customer_custom_field_values — one row per custom field value recorded on one customer. pk: custom_field_value_id. joins: customer_id→ls_customers, custom_field_id→ls_custom_fields, custom_field_choice_id→ls_custom_field_choices\nls_customer_notes — one row per note attached to a customer. pk: note_id. joins: customer_id→ls_customers\nls_customer_types — one row per customer type (segment definition). pk: customer_type_id. joins: tax_category_id→ls_tax_categories, discount_id→ls_discounts\nls_customers — one row per Customer record (one POS customer identity, account-wide, not one human being). pk: customer_id. joins: credit_account_id→ls_credit_accounts, customer_type_id→ls_customer_types, discount_id→ls_discounts, tax_category_id→ls_tax_categories, contact_id→ls_contacts\nls_ship_tos — one row per ShipTo record (one shipment destination created for a sale that needs sending). pk: ship_to_id. joins: customer_id→ls_customers, sale_id→ls_sales, contact_id→ls_contacts\n\n[inventory]\nls_inventory_count_calcs — one item within one inventory count (the system-vs-physical rollup for that item/count pair). pk: inventory_count_calc_id. joins: item_id→ls_items\nls_inventory_count_items — one physical counting act — one item counted once by one employee at one moment (counting the same item three…. pk: inventory_count_item_id. joins: item_id→ls_items, employee_id→ls_employees\nls_inventory_count_reconciles — one reconcile posting — one item's stock and cost adjustment applied when a count was reconciled. pk: inventory_count_reconcile_id. joins: item_id→ls_items\nls_inventory_logs — one inventory change event — one item's stock level changing in one shop, for one reason, at one moment. pk: inventory_log_id. joins: employee_id→ls_employees, item_id→ls_items, shop_id→ls_shops, order_id→ls_purchase_orders, transfer_id→ls_transfers, sale_id→ls_sales, customer_id→ls_customers, vendor_return_id→ls_vendor_returns\nls_special_orders — one special order — one item a named customer asked the shop to bring in, tracked from the sale line it was r…. pk: special_order_id. joins: customer_id→ls_customers, shop_id→ls_shops, sale_line_id→ls_sale_lines, order_line_id→ls_purchase_order_lines, transfer_item_id→ls_transfer_items\nls_transfer_from — one origin record for one stock transfer. pk: transfer_from_id\nls_transfer_items — one line on one transfer — one item on one inter-shop transfer document. pk: transfer_item_id. joins: transfer_id→ls_transfers, item_id→ls_items\nls_transfer_to — one destination record for one stock transfer. pk: transfer_to_id\nls_transfers — one inter-shop transfer document (header), with its origin-side and destination-side records flattened in. pk: transfer_id. joins: transfer_from_id→ls_transfer_from, transfer_to_id→ls_transfer_to, order_id→ls_purchase_orders, employee_id→ls_employees, shop_id→ls_shops\n\n[org]\nls_account — one row -- the Lightspeed Retail (R-Series) account associated with the access token (singleton). pk: account_id\nls_account_purchasing_currencies — one row per purchasing currency enabled on the account. pk: account_id, code. joins: account_id→ls_account\nls_cc_gateways — one row per legacy credit-card gateway configuration referenced by a shop. pk: cc_gateway_id\nls_currency_denominations — one physical currency denomination available in a locale. pk: locale_id, currency_denominations\nls_currency_rates — one row per foreign currency exchange rate the merchant maintains. pk: currency_rate_id\nls_employee_hours — one row per clock-in/clock-out entry for one employee at one shop. pk: employee_hours_id. joins: employee_id→ls_employees, shop_id→ls_shops\nls_employee_rights — one row per (employee, right) grant made directly to an employee -- effective only when that employee has no…. pk: employee_id, employee_right_id. joins: employee_id→ls_employees\nls_employee_role_rights — one row per (role, right) grant -- one right conferred by one role. pk: employee_role_id, employee_right_id. joins: employee_role_id→ls_employee_roles\nls_employee_roles — one row per employee role defined on the account. pk: employee_role_id\nls_employees — one row per employee login on the account, including archived former staff. pk: employee_id. joins: contact_id→ls_contacts, employee_role_id→ls_employee_roles\nls_industries — one row per Lightspeed catalog industry vertical, with its enabled state for this account. pk: industry_id\nls_locales — one row per locale Lightspeed publishes globally (a global catalogue, not the account's own setting). pk: name\nls_receipt_setups — one row per receipt setup configuration referenced by a shop. pk: receipt_setup_id\nls_registers — one row per point-of-sale register (till) configured on the account. pk: register_id. joins: shop_id→ls_shops\nls_session — one row -- the identity behind the access token currently in use (singleton). pk: system_api_key_id. joins: employee_id→ls_employees\nls_shops — one row per shop (physical store location) on the account, including archived ones. pk: shop_id. joins: contact_id→ls_contacts, tax_category_id→ls_tax_categories, receipt_setup_id→ls_receipt_setups, cc_gateway_id→ls_cc_gateways, price_level_id→ls_price_levels\n\n[purchasing]\nls_order_shipment_items — one product's receipt within one shipment (one row per ShipmentItem). pk: order_shipment_item_id. joins: order_shipment_id→ls_order_shipments, item_id→ls_items\nls_order_shipments — one shipment (receiving event) against one purchase order. pk: order_shipment_id. joins: order_id→ls_purchase_orders, employee_id→ls_employees\nls_purchase_order_lines — one product line on one purchase order (one row per OrderLine). pk: order_line_id. joins: order_id→ls_purchase_orders, item_id→ls_items, vendor_id→ls_vendors, shop_id→ls_shops\nls_purchase_orders — one purchase order raised with one vendor for one shop (Lightspeed resource `Order`). pk: order_id. joins: vendor_id→ls_vendors, note_id→ls_customer_notes, shop_id→ls_shops\nls_vendor_returns — one vendor return document raised at one shop for one vendor. pk: vendor_return_id. joins: vendor_id→ls_vendors, shop_id→ls_shops\nls_vendors — one supplier the account buys from. pk: vendor_id\n\n[registers]\nls_register_calculated — one payment type's live running total for one register's CURRENTLY OPEN session, as at the instant the endpoi…. pk: register_calculated_path_parameter_register_id, payment_type_id. joins: payment_type_id→ls_payment_types\nls_register_count_amounts — one payment type's expected-versus-counted pair inside one register close-out. pk: register_count_amount_id. joins: register_count_id→ls_register_counts, payment_type_id→ls_payment_types\nls_register_counts — one register close-out — the open-to-close session of a single till, written at the moment the closing count…. pk: register_count_id. joins: register_id→ls_registers\nls_register_withdraws — one cash add or payout at one register (a single signed drawer movement outside of sales). pk: register_withdraw_id. joins: employee_id→ls_employees, payment_type_id→ls_payment_types, register_id→ls_registers\n\n[sales]\nls_cc_charges — one row per CCCharge — one credit-card transaction ATTEMPT at the processing gateway, including declines, gat…. pk: cc_charge_id. joins: sale_id→ls_sales\nls_discounts — one row per named Discount rule that staff or the system can apply to a sale or a sale line. pk: discount_id\nls_processing_fees — one row per ProcessingFee — one fee record the payment processor assessed against one SalePayment. pk: sale_payment_processing_fee_id. joins: sale_payment_id→ls_sale_payments\nls_quotes — one row per Quote — one saved, uncompleted sale held for a customer so it can be reloaded at the register lat…. pk: quote_id. joins: employee_id→ls_employees, sale_id→ls_sales\nls_sale_accounts — one row per SaleAccount — one gift-card (CreditAccount) association linking a single SalePayment to the SaleL…. pk: sale_account_id. joins: credit_account_id→ls_credit_accounts, sale_payment_id→ls_sale_payments, sale_line_id→ls_sale_lines\nls_sale_line_inventory_allocations — one row per InventorySale — one allocation of units from ONE inventory lot to ONE sale line. pk: inventory_sale_id. joins: sale_line_id→ls_sale_lines, sale_id→ls_sales\nls_sale_lines — one row per SaleLine — one charge on one sale. pk: sale_line_id. joins: sale_id→ls_sales, tax_class_id→ls_tax_classes, customer_id→ls_customers, discount_id→ls_discounts, employee_id→ls_employees, item_id→ls_items, note_id→ls_customer_notes, shop_id→ls_shops\nls_sale_payment_signatures — one row per SalePaymentSignature — one captured signature image belonging to one sale payment. pk: sale_payment_signature_id. joins: sale_payment_id→ls_sale_payments\nls_sale_payments — one row per SalePayment — one tender applied to, or refunded from, one sale. pk: sale_payment_id. joins: sale_id→ls_sales, payment_type_id→ls_payment_types, cc_charge_id→ls_cc_charges, register_id→ls_registers, employee_id→ls_employees, credit_account_id→ls_credit_accounts, shop_id→ls_shops\nls_sale_voids — one row per SaleVoid — one void event recorded against one sale, with the operator's stated reason. pk: sale_void_id. joins: sale_id→ls_sales, employee_id→ls_employees, shop_id→ls_shops\nls_sales — one row per Sale record — one register ticket/transaction, in any state (open, completed, voided, archived). pk: sale_id. joins: customer_id→ls_customers, discount_id→ls_discounts, employee_id→ls_employees, quote_id→ls_quotes, register_id→ls_registers, ship_to_id→ls_ship_tos, shop_id→ls_shops, tax_category_id→ls_tax_categories\n\n[taxreports]\nls_payment_types — one tender method configured on the account. pk: payment_type_id\nls_report_discounts_by_day — one shop per day. pk: date, shop_id. joins: shop_id→ls_shops\nls_report_orders_by_tax_class — one tax-class cost subtotal within one received purchase order. pk: order_id, tax_class_id. joins: shop_id→ls_shops, vendor_id→ls_vendors, tax_class_id→ls_tax_classes, order_id→ls_purchase_orders\nls_report_payments_by_day — one payment type per shop per day, split by the layaway flag. pk: date, shop_id, payment_type_id, layaway. joins: shop_id→ls_shops, payment_type_id→ls_payment_types\nls_report_tax_class_sales_by_day — one tax class per shop per day. pk: date, shop_id, tax_class_id. joins: shop_id→ls_shops, tax_class_id→ls_tax_classes\nls_report_taxes_by_day — one tax category per shop per day. pk: date, shop_id, tax_category_id. joins: shop_id→ls_shops, tax_category_id→ls_tax_categories\nls_tax_categories — one sales-tax configuration (TaxCategory, labelled \"Sales Tax\" in the Lightspeed UI) on the account. pk: tax_category_id\nls_tax_category_classes — one per-tax-class rate override inside one tax category. pk: tax_category_id, tax_class_id. joins: tax_category_id→ls_tax_categories, tax_class_id→ls_tax_classes\nls_tax_classes — one tax class label that items and sale lines can carry. pk: tax_class_id\n\n[workshop]\nls_workorder_images — one row per image attached to one workorder. pk: workorder_image_id. joins: workorder_id→ls_workorders\nls_workorder_items — one row per part/product charge on one workorder. pk: workorder_item_id. joins: workorder_id→ls_workorders, employee_id→ls_employees, sale_line_id→ls_sale_lines, sale_id→ls_sales, item_id→ls_items, discount_id→ls_discounts\nls_workorder_lines — one row per labour task or misc (non-part) charge on one workorder. pk: workorder_line_id. joins: workorder_id→ls_workorders, employee_id→ls_employees, sale_line_id→ls_sale_lines, sale_id→ls_sales, item_id→ls_items, discount_id→ls_discounts, tax_class_id→ls_tax_classes\nls_workorder_statuses — one row per workorder status configured on the account (system-defined and store-created). pk: workorder_status_id\nls_workorders — one row per workorder — one service/repair ticket for one customer item (a Serialized entry) at one shop. pk: workorder_id. joins: customer_id→ls_customers, discount_id→ls_discounts, employee_id→ls_employees, serialized_id→ls_serialized, shop_id→ls_shops, sale_id→ls_sales, sale_line_id→ls_sale_lines, workorder_status_id→ls_workorder_statuses";

