/** Full per-dimension column dictionaries (live typed-staging DDL names with meanings). */
export const LIGHTSPEED_DIMENSION_DICTIONARIES: Readonly<Record<string, string>> = Object.freeze({
  "catalogue": "source_lightspeed.ls_catalog_vendor_items — one product entry in one configured vendor catalogue.\n  What the shop's suppliers say is available to ORDER: supplier part numbers, tiered costs, bulk price breaks, MSRPs, availability status and supersession.\n  primary key: catalog_vendor_item_id\n  catalog_vendor_item_id — Primary key of the catalogue entry\n  catalog_vendor_id — Which vendor CATALOGUE the entry belongs to\n  vendor_number — The part number the VENDOR assigns — what goes on a purchase order to that supplier\n  manufacturer_number — The part number the MANUFACTURER assigns\n  description — Name/description of the product as the vendor writes it\n  category — The VENDOR's suggested category as free text (e.g. 'Trunk Racks')\n  brand — Brand of the product per the catalogue\n  model — Model designation; the docs note it is usually a year\n  year — Model year of the item as text (not a number, so no arithmetic or range filters without casting)\n  upc — Universal Product Code\n  ean — International Article Number for the entry; the international counterpart of upc\n  ean2 — An alternate EAN\n  color_name — Colour as published by the vendor\n  size_name — Size as published by the vendor\n  retail_unit — How many SELLABLE units come per order unit (e.g. inner tubes supplied in boxes of 50)\n  unit_of_measurement — How multiple quantities are grouped for ordering — EA, box, pair\n  cost — Base cost per ORDER UNIT from the vendor, in the CATALOGUE's own currency (which may not be the store's)\n  cost_level2 — First discounted cost tier (a dealer-terms tier, not a volume break)\n  cost_level3 — Second discounted cost tier\n  cost_level4 — Final discounted cost tier — the best published terms\n  msrp — Manufacturer's suggested retail price per the catalogue, in the catalogue's currency\n  break_qty — Order quantity at which the first bulk price break applies\n  break_price — Unit price once at least break_qty is ordered\n  break_qty2 — Second bulk break quantity\n  break_price2 — Unit cost at the second break quantity\n  break_qty3 — Third bulk break quantity\n  break_price3 — Unit cost at the third break quantity\n  status — The vendor's lifecycle status for the entry\n  replacement — Vendor part number of the suggested successor when this entry is superseded\n  replacement_description — Description of the suggested replacement\n  last_price_change — When the vendor last changed pricing on this entry\n  last_qoh — Last reported quantity on hand AT THE VENDOR's warehouse — not in the shop\n  archived — True when the catalogue entry itself is archived\n  catalog_vendor — Raw catalogue-owner object\n  REFERENCES\n\nsource_lightspeed.ls_categories — one category node in the item category tree.\n  The hierarchical category tree used to organise items, structured like a directory.\n  primary key: category_id\n  category_id — Primary key of the node\n  name — The node's OWN name only, not its path (e.g. 'Service')\n  full_path_name — Slash-delimited path from the root to this node (e.g. 'Workshop/Service')\n  parent_id — The node directly above this one\n  node_depth — How many ancestors the node has: 0 = top level, 1 = one parent, and so on\n  left_node — Nested-set left bound\n  right_node — Nested-set right bound, the closing partner of left_node\n  create_time — When the node was created\n  time_stamp — When the node was last modified\n  REFERENCES\n\nsource_lightspeed.ls_images — one product image, attached to EITHER an item or a matrix (exactly one of the two).\n  Product photo metadata hosted on Lightspeed's Cloudinary account.\n  primary key: image_id\n  image_id — Primary key of the image record\n  item_id — The single item this photo belongs to, or NULL/0 when the photo is attached at matrix level instead. joins ls_items\n  item_matrix_id — The variant family this photo belongs to, or NULL/0 when it is attached to a single item. joins ls_item_matrices\n  description — Caption or alt text for the image\n  filename — Original filename of the upload\n  ordering — Display sequence among a product's images\n  public_id — The Cloudinary public id used to retrieve the image\n  REFERENCES\n\nsource_lightspeed.ls_item_attribute_sets — one attribute-set definition (the schema of a matrix's variant axes).\n  Tiny lookup that names what the attribute1/2/3 slots on items and matrices MEAN — e.g. attribute1 = Color, attribute2 = Size.\n  primary key: item_attribute_set_id\n  item_attribute_set_id — Primary key\n  name — Name of the set\n  attribute_name1 — Label for the first axis — documented as 'Color' or the generic 'Attribute 1'\n  attribute_name2 — Label for the second axis — documented as 'Size' or 'Attribute 2'\n  attribute_name3 — Label for the third axis — 'Attribute 3'\n  REFERENCES\n\nsource_lightspeed.ls_item_components — one component line: the link between one assembly/box item and one of the items it is made from.\n  The bill of materials for box and assembly products — which single items make up a box, and how many of each.\n  primary key: item_component_id\n  item_component_id — Primary key of the component line\n  assembly_item_id — The parent: the box or assembly item being built\n  component_item_id — The child: the single item consumed to build the parent\n  quantity — How many units of component_item_id it takes to build ONE assembly_item_id\n  component_group — Discriminates the two relationship kinds that share this table\n  REFERENCES\n\nsource_lightspeed.ls_item_fees — one configured item fee definition.\n  The configuration list of fixed-amount surcharges that attach to item categories — tyre recycling levies, e-bike environmental fees and similar.\n  primary key: item_fee_id\n  item_fee_id — Primary key of the fee definition\n  name — Fee name as shown at the register and on the receipt line\n  calculation_method — How the fee amount is derived\n  fee_value — The monetary amount of the fee in store currency\n  taxable — True when tax is charged ON the fee itself\n  discountable — Nominally whether the fee can be discounted, but documented as currently providing NO extra functionality. deprecated\n  non_refundable — Nominally whether the fee can be refunded; documented as currently not in use. deprecated\n  archived — True when the fee is retired and can no longer be used within a transaction\n  create_time — When the fee was configured — the earliest date its sale lines can appear\n  timestamp — When the fee was last updated\n  item_fee_categories — Raw list of the item categories the fee attaches to\n  REFERENCES\n\nsource_lightspeed.ls_item_matrices — one matrix — one variant family of items (e.g. one jersey that exists in five sizes).\n  The product-family layer above ls_items: family-level identity, defaults and the attribute set that defines the variant axes.\n  primary key: item_matrix_id\n  item_matrix_id — Primary key of the variant family\n  description — Family-level product name\n  item_type — Type default inherited by the family's items\n  serialized — True when units in this family carry serial numbers (typical for bike model families)\n  tax — Whether tax is charged on this family's items\n  default_cost — Family-level reorder cost, ex tax, used to seed inventory cost\n  model_year — Model year of the family (e.g. 2024)\n  archived — True when the family is retired\n  category_id — Category default for the family. joins ls_categories\n  tax_class_id — Tax class default for the family. joins ls_tax_classes\n  department_id — Legacy department grouping. deprecated\n  manufacturer_id — Brand of the family (who makes it), not the supplier. joins ls_manufacturers\n  season_id — Legacy season grouping; Seasons are deprecated by Lightspeed. deprecated. joins ls_seasons\n  default_vendor_id — Default supplier for the family\n  item_attribute_set_id — Which attribute-set definition shapes the family's variant axes (Color/Size, Size, Color, 3 Attributes). joins ls_item_attribute_sets\n  time_stamp — When the matrix record was last modified\n  attribute_name1 — Label of the family's first variant axis (typically 'Color'); pairs with ls_items.attribute_1 on the children\n  attribute_name2 — Label of the second variant axis (typically 'Size')\n  attribute_name3 — Label of the third variant axis; only meaningful for the '3 Attributes' set\n  tax_class — Raw tax-class object\n  department — Raw department object for the family. deprecated\n  custom_field_values — Raw account-defined custom field values on the matrix\n  REFERENCES\n  full_path_name\n  name\n\nsource_lightspeed.ls_item_prices — one price level amount on one item — the unique key is (item_id, use_type_id), not item_id alone.\n  Every configured price level for every item: Default, MSRP, Online and any account-defined level.\n  primary key: item_id, use_type_id\n  item_id — The item the price belongs to. joins ls_items\n  use_type_id — Numeric FK to the pricing level definition (ls_price_levels.price_level_id)\n  use_type — Human name of the price level, which also indicates how the level is applied\n  amount — The price at this level, in store currency, following the account's tax-inclusive setting (tax-inclusive jurisdictions: it INCLUDES tax, unlike costs…\n  REFERENCES\n  archived\n  description\n\nsource_lightspeed.ls_item_shops — one item's stock record at one location; shop_id = 0 is the account-wide aggregate, so use it alone for whole-business stock and only shop_id > 0 for per-shop breakdowns.\n  The current stock position per item per shop: quantity on hand, what is sellable, what is on order, and the reorder thresholds.\n  primary key: item_shop_id\n  item_shop_id — Primary key of this item-in-shop stock record\n  item_id — The item this stock row belongs to. joins ls_items\n  shop_id — The shop holding the stock — EXCEPT 0, which is documented as a summary record containing the QOH for all shops combined. joins ls_shops\n  qoh — Units physically on hand\n  sellable — Units the POS will let you sell: identical to qoh except it clamps at 0 when qoh is negative\n  backorder — Units already committed on a purchase order but not yet received — 'on order' in shop language\n  component_qoh — Additional units of this item that could be produced by breaking down or building up boxes/assemblies that are themselves in stock\n  component_backorder — Additional units obtainable from boxes/assemblies that are currently on order rather than in stock\n  reorder_point — Threshold: when qoh is at or below this, the item is considered due for reorder in this shop\n  reorder_level — Target stock level to reach when reordering: an automatic reorder adds (reorder_level - qoh) units\n  time_stamp — When this stock record last changed\n  description — Denormalised product name from the parent item, so stock rows are readable without a join\n  archived — Parent item's archived flag\n  item_type — Parent item type, carried here because non_inventory rows must be excluded from every stock count and valuation — their quantities are meaningless\n  avg_cost — Parent item's account-wide weighted average unit cost, ex tax\n  category_id — Parent item's category. joins ls_categories\n  manufacturer_id — Parent item's brand, for brand-level stock rollups without a join. joins ls_manufacturers\n  REFERENCES\n\nsource_lightspeed.ls_item_vendor_nums — one vendor-specific SKU: one item as catalogued by one vendor.\n  The cross-reference between the shop's items and the part numbers its suppliers use, with the per-vendor buy cost when vendor-cost functionality is enabled.\n  primary key: item_vendor_num_id\n  item_vendor_num_id — Primary key of the item-vendor cross-reference row\n  item_id — The shop's item this vendor SKU refers to. joins ls_items\n  vendor_id — The supplier that uses this SKU. joins ls_vendors\n  value — The vendor's own part number for the item — the string you put on a purchase order\n  cost — The buy cost from THIS vendor, ex tax\n  time_stamp — When this cross-reference row was last modified\n  REFERENCES\n\nsource_lightspeed.ls_items — one catalogue item — a single sellable SKU.\n  The product master: identity, SKUs/barcodes, categorisation, current price levels, cost basis and the flags that govern tax, discounting and stock behaviour.\n  primary key: item_id\n  item_id — Stable primary key of the SKU across the whole account; the join target for sale lines, stock rows, images, serial numbers and order lines\n  system_sku — The barcode Lightspeed generates and prints on shelf labels (e.g. 210000000004)\n  default_cost — Expected per-unit reorder cost from the supplier, EXCLUSIVE of tax\n  avg_cost — Weighted average unit cost of ALL purchases of this item ever, including stock already sold, EXCLUSIVE of tax\n  tax — True when sales tax/GST is charged on this item at the register\n  archived — True when the item has been retired\n  discountable — True when cashiers may apply a discount to this line at the register\n  item_type — What kind of thing the SKU is, which decides whether its stock number means anything\n  serialized — True when every unit gets a serial number captured at sale\n  description — The product name printed on receipts and labels\n  model_year — Model year of the product (e.g. 2008, 2024). deprecated\n  upc — UPC barcode, 11-14 digits\n  ean — EAN barcode, 11-14 digits — the international sibling of upc, usually empty when upc is populated\n  custom_sku — The shop's own internal SKU, entered by staff\n  manufacturer_sku — The manufacturer's own part number\n  time_stamp — When the item RECORD was last edited\n  create_time — When the SKU was first created in the catalogue\n  publish_to_ecom — Flag requesting publication to Lightspeed eCom\n  category_id — The single category node this item hangs off, at any depth of the tree. joins ls_categories\n  tax_class_id — Which tax class governs the item's rate. joins ls_tax_classes\n  department_id — Legacy department grouping. deprecated\n  item_matrix_id — The variant family this SKU belongs to: all sizes/colours of one product share it. joins ls_item_matrices\n  manufacturer_id — Who MAKES the product (brand). joins ls_manufacturers\n  season_id — Legacy season grouping. deprecated. joins ls_seasons\n  default_vendor_id — The supplier the shop reorders this item from by default\n  tax_class — Raw tax-class object as returned\n  note — Raw note object attached to the item (staff notes; public notes also print on receipts)\n  custom_field_values — Raw account-defined custom field values\n  attribute1 — First variant axis VALUE for a matrix item, conventionally the colour\n  attribute2 — Second variant axis value, conventionally the size\n  attribute3 — Third variant axis value; only used by the '3 Attributes' attribute set\n  item_attribute_set_id — Which attribute-set definition explains this item's attribute_1/2/3. joins ls_item_attribute_sets\n  attribute_name1 — Label for variant axis 1 (typically 'Color')\n  attribute_name2 — Label for variant axis 2 (typically 'Size')\n  attribute_name3 — Label for variant axis 3 ('Attribute 3')\n  item_e_commerce_id — Id of the item's eCommerce info record\n  long_description — Long-form marketing copy for the item\n  short_description — Short marketing blurb\n  weight — Item weight\n  width — Item width, unitless per the API — same unit caveat as weight\n  height — Item height, unitless per the API\n  length — Item length, unitless per the API\n  list_on_store — Whether the item is flagged to be sold online\n  amount_where_use_type_default — TODAY's shelf/register selling price at the Default price level\n  amount_where_use_type_msrp — Manufacturer's suggested retail price level\n  REFERENCES\n  full_path_name\n  name\n\nsource_lightspeed.ls_manufacturers — one manufacturer (brand).\n  The brand list: who MAKES the products.\n  primary key: manufacturer_id\n  manufacturer_id — Primary key of the brand\n  name — Brand name\n  create_time — When the brand was added to the account\n  time_stamp — When the brand record was last modified (typically a rename)\n  REFERENCES\n\nsource_lightspeed.ls_options — one account option: a name/value pair the account has turned on.\n  The account's feature switches as name/value strings.\n  primary key: name\n  name — The option's identifier\n  value — The option's value, always delivered as a string even when it represents a boolean or a number\n  REFERENCES\n\nsource_lightspeed.ls_price_levels — one price level definition on the account.\n  The definitions behind the price levels that ls_item_prices rows reference: their names, whether they are archived, their type, and the calculation parameters used to derive prices from cost.\n  primary key: price_level_id\n  price_level_id — Primary key of the price level\n  name — Display name of the level (Default, MSRP, Online, or an account-defined label)\n  archived — True when the level is retired\n  can_be_archived — Whether Lightspeed permits archiving this level — false on built-in levels such as Default\n  type — The kind of price level\n  calculation — Raw parameters used to derive a price from cost (markup/margin rules)\n  REFERENCES\n\nsource_lightspeed.ls_seasons — one season label.\n  Legacy organiser: season labels that older accounts used to group items.\n  primary key: season_id\n  season_id — Primary key of the season label. deprecated\n  name — The season's label text. deprecated\n  REFERENCES\n\nsource_lightspeed.ls_serialized — one serial-number record — one physical serialized unit, whether it came from stock or was logged as a customer's own property.\n  The register of serialized units: bikes, frames, e-bikes and anything else tracked by serial number.\n  primary key: serialized_id\n  serialized_id — Primary key of the serial record\n  serial — The serial number stamped on the unit\n  description — Free-text identity used when the record is NOT connected to a catalogue item — typically a customer's own bike ('black planet x')\n  color_name — Colour of the unit as typed by staff\n  size_name — Size of the unit (frame size for bikes) as typed by staff\n  item_id — The catalogue item this serial is an instance of, when the unit was sold from stock. joins ls_items\n  sale_line_id — The sale line where this unit was sold, or 0/NULL if it never went through the POS. joins ls_sale_lines\n  customer_id — The customer who owns this unit. joins ls_customers\n  time_stamp — When the record last changed\n  REFERENCES\n\nsource_lightspeed.ls_tag_groups — one tag group name for the account.\n  Helper list of the tag groups configured on the account.\n  primary key: name\n  name — The tag group's name\n  REFERENCES\n\nsource_lightspeed.ls_tags — one tag in the account's tag vocabulary.\n  The list of tags staff can attach to items and matrices for ad-hoc grouping.\n  primary key: tag_id\n  tag_id — Primary key of the tag\n  name — The tag text itself\n  REFERENCES",
  "customers": "source_lightspeed.ls_contact_emails — one row per email address held on a contact.\n  The multi-valued email addresses of a contact, one row each, with the documented Primary/Secondary use type.\n  primary key: contact_id, contact_email\n  contact_id — Owning contact block. joins ls_contacts\n  contact_email — Zero-based position of this address inside the parent's email container, needed only because the API gives email entries no id of their own\n  address — The email address itself\n  use_type — Which slot this address occupies: Primary or Secondary\n  REFERENCES\n\nsource_lightspeed.ls_contact_phones — one row per phone number held on a contact.\n  The multi-valued phone numbers of a contact, one row each, tagged with the documented Home/Work/Mobile/Pager/Fax use type.\n  primary key: contact_id, contact_phone\n  contact_id — Owning contact block. joins ls_contacts\n  contact_phone — Zero-based position within the parent's phone container; phone entries carry no id of their own\n  number — The phone number exactly as typed: spaces, dashes, brackets and missing country codes all occur\n  use_type — What kind of number this is: Home, Work, Mobile, Pager or Fax\n  REFERENCES\n\nsource_lightspeed.ls_contact_websites — one row per website URL held on a contact.\n  The multi-valued website URLs attached to a contact.\n  primary key: contact_id, contact_website\n  contact_id — Owning contact block. joins ls_contacts\n  contact_website — Zero-based position within the parent's website container; website entries carry no id\n  url — The URL as typed\n  REFERENCES\n\nsource_lightspeed.ls_contacts — one row per Contact record (the single contact block attached to a Customer, CreditAccount or ShipTo).\n  The shared contact block: exactly one postal address plus the three marketing opt-out flags, and the parent of the multi-valued email, phone and website child tables.\n  primary key: contact_id\n  contact_id — Unique numeric id of the contact block\n  address1 — The contact's street address, first line\n  address2 — Second address line: apartment, suite, unit, care-of\n  city — Postal address city or suburb, free text and unnormalised (spelling and case vary), so group with lower(trim(city)) for catchment analysis\n  state — Postal address state/province as free text, e.g. 'Victoria'\n  state_code — ISO code for the state/province, e.g. 'VIC'\n  zip — Postal/zip code\n  country — Postal address country as free text; often the store's own country by default rather than a deliberate entry\n  country_code — ISO code for the country\n  no_email — True when the contact has opted OUT of email messages\n  no_mail — True when the contact has opted OUT of postal mail\n  no_phone — True when the contact has opted OUT of phone calls\n  time_stamp — Last modification of the contact block\n  REFERENCES\n  contact\n  ship_to_id — joins ls_ship_tos\n\nsource_lightspeed.ls_credit_accounts — one row per credit account: either a customer store account or a gift card.\n  Two different instruments share this endpoint and this table.\n  primary key: credit_account_id\n  credit_account_id — Unique numeric id of the credit account or gift card\n  name — Label for the account\n  code — For gift cards, the barcode or numeric id scanned at the point of sale; documented as 8 to 32 characters and empty for customer credit accounts\n  description — Free-text description of the account, typically empty\n  gift_card — True = a gift card (bearer code with monetary value, no customer), false = a customer store account\n  archived — True when the account is archived\n  customer_id — Foreign key to the owning customer. joins ls_customers\n  balance — Current balance in store currency, signed from the STORE'S receivable viewpoint per the official reference: POSITIVE = the customer owes the store (o…\n  contact_id — Contact block attached to the account, available only when the Contact relation is requested. joins ls_contacts\n  time_stamp — Last modification of the record, which in practice means the last time the balance moved\n  REFERENCES\n\nsource_lightspeed.ls_custom_field_choices — one row per selectable option on a single_choice or multi_choice custom field.\n  The picklist options behind choice-typed custom fields: the option's id, its display name, an optional distinct stored value, and whether it can still be deleted.\n  primary key: custom_field_choice_id\n  custom_field_choice_id — Unique numeric id of the choice\n  custom_field_id — Foreign key to the owning custom field definition in ls_custom_fields. joins ls_custom_fields\n  name — The label shown to staff for this option\n  value — An optional stored string value that differs from the display name (e.g. name 'Gold Member', value 'GOLD')\n  can_be_deleted — False when the choice is in use somewhere and therefore cannot be removed\n  time_stamp — Last modification of the choice\n  REFERENCES\n\nsource_lightspeed.ls_custom_fields — one row per custom field definition available on customers.\n  The schema for store-defined customer attributes: name, data type, units, rounding precision, archive state and default value.\n  primary key: custom_field_id\n  custom_field_id — Unique numeric id of the custom field definition\n  type — The declared data type, which controls both the validation applied on write and how the stored value must be parsed on read\n  name — The label staff see for the field\n  uom — Unit of measure for the field, up to four characters (e.g. 'kg', 'cm')\n  decimal_precision — Number of decimal places floats are rounded to\n  archived — True when the field definition is archived\n  default — The default CustomFieldValue applied when the field is first set, typed according to type (so it may be a scalar or a CustomFieldChoice object — stor…\n  REFERENCES\n\nsource_lightspeed.ls_customer_custom_field_values — one row per custom field value recorded on one customer.\n  The store-defined attributes actually recorded against customers: one row per (customer, custom field) pair, carrying the value plus a snapshot of the field's name and type at read time.\n  primary key: custom_field_value_id\n  custom_field_value_id — Primary key of this individual value record\n  customer_id — The customer this value belongs to, taken from the parent record the relation was loaded on. joins ls_customers\n  custom_field_id — Foreign key to the field definition in ls_custom_fields. joins ls_custom_fields\n  name — The field's name copied onto the value for convenience\n  type — The field's type copied onto the value, also only updatable on the definition\n  value — The stored value, preserved as JSON because its shape depends on the field type: a scalar for string/text/url/email/integer/float/boolean/date/dateti…\n  custom_field_choice_id — For single_choice fields, the selected choice id lifted out of value_raw so it can be joined to ls_custom_field_choices. joins ls_custom_field_choices\n  deleted — The delete flag: setting it true on an update of the parent is how a value is removed\n  time_stamp — Last modification of this value\n  REFERENCES\n\nsource_lightspeed.ls_customer_notes — one row per note attached to a customer.\n  Free-text notes staff attach to a customer record, with a flag controlling whether the text is printed on receipts.\n  primary key: note_id\n  note_id — Unique numeric id of the note\n  customer_id — The customer this note hangs off, taken from the parent record the relation was loaded on. joins ls_customers\n  note — The note text\n  is_public — True when the note is shown on receipts and other customer-facing output; false when it is internal-only\n  time_stamp — Last modification of the note\n  REFERENCES\n\nsource_lightspeed.ls_customer_types — one row per customer type (segment definition).\n  Lookup of customer segments such as VIP, Club, Wholesale or Staff.\n  primary key: customer_type_id\n  customer_type_id — Unique numeric id of the segment\n  name — Description/name of the customer type as shown in the POS Type field\n  tax_category_id — Foreign key to the TaxCategory automatically applied at the register when a customer of this type is attached — the mechanism behind tax-exempt segme…. joins ls_tax_categories\n  discount_id — Foreign key to the Discount automatically applied at the register for this type. joins ls_discounts\n  REFERENCES\n\nsource_lightspeed.ls_customers — one row per Customer record (one POS customer identity, account-wide, not one human being).\n  The CRM master record: names, company/tax identifiers, date of birth, archive state, and the foreign keys that drive register behaviour (customer type, discount, tax category, store credit account).\n  primary key: customer_id\n  customer_id — Unique numeric id of this POS customer identity\n  first_name — Customer's given name\n  last_name — Customer's family name\n  dob — Documented as the customer's date of birth, stored as a datetime at store-local midnight, so only the date part is meaningful\n  archived — True when the customer has been archived\n  title — The customer's JOB title (e.g. Purchasing Manager) — not an honorific like Mr/Ms, and not a record label\n  company — Name of the company this customer belongs to\n  company_registration_number — The customer's company registration number (ABN/company number depending on locale)\n  vat_number — The customer's VAT/GST registration number, as text\n  create_time — When the customer record was created, i.e. when this identity first entered the system\n  time_stamp — Last modification of the record\n  credit_account_id — Foreign key to the customer's store credit account in ls_credit_accounts. joins ls_credit_accounts\n  customer_type_id — Foreign key to ls_customer_types (the segment: VIP, Club, Wholesale, Staff...). joins ls_customer_types\n  discount_id — Foreign key to the Discount (pricing domain) auto-applied at the register for this customer. joins ls_discounts\n  tax_category_id — Foreign key to the TaxCategory (tax domain, canonical tax_code) that overrides normal tax for this customer, e.g. tax-exempt bodies or export custome…. joins ls_tax_categories\n  contact_id — Id of the Contact block carrying this customer's emails, phones, postal address and marketing opt-outs. joins ls_contacts\n  contact — Raw Contact subtree kept verbatim for anything the normalised tables do not flatten\n  custom_field_values — Raw CustomFieldValues subtree, NULL when the customer has none\n  REFERENCES\n\nsource_lightspeed.ls_ship_tos — one row per ShipTo record (one shipment destination created for a sale that needs sending).\n  The store's shipping queue and history: a record is created when a sale has to be shipped to the customer, carrying the recipient name, a free-text note, the shipped flag and the destination address via the Contact rela….\n  primary key: ship_to_id\n  ship_to_id — Unique numeric id of the shipment record\n  shipped — True once the parcel has gone out, false while it still needs to ship\n  ship_note — Free-text delivery instructions for the parcel (leave at door, call on arrival, gift message)\n  first_name — Recipient's first name for this shipment\n  last_name — Recipient's last name for this shipment\n  customer_id — Foreign key to the customer this shipment is for. joins ls_customers\n  sale_id — Foreign key to the sale being shipped. joins ls_sales\n  time_stamp — Last modification of the shipment record\n  contact — The destination address, i.e. where the parcel is going, taken from the Contact relation\n  contact_id — Id of the destination contact block; join to ls_contacts.contact_id where owner_object = 'ShipTo' for a normalised address. joins ls_contacts\n  REFERENCES",
  "inventory": "source_lightspeed.ls_inventory_count_calcs — one item within one inventory count (the system-vs-physical rollup for that item/count pair).\n  The scoreboard of a stocktake: for each item in a count, what the system thought was on hand (calc_qoh) versus what people physically found (counted_qoh).\n  primary key: inventory_count_calc_id\n  inventory_count_calc_id — Unique id of this item's rollup within a count\n  time_stamp — Modified date/time of this rollup: the last time a count entry was recorded for THIS item in THIS count\n  calc_qoh — What the system believed the business should have in stock — the 'book' side of the variance\n  counted_qoh — The physical amount counted — the sum of every ls_inventory_count_items.qty entry for this item in this count\n  inventory_count_id — The stocktake this rollup belongs to\n  item_id — The item this rollup is for. joins ls_items\n  REFERENCES\n\nsource_lightspeed.ls_inventory_count_items — one physical counting act — one item counted once by one employee at one moment (counting the same item three times creates three rows).\n  The keystroke-level record of a stocktake: each quantity an employee entered, when, for which item.\n  primary key: inventory_count_item_id\n  inventory_count_item_id — Unique id of this single count entry\n  qty — The quantity found in this one counting act\n  time_stamp — The date/time at which the count was made\n  inventory_count_id — The stocktake this entry belongs to\n  item_id — The item that was counted. joins ls_items\n  employee_id — Employee who physically made this count entry. joins ls_employees\n  REFERENCES\n\nsource_lightspeed.ls_inventory_count_reconciles — one reconcile posting — one item's stock and cost adjustment applied when a count was reconciled.\n  The posted result of a stocktake: the adjustment actually written to the books for each item, in units and in cost value.\n  primary key: inventory_count_reconcile_id\n  inventory_count_reconcile_id — Unique id of this reconcile posting\n  create_time — When the reconcile was performed — the moment the books actually moved\n  cost_change — The cost VALUE of the adjustment: the amount lost (negative) or gained (positive) to the books for this item, ex tax, in store currency\n  qoh_change — The stock-level change applied by the reconcile: negative means the count found FEWER units than the books claimed (shrinkage written off), positive…\n  inventory_count_id — The stocktake being reconciled\n  item_id — The item adjusted. joins ls_items\n  REFERENCES\n\nsource_lightspeed.ls_inventory_logs — one inventory change event — one item's stock level changing in one shop, for one reason, at one moment.\n  The inventory movement ledger: every stock change with why it happened (sale, purchase-order receive, transfer, manual adjustment, stocktake correction, refund, auto-add, bulk import) and who caused it.\n  primary key: inventory_log_id\n  inventory_log_id — Unique id of the movement event\n  create_time — When the stock change happened, store-local time\n  qoh_change — Units added (positive) or removed (negative) by this event\n  cost_change — Despite the '-Change' name this is NOT a delta: documented as 'the updated unit cost for the Item', i.e. the item's unit cost AFTER this event, ex ta…\n  automated — true when Lightspeed itself made the change (a sale deducting stock, a PO receive posting); false when a human typed an adjustment\n  reason — Machine-named cause of the change\n  caused_negative — true when this specific event pushed the item's on-hand below zero in that shop — the exact moment an oversell happened\n  employee_id — Employee who made or triggered the change. joins ls_employees\n  item_id — Item whose stock changed. joins ls_items\n  shop_id — Shop where the change happened; 0/NULL means unattributed. joins ls_shops\n  order_id — Purchase order whose receiving caused the change. joins ls_purchase_orders\n  transfer_id — Inter-shop transfer that caused the change. joins ls_transfers\n  sale_id — Sale that caused the change. joins ls_sales\n  inventory_count_id — Stocktake that caused the change\n  customer_id — Customer associated with the change — set on special-order and layaway reservation movements. joins ls_customers\n  vendor_return_id — Vendor return (RMA) that caused the change: stock sent back to a supplier, so qoh_change is normally negative. joins ls_vendor_returns\n  item_import_id — Bulk item import that caused the change — a spreadsheet load setting stock levels\n  REFERENCES\n\nsource_lightspeed.ls_special_orders — one special order — one item a named customer asked the shop to bring in, tracked from the sale line it was raised on to the purchase order line or transfer that fulfils it.\n  Customer special orders: a customer wants something the shop does not stock, the shop optionally takes a deposit and orders it in.\n  primary key: special_order_id\n  special_order_id — Unique id of the special order\n  unit_quantity — How many units the customer asked the shop to bring in\n  contacted — true once someone has told the customer their special order has arrived\n  completed — true when the special order has been closed out (collected and rung up on the originating sale line)\n  customer_id — The customer waiting for the item. joins ls_customers\n  shop_id — Shop where the special order was raised and where the customer will collect. joins ls_shops\n  sale_line_id — The sale line the special order was started from and where it will be completed — the customer's side of the deal, carrying the price, deposit and sa…. joins ls_sale_lines\n  order_line_id — The purchase order line where the item is being bought from the supplier — the supply side. joins ls_purchase_order_lines\n  transfer_item_id — The transfer line fulfilling this special order when another shop supplies it rather than a supplier. joins ls_transfer_items\n  REFERENCES\n\nsource_lightspeed.ls_transfer_from — one origin record for one stock transfer.\n  The sending side of a stock transfer.\n  primary key: transfer_from_id\n  transfer_from_id — Primary key of the origin record\n  REFERENCES\n\nsource_lightspeed.ls_transfer_items — one line on one transfer — one item on one inter-shop transfer document.\n  The lines of an inter-shop transfer: which item, how many were meant to go, how many actually left, how many the destination counted, how many landed, and the cost value on each side.\n  primary key: transfer_item_id\n  transfer_item_id — Unique id of this transfer line\n  transfer_id — The transfer document this line belongs to. joins ls_transfers\n  item_id — The item being transferred. joins ls_items\n  to_send — The quantity the origin shop INTENDS to send — the picking instruction\n  to_receive — The quantity the receiving shop has counted as received during check-in\n  sent — The actual number dispatched from the origin shop\n  received — The actual number that landed at the destination\n  sent_value — TOTAL inventory cost value of the quantity sent, ex tax, in store currency — not a unit cost\n  received_value — TOTAL inventory cost value of the quantity received, ex tax\n  comment — Free-text note on the line — usually where staff explain a short shipment or damage\n  time_stamp — Last modification to this line, store-local\n  REFERENCES\n\nsource_lightspeed.ls_transfer_to — one destination record for one stock transfer.\n  The receiving side of a stock transfer, mirroring ls_transfer_from.\n  primary key: transfer_to_id\n  transfer_to_id — Primary key of the destination record\n  REFERENCES\n\nsource_lightspeed.ls_transfers — one inter-shop transfer document (header), with its origin-side and destination-side records flattened in.\n  Transfers of stock between shops: one row per transfer document, carrying whether it has been sent and received, which shops and staff were on each end, and the send/receive dates.\n  primary key: transfer_id\n  transfer_id — Unique id of the transfer document\n  sent — true once the origin store has dispatched the transfer\n  received — true once the receiving store has checked the transfer in\n  note — Free-text note for the store\n  archived — true when the transfer is filed away as done\n  transfer_from_id — Key of the origin-side sub-record whose three payload fields are flattened onto this row as sent_on, sent_by_employee_id and from_shop_id. joins ls_transfer_from\n  transfer_to_id — Key of the destination-side sub-record, flattened onto this row as need_by, received_by_employee_id and to_shop_id. joins ls_transfer_to\n  order_id — Purchase Order this transfer was attached to for centralized ordering (head office buys once, then transfers stock out to shops). joins ls_purchase_orders\n  sent_on — Date/time the transfer left the origin shop\n  employee_id — Employee who sent the transfer from the origin shop. joins ls_employees\n  shop_id — Origin shop — where the stock leaves. joins ls_shops\n  need_by — OVERLOADED, exactly as documented: while pending it is the date the transfer must be received BY; once received it is the date it WAS received\n  time_stamp — Last modification to the transfer record, store-local\n  REFERENCES",
  "org": "source_lightspeed.ls_account — one row -- the Lightspeed Retail (R-Series) account associated with the access token (singleton).\n  The merchant account itself: its id, trading name, subscription status, employee licence usage and base currency.\n  primary key: account_id\n  account_id — The account's unique id\n  name — The merchant account name, i.e. the business as Lightspeed bills it\n  link — Self-referencing API URL for this account resource, as returned in the example payload\n  system_customer_id — Lightspeed's platform-level identifier for the merchant, the same value as Session.systemCustomerID\n  status — Subscription/lifecycle state of the account\n  employee_count — Number of employees counted against the account's licence\n  employee_limit — Maximum employees the account's plan permits\n  unique_subscription_identifier — Opaque identifier of the billing subscription behind the account, from the example payload\n  code — ISO code of the account's BASE currency (USD, CAD, AUD...)\n  symbol — Display symbol for the base currency ($, £, €)\n  REFERENCES\n\nsource_lightspeed.ls_account_purchasing_currencies — one row per purchasing currency enabled on the account.\n  The non-base currencies the account is configured to PURCHASE in (i.e. buy stock from overseas suppliers), each with the exchange rate recorded against it.\n  primary key: account_id, code\n  account_id — The account these purchasing currencies belong to, carried down from the parent Account object. joins ls_account\n  code — ISO code of a currency the account may raise purchase orders in (USD, EUR...)\n  symbol — Display symbol for the purchasing currency\n  rate — Exchange rate recorded for this purchasing currency\n  REFERENCES\n\nsource_lightspeed.ls_cc_gateways — one row per legacy credit-card gateway configuration referenced by a shop.\n  Legacy per-shop credit-card gateway setup: which processor, its credentials, terminal/market identifiers, enabled and test-mode switches, and the mapping from card brands to PaymentType ids.\n  primary key: cc_gateway_id\n  cc_gateway_id — Unique numeric id of the gateway configuration\n  gateway — Name of the payment gateway/processor this shop is wired to\n  enabled — True when the gateway is switched on\n  test_mode — True when the gateway is in test/sandbox mode\n  allow_credits — Whether credit-card charges (credits back to a card) are permitted through this gateway\n  market_type — Market type value sent in the transaction XML (retail, e-commerce, MOTO and similar processor-defined categories)\n  device_type — Numeric code for the type of device used to process card transactions\n  terminal_num — Terminal ID sent in the transaction XML\n  login — Gateway credential (merchant login)\n  trans_key — Gateway credential (transaction key)\n  account_num — Gateway credential (merchant account number)\n  hash_value — MD5 hash used to validate the transaction\n  other_credentials1 — Spare credential slot, used when a processor needs a field beyond login/transKey/accountNum\n  other_credentials2 — Second spare credential slot\n  visa_payment_type_id — PaymentType id that Visa transactions on this gateway are recorded against (/Account/{accountID}/PaymentType/{visaPaymentTypeID})\n  master_payment_type_id — PaymentType id used for MasterCard transactions on this gateway (/Account/{accountID}/PaymentType/{masterPaymentTypeID})\n  discover_payment_type_id — PaymentType id used for Discover Card transactions (/Account/{accountID}/PaymentType/{discoverPaymentTypeID})\n  american_payment_type_id — PaymentType id used for American Express transactions (/Account/{accountID}/PaymentType/{americanPaymentTypeID})\n  debit_payment_type_id — PaymentType id used for debit-card transactions (/Account/{accountID}/PaymentType/{debitPaymentTypeID})\n  REFERENCES\n\nsource_lightspeed.ls_currency_denominations — one physical currency denomination available in a locale.\n  The note and coin denominations defined for a locale.\n  primary key: locale_id, currency_denominations\n  locale_id — Owning locale\n  currency_denominations — Face value of the note or coin in the locale currency\n  REFERENCES\n\nsource_lightspeed.ls_currency_rates — one row per foreign currency exchange rate the merchant maintains.\n  Manually maintained foreign-exchange rates used for multi-currency work.\n  primary key: currency_rate_id\n  currency_rate_id — Unique numeric id of the rate record (/Account/{accountID}/CurrencyRate/{currencyRateID})\n  currency_code — ISO currency code the rate applies to (USD, CAD...)\n  rate — Exchange rate of the given currency relative to the account's base currency, documented as (given currency / account currency)\n  create_time — When the currency-rate record was created, in the shop's timezone\n  time_stamp — When the rate record was last modified, in the shop's timezone\n  REFERENCES\n\nsource_lightspeed.ls_employee_hours — one row per clock-in/clock-out entry for one employee at one shop.\n  Time-clock entries recorded when employees clock in and out of the POS.\n  primary key: employee_hours_id\n  employee_hours_id — Unique numeric id of the clock entry (/Account/{accountID}/EmployeeHours/{employeeHoursID})\n  check_in — Start of the clock-in entry, in the shop's timezone\n  check_out — End of the clock-in entry, in the shop's timezone\n  employee_id — Foreign key to the Employee this entry belongs to (/Account/{accountID}/Employee/{employeeID}). joins ls_employees\n  shop_id — Foreign key to the Shop where the clock in/out physically happened (/Account/{accountID}/Shop/{shopID}). joins ls_shops\n  REFERENCES\n\nsource_lightspeed.ls_employee_rights — one row per (employee, right) grant made directly to an employee -- effective only when that employee has no role.\n  Per-employee rights, exploded from the EmployeeRights collection nested directly under Employee.\n  primary key: employee_id, employee_right_id\n  employee_id — The employee the right is attached to directly, carried down from the parent Employee object. joins ls_employees\n  employee_right_id — Unique numeric id of the right/privilege, from the same catalogue as ls_employee_role_rights.employee_right_id\n  name — The right's name as Lightspeed defines it\n  REFERENCES\n\nsource_lightspeed.ls_employee_role_rights — one row per (role, right) grant -- one right conferred by one role.\n  The bridge between a role and the individual rights/privileges it confers, exploded from the EmployeeRights collection nested under EmployeeRole.\n  primary key: employee_role_id, employee_right_id\n  employee_role_id — The role conferring this right, carried down from the parent EmployeeRole object during the explode. joins ls_employee_roles\n  employee_right_id — Unique numeric id of the right/privilege\n  name — The right's name as Lightspeed defines it (e.g. discount-application, void, price-override, reporting access)\n  REFERENCES\n\nsource_lightspeed.ls_employee_roles — one row per employee role defined on the account.\n  Named permission roles (e.g. Manager, Sales Associate) that bundle a set of rights and are assigned to employees via Employee.employeeRoleID.\n  primary key: employee_role_id\n  employee_role_id — Unique numeric id for the role\n  name — Display name of the role as configured by the merchant (e.g. 'Manager', 'Cashier')\n  REFERENCES\n\nsource_lightspeed.ls_employees — one row per employee login on the account, including archived former staff.\n  Biographical and account-login information for staff: names, lock-out and archive state, which role (and therefore which rights) they hold, which shop they are restricted to, and a set of live 'currently attached to' po….\n  primary key: employee_id\n  employee_id — Unique numeric id for the staff login\n  first_name — Employee's given name\n  last_name — Employee's family name\n  lock_out — True when the employee is locked out of the system and cannot log in to the POS\n  archived — True for former staff\n  contact_id — Foreign key to the Contact record with the employee's phone, email and address. joins ls_contacts\n  clock_in_employee_hours_id — Foreign key to the EmployeeHours record the employee is CURRENTLY clocked in under (/Account/{accountID}/EmployeeHours/{clockInEmployeeHoursID})\n  employee_role_id — Foreign key to the employee's role, which specifies their rights. joins ls_employee_roles\n  limit_to_shop_id — Foreign key to the single Shop this login is restricted to (/Account/{accountID}/Shop/{limitToShopID})\n  last_shop_id — The shop the employee is currently -- or was most recently -- attached to (/API/Account/Shop/{lastShopID})\n  last_sale_id — The sale the employee is currently, or was last, working on (/Account/{accountID}/Sale/{lastSaleID})\n  last_register_id — The register the employee is currently, or was last, attached to (/Account/{accountID}/Register/{lastRegisterID})\n  time_stamp — When the employee record was last modified, in the shop's timezone\n  contact — The employee's full Contact record from load_relations=Contact: Phones.ContactPhone, Emails.ContactEmail, Addresses.ContactAddress\n  REFERENCES\n\nsource_lightspeed.ls_industries — one row per Lightspeed catalog industry vertical, with its enabled state for this account.\n  Lightspeed's built-in retail verticals (Bicycles, Jewelry, Pet, Golf...) and whether each is switched on for this account.\n  primary key: industry_id\n  industry_id — Unique numeric id for the industry vertical\n  name — Name of the industry vertical (Bicycles, Skateboards, Motorcycles...)\n  enabled — True when the vertical is switched on for THIS account\n  REFERENCES\n\nsource_lightspeed.ls_locales — one row per locale Lightspeed publishes globally (a global catalogue, not the account's own setting).\n  The global list of locales available across Lightspeed and their formatting/currency attributes: currency symbol and code, decimal precision, cash-rounding increment, tax naming, date formats and language tag.\n  primary key: name\n  name — Name of the locale\n  country — Country the locale belongs to\n  states — States/provinces within the locale, published as a string rather than a structured collection\n  currency_symbol — Currency symbol used for display in this locale\n  currency_code — ISO currency code of the locale\n  currency_precision — Number of decimal places the currency is stored/displayed to\n  cash_rounding_precision — Smallest unit of currency actually used in CASH transactions -- e.g. 0.05 where 1c and 2c coins were withdrawn (AU, CA, NZ)\n  include_tax_on_labels — Whether product labels in this locale print tax-inclusive prices\n  language_tag — Language tag per ISO 639-1 (e.g. 'en', 'fr')\n  date_format — Date format string for the locale, in the API's own format syntax (e.g. 'd/m/Y' style PHP tokens, not strftime and not ISO)\n  datetime_format — Date-and-time format string for the locale, same token syntax caveat as date_format\n  tax_name1 — Name of the locale's first tax (GST, VAT, State Tax, TPS...)\n  tax_name2 — Name of the locale's second tax, for two-tier regimes such as Canadian GST + PST/QST\n  currency_denominations — The locale's note and coin denominations, kept as a JSON blob\n  REFERENCES\n\nsource_lightspeed.ls_receipt_setups — one row per receipt setup configuration referenced by a shop.\n  Receipt print configuration: the header block, the general footer message, the workorder and credit-card agreement texts, and the logo image with its pixel dimensions.\n  primary key: receipt_setup_id\n  receipt_setup_id — Unique numeric id of the receipt configuration\n  header — Text printed at the TOP of the receipt\n  general_msg — General text printed at the end of ALL receipts (return policy, thanks, opening hours)\n  workorder_agree — Text printed at the end of workorder receipts, invoices and quotes only\n  creditcard_agree — Text printed at the end of a sales receipt that includes credit-card charges -- the cardholder agreement/signature wording\n  logo — RELATIVE URL of the logo image file, not an absolute URL and not the image bytes\n  logo_height — Logo image height in PIXELS as stored, not print millimetres\n  logo_width — Logo image width in PIXELS\n  REFERENCES\n\nsource_lightspeed.ls_registers — one row per point-of-sale register (till) configured on the account.\n  A Register is a single point of sale -- a place where money is received -- and each register keeps a separate cash count per payment type.\n  primary key: register_id\n  register_id — Unique numeric id for the till\n  name — Human label for the till as shown in the POS, e.g. 'Front Register', 'Counter'\n  open — True when the till is open for trading AT THE MOMENT THE ROW WAS FETCHED\n  open_time — When the CURRENT session was opened, in the shop's timezone\n  tip_enabled — True when the Tipping feature is permitted on this register\n  open_employee_id — Foreign key to the Employee who opened the current session (/Account/{accountID}/Employee/{openEmployeeID})\n  shop_id — Foreign key to the Shop this register physically sits in (/Account/{accountID}/Shop/{shopID}). joins ls_shops\n  REFERENCES\n\nsource_lightspeed.ls_session — one row -- the identity behind the access token currently in use (singleton).\n  Describes the current API session derived from the access token: which employee granted it, which account and API client it belongs to, and a couple of account-wide facts (shop count, linked eCom URL).\n  primary key: system_api_key_id\n  session_id — Legacy cookie-session identifier. deprecated\n  session_cookie — Legacy cookie-session value. deprecated\n  employee_id — Foreign key to the Employee who granted the access token (/Account/{accountID}/Employee/{employeeID}). joins ls_employees\n  system_customer_id — The account ID (/Account/{accountID})\n  system_user_id — The employee's identifier at the Lightspeed platform level, unique ACROSS ALL ACCOUNTS -- unlike employeeID, which is only unique within one account\n  system_api_client_id — Unique identifier of the API client (the registered application) associated with the access token\n  system_api_key_id — Unique identifier of the access token itself\n  ecom_url — URL of the associated Lightspeed eCom (C-Series) store, if the account has one linked\n  shop_count — Number of shops on the account, as counted by the platform\n  REFERENCES\n\nsource_lightspeed.ls_shops — one row per shop (physical store location) on the account, including archived ones.\n  The physical store locations on the account.\n  primary key: shop_id\n  shop_id — Unique numeric id for the store location\n  name — Store name as it appears on receipts, labels and in the POS shop picker\n  service_rate — Default hourly labour/service rate for this location, in the account's base currency (Account.defaultCurrency.code)\n  time_zone — The store's IANA timezone\n  tax_labor — True when service/labour lines at this shop attract sales tax\n  label_title — What heading is printed at the top of product labels for this shop\n  label_msrp — True when a product label should also print the MSRP, but only for items where MSRP is filled in AND MSRP exceeds this shop's own selling price\n  archived — True when the location has been archived (closed down / retired)\n  contact_id — Foreign key to the Contact record holding the store's street address, phone, email and website. joins ls_contacts\n  tax_category_id — Foreign key to the TaxCategory this shop applies to new sales by default (/Account/{accountID}/TaxCategory/{taxCategoryID}). joins ls_tax_categories\n  receipt_setup_id — Foreign key to the ReceiptSetup record (header/footer text and logo) used by this shop. joins ls_receipt_setups\n  cc_gateway_id — Foreign key to the LEGACY credit-card gateway configuration for this shop (ls_cc_gateways). deprecated. joins ls_cc_gateways\n  price_level_id — Foreign key to the default PriceLevel this shop sells at (/Account/{accountID}/PriceLevel/{priceLevelID}). joins ls_price_levels\n  contact — The shop's full Contact record as returned by load_relations=Contact: Addresses.ContactAddress (address1, address2, city, state, zip, country), Phone…\n  REFERENCES",
  "purchasing": "source_lightspeed.ls_order_shipment_items — one product's receipt within one shipment (one row per ShipmentItem).\n  One row per item received in a shipment: how many units of that product landed in that delivery, its cost before freight, its allocated freight and discount, and its final landed cost.\n  primary key: order_shipment_item_id\n  order_shipment_item_id — Unique id of this item-within-shipment row\n  order_shipment_id — Parent shipment; joins ls_order_shipments.order_shipment_id. joins ls_order_shipments\n  qty_received — Units of this item received in THIS delivery — a per-delivery event quantity, safe to sum over time, unlike the running counters on ls_purchase_order…\n  vendor_cost — Item cost in the VENDOR's currency before freight and discount\n  cost — Item cost in the merchant's default currency before freight and discount\n  total_vendor_cost — Total LANDED cost of this item within this shipment, in the vendor's currency — goods plus allocated freight, net of allocated discount\n  total_cost — Total LANDED cost of this item within this shipment in merchant currency — the true inventory value added by this receipt, and the numerator for real…\n  shipping_cost — Freight allocated to this item in merchant currency, already included in total_cost\n  shipping_vendor_cost — Freight allocated to this item in the vendor's currency; the currency twin of shipping_cost, not an extra charge\n  discount_money_value — Discount allocated to this item in merchant currency, already netted off total_cost\n  discount_money_vendor_value — Discount allocated to this item in the vendor's currency — currency twin of discount_money_value\n  discount_percent_value — Discount percentage applied to this item, in whole-percent units (5 = 5%)\n  currency_code — The merchant's default currency code for this row's non-vendor money columns, frozen when the shipment was created\n  vendor_currency_code — The vendor's currency code — the unit for every *_vendor_* money column on this row\n  vendor_currency_rate — Exchange rate from vendor to merchant currency captured AT SHIPMENT CREATION — historic and frozen, so re-converting old receipts at a current rate i…\n  create_time — When this item row was created, i.e. when the line was keyed during check-in\n  time_stamp — Last update of this item row and the sync high-water mark\n  item_id — The product received; joins the products domain (canonical `product_variant`). joins ls_items\n  item_vendor_id — The VENDOR's own SKU for this item — a STRING despite the '...ID' name, and not a foreign key to anything in Lightspeed\n  item_description — The item's description as captured on this receipt — a point-in-time snapshot, so it can differ from the product's current name after a rename\n  REFERENCES\n\nsource_lightspeed.ls_order_shipments — one shipment (receiving event) against one purchase order.\n  One row per delivery received against a purchase order: how many units landed, the landed cost of that delivery, the freight and discount allocated to it, and who received it when.\n  primary key: order_shipment_id\n  order_shipment_id — Unique id of the shipment across the whole account (not per order — that is sequence_number)\n  order_id — The purchase order this delivery was received against; joins ls_purchase_orders.order_id. joins ls_purchase_orders\n  sequence_number — The delivery's number WITHIN its purchase order (1 = first delivery, 2 = second)\n  total_qty_received — Total units received in THIS delivery, summing its items\n  total_vendor_cost — Total LANDED cost of everything in this shipment expressed in the VENDOR's currency — goods plus allocated freight, net of allocated discount\n  total_cost — Total LANDED cost of this shipment in the merchant's default currency — goods plus allocated freight, net of allocated discount\n  currency_code — The merchant's DEFAULT currency code at the time this shipment was created (e.g. 'AUD') — the unit for every non-vendor money column here\n  vendor_currency_code — The vendor's currency code, the unit for every *_vendor_cost / *_vendor_value column on this row\n  vendor_currency_rate — Exchange rate from vendor currency to merchant currency CAPTURED AT SHIPMENT CREATION\n  create_time — When the shipment RECORD was created (keyed by staff)\n  payment_due_date — Date the supplier's invoice for this delivery falls due — a DATE with no time component, populated only when the receiver entered the invoice terms\n  shipment_packing_ref_num — Reference number for the shipment as typed by staff — in practice the packing slip or supplier invoice number\n  time_stamp — Last update of the shipment record and the incremental-sync high-water mark\n  employee_id — Employee who received/checked in this delivery; joins the workforce domain (canonical `worker`). joins ls_employees\n  reception_date — When the goods were actually received\n  shipping_cost_method — How the freight charged to this shipment was spread across its items\n  shipping_vendor_cost — Freight allocated to THIS shipment, in the vendor's currency\n  shipping_cost — Freight allocated to THIS shipment, in merchant currency, and already included inside total_cost\n  shipping_cost_order_full_value — The FULL freight applied to the whole purchase order, in merchant currency, repeated on every shipment row of that order as context\n  shipping_cost_order_full_vendor_value — The full whole-PO freight in the vendor's currency, repeated on every shipment row\n  discount_method — How the discount charged to this shipment was spread across its items, mirroring shipping_cost_method\n  discount_money_vendor_value — Discount allocated to THIS shipment in the vendor's currency\n  discount_money_value — Discount allocated to THIS shipment in merchant currency, already netted off total_cost\n  discount_percent_value — Discount percentage applied on the shipment, in whole-percent units (5 = 5%)\n  discount_order_full_money_value — The FULL discount applied to the whole purchase order in merchant currency, repeated on every shipment row as context\n  discount_order_full_money_vendor_value — The full whole-PO discount in the vendor's currency, repeated on every shipment row\n  cost — Goods cost of the items in this shipment BEFORE freight and discount, merchant currency\n  vendor_cost — Goods cost of the items in this shipment before freight and discount, in the VENDOR's currency\n  status — Lifecycle state of the shipment, constrained by the docs to two values\n  REFERENCES\n\nsource_lightspeed.ls_purchase_order_lines — one product line on one purchase order (one row per OrderLine).\n  One row per item line on a purchase order: which product, how many units were ordered, at what unit cost, and how many of them have physically landed.\n  primary key: order_line_id\n  order_line_id — Unique id of the PO line\n  order_id — Parent purchase order; joins ls_purchase_orders.order_id. joins ls_purchase_orders\n  item_id — The product being ordered; joins the products domain (canonical `product_variant`, since a Lightspeed Item is the sellable variant). joins ls_items\n  quantity — Units ORDERED on this line\n  price — Unit COST in the merchant's default currency, ALREADY adjusted for any order-level discount\n  original_price — Unit cost in merchant currency BEFORE any order-level discount\n  vendor_cost — Unit cost BEFORE order discount in the VENDOR's currency — the vendor-currency counterpart of unit_cost_original, and per the docs it should be used…\n  checked_in — Units checked in, meaning ADDED TO INVENTORY — the stock is on the shelf and counted in quantity-on-hand\n  num_received — Units received at the door but NOT yet added to inventory — physically present, invisible to stock-on-hand\n  total — Documented as quantity x price, so it is the discounted goods cost of the line in merchant currency and EXCLUDES the allocated shipping_cost\n  shipping_cost — This line's share of the PO-level freight, calculated down from the header in merchant currency\n  shipping_vendor_cost — The same allocated freight share expressed in the vendor's currency\n  discount_money_value — This line's share of the order-level discount as money in merchant currency\n  discount_money_vendor_value — This line's allocated discount share in the vendor's currency — the currency twin of discount_money_value, not a second discount\n  discount_percent_value — The order-level discount percentage as it lands on this line, in whole-percent units (5 = 5%)\n  create_time — When the line was added to the PO — which can be later than the order's own created_at when a buyer appends items, and can be the migration timestamp…\n  time_stamp — Last modification of the line and the sync high-water mark\n  vendor_id — Parent-projected and potentially unpopulated. joins ls_vendors\n  shop_id — Parent-projected and potentially unpopulated. joins ls_shops\n  complete — Parent-projected and potentially unpopulated\n  ordered_date — Parent-projected and potentially unpopulated\n  received_date — Parent-projected and potentially unpopulated\n  archived — Parent-projected and potentially unpopulated\n  vendor_currency_code — Parent-projected and potentially unpopulated\n  REFERENCES\n\nsource_lightspeed.ls_purchase_orders — one purchase order raised with one vendor for one shop (Lightspeed resource `Order`).\n  One row per PURCHASE ORDER: stock the business is buying from a supplier, with the header-level costs, discounts, currency and lifecycle flags.\n  primary key: order_id\n  order_id — Unique id of the purchase order and the join key for every child table (lines, shipments)\n  ordered_date — When the order was placed WITH the vendor\n  received_date — The date the order actually arrived\n  arrival_date — The date the order is EXPECTED to arrive — a promise/ETA typed by staff, not a system-computed date and not evidence anything arrived\n  ref_num — Free-text external reference, often the vendor's own order or invoice number\n  ship_instructions — Free-text instructions for the VENDOR or shipper about how to ship the order (carrier, consolidation, drop-ship address)\n  stock_instructions — Free-text instructions for the RECEIVING employees about how to stock the goods once they land (which bay, label runs, hold for customer)\n  ship_cost — Freight the vendor added to the order, in the MERCHANT's default currency\n  ship_vendor_cost — The same freight expressed in the VENDOR's currency\n  other_cost — Other vendor-added costs (handling, surcharges, duty recharges) in merchant currency\n  other_vendor_cost — Other vendor-added costs in the vendor's currency; same negative-means-discount convention as other_cost\n  complete — True once the order is marked complete, which usually happens after check-in finishes\n  archived — True when the PO is archived\n  total_discount — Total MONEY value of all discounts on the order, merchant currency — the realised sum, whichever discount family produced it\n  total_quantity — Total units ORDERED across all lines — a header rollup of ls_purchase_order_lines.quantity, and never units received\n  vendor_id — Supplier the PO is for; joins ls_vendors.vendor_id. joins ls_vendors\n  name — Denormalised supplier name from the embedded Vendor relation, for readable grouping without a join\n  note_id — Foreign key to the Note record holding the PO's free-text note. joins ls_customer_notes\n  shop_id — The shop (location) the stock is being ordered FOR, i.e. where it will be checked in — not necessarily where the buyer sits. joins ls_shops\n  created_by_employee_id — Employee who CREATED the PO — the buyer, not the person who later received it (that is ls_order_shipments.employee_id)\n  custom_field_values — Raw JSON of the account-defined custom fields attached to this PO\n  create_time — When the PO RECORD was created\n  time_stamp — Last modification of the record — the correct high-water mark for incremental syncs, and meaningless as a business date (a PO from 2019 touched yeste…\n  vendor_currency_rate — Exchange rate captured on the PO, defaulting to the vendor's rate: multiply vendor-currency amounts by this to reach merchant currency\n  vendor_currency_code — Currency code of the purchase order, defaulting to the vendor's currency (e.g. 'USD')\n  shipping_cost_method — How ship_cost is distributed to the lines\n  has_shipments — True when the PO has any shipment records\n  discount_method — How the order-level discount is distributed to the lines, mirroring shipping_cost_method\n  discount_money_value — The order-level discount expressed as MONEY in the merchant's currency\n  discount_money_vendor_value — The same order-level discount in the VENDOR's currency\n  discount_is_percent — True when the buyer typed the order discount as a percentage, false when as a fixed amount\n  discount_percent_value — Order-level discount percentage in whole-percent units (5 = 5%, not 0.05)\n  costs_modified_after_shipment — True when the shipping cost or discount changed AFTER the first shipment was created\n  b2b_order_uid — Opaque unique identifier of this order in NuORDER (Lightspeed's B2B wholesale platform)\n  b2b_order_number — Human-readable order number in NuORDER, the display counterpart to b2b_order_uid\n  REFERENCES\n  discount\n\nsource_lightspeed.ls_vendor_returns — one vendor return document raised at one shop for one vendor.\n  One row per return of stock BACK TO a supplier — warranty batches, faulty goods, agreed stock swaps — with the cost value the shop expects to be credited.\n  primary key: vendor_return_id\n  vendor_return_id — Unique id of the vendor return document\n  vendor_id — Supplier the stock is being sent back TO; joins ls_vendors.vendor_id. joins ls_vendors\n  shop_id — The shop the stock is LEAVING — the location that loses the inventory, not the vendor's address. joins ls_shops\n  ref_num — Free-text external reference, in practice the supplier's RMA or credit-note number\n  status — Lifecycle state of the return\n  sent_date — When the return was dispatched to the vendor\n  ship_cost — Shipping cost incurred on the return, in the shop's currency\n  other_cost — Other costs on the return (restocking fees, handling)\n  hide_vendor_details — True when the vendor's details are suppressed on the printed return document\n  archived — True when the return has been archived\n  subtotal — Cost value of the goods being returned, before ship_cost/other_cost adjustments\n  total — Total cost value of the return INCLUDING adjustments — the credit the shop expects from the supplier\n  name — Denormalised supplier name from the embedded Vendor relation for readable grouping\n  time_stamp — Last modification of the record and the incremental-sync high-water mark\n  REFERENCES\n\nsource_lightspeed.ls_vendors — one supplier the account buys from.\n  One row per supplier: the party that fulfils purchase orders and receives vendor returns, with the trading terms the shop holds with them (account number, price level, purchasing currency) and the catalogue-sync behavio….\n  primary key: vendor_id\n  vendor_id — Unique supplier id; the target of ls_purchase_orders.vendor_id and ls_vendor_returns.vendor_id\n  name — Supplier name exactly as the shop typed it — a brand or a distributor\n  archived — True when the supplier is retired from the picker\n  account_number — The shop's own account number WITH this supplier (our customer number at their end), not an internal id\n  price_level — Name of the pricing tier the business trades on with this supplier — usually '1','2','3' running from HIGHEST price to lowest, so a numerically large…\n  update_price — Behaviour switch: when true, adding a catalogue item to a purchase order refreshes the item's RETAIL price from the catalogue MSRP\n  update_cost — Behaviour switch: when true, adding a catalogue item to a purchase order refreshes the item's COST from the catalogue entry\n  update_description — Behaviour switch: when true, adding a catalogue item to a purchase order overwrites the item's description from the catalogue entry — which is how ca…\n  share_sell_through — True when the shop has agreed that this vendor may receive sell-through data\n  b2b_seller_uid — The vendor's unique identifier in NuORDER (Lightspeed's B2B platform)\n  contact — Raw JSON of the supplier's contact record — addresses, phone numbers, emails, websites\n  code — Currency the shop buys from this supplier in (e.g. 'USD')\n  symbol — Display symbol for the purchasing currency (e.g. '$')\n  rate — The vendor's CURRENT default exchange rate, used to seed new purchase orders\n  time_stamp — Last modification of the vendor record and the incremental-sync high-water mark\n  REFERENCES",
  "registers": "source_lightspeed.ls_register_calculated — one payment type's live running total for one register's CURRENTLY OPEN session, as at the instant the endpoint was called.\n  The live 'what should be in this drawer right now' figure, broken down per payment type into the payments taken, the cash added and the cash withdrawn since the register was opened.\n  primary key: register_calculated_path_parameter_register_id, payment_type_id\n  register_calculated_path_parameter_register_id — The register these running totals belong to\n  payment_type_id — The tender this running total is for. joins ls_payment_types\n  payment — Running total of PAYMENTS taken on this tender since the register was opened — the sales-driven component of the expected drawer\n  add — Running total of the POSITIVE register-withdraw rows since open: the opening float plus any change top-ups\n  withdraw — Running total of the NEGATIVE register-withdraw rows since open: payouts and safe drops\n  REFERENCES\n\nsource_lightspeed.ls_register_count_amounts — one payment type's expected-versus-counted pair inside one register close-out.\n  The per-tender detail of every till close-out: what the system calculated the drawer should hold for a payment type, against what a human physically counted.\n  primary key: register_count_amount_id\n  register_count_amount_id — Unique id for this one tender line of one close-out\n  register_count_id — The close-out this tender line belongs to. joins ls_register_counts\n  payment_type_id — The tender being counted (Cash, Credit Card, Gift Card, ...). joins ls_payment_types\n  calculated — The 'should have' side: what the system computed the drawer holds for this tender, built from payments taken on it during the session PLUS the signed…\n  actual — The physical amount a human counted for this tender at close\n  REFERENCES\n\nsource_lightspeed.ls_register_counts — one register close-out — the open-to-close session of a single till, written at the moment the closing count is submitted.\n  End-of-day (or end-of-shift) till close-out headers.\n  primary key: register_count_id\n  register_count_id — Unique id of this close-out\n  create_time — The moment the till was CLOSED and the count submitted\n  open_time — When this till session was opened\n  notes — Free text typed by staff at close\n  register_id — The till that was counted. joins ls_registers\n  open_employee_id — Employee who OPENED the session\n  close_employee_id — Employee who submitted the count and closed the till\n  REFERENCES\n\nsource_lightspeed.ls_register_withdraws — one cash add or payout at one register (a single signed drawer movement outside of sales).\n  Cash moving in and out of a till for reasons other than a sale: opening floats, change top-ups, safe drops and petty-cash payouts.\n  primary key: register_withdraw_id\n  register_withdraw_id — Unique id for this add/payout\n  amount — SIGNED drawer movement\n  create_time — When the add/payout was recorded, store-local wall time with no timezone offset\n  notes — Reason staff typed for the movement\n  employee_id — Employee who made the add/payout. joins ls_employees\n  payment_type_id — Tender that moved. joins ls_payment_types\n  register_id — Till the movement happened at. joins ls_registers\n  REFERENCES",
  "sales": "source_lightspeed.ls_cc_charges — one row per CCCharge — one credit-card transaction ATTEMPT at the processing gateway, including declines, gateway voids and authorisation-only holds.\n  Gateway-side truth for integrated card payments: what was authorised, captured, declined, voided or refunded, and the reference ids needed to reconcile against a processor statement.\n  primary key: cc_charge_id\n  cc_charge_id — Unique numeric id for the charge attempt\n  gateway_trans_id — The processor's own transaction id — the key for reconciling against a merchant statement\n  xnum — Last four digits of the customer's card\n  response — Raw response received from the gateway\n  voided — The charge was voided AT THE GATEWAY before settlement — no money ever moved\n  refunded — CUMULATIVE amount refunded back to this card so far — a running total restated on the same row, NOT a per-refund event\n  amount — The original amount authorised/captured on the card\n  exp — Expiration date of the credit card as recorded by the gateway\n  auth_only — True when the transaction was an AUTHORISATION HOLD only and was never captured\n  auth_code — Authorisation code returned by the gateway on approval\n  time_stamp — When the record was last modified, store-local\n  declined — True when the gateway declined the charge\n  sale_id — The sale this card payment belongs to. joins ls_sales\n  entry_method — CONFLICTED FIELD: the reference documents it as 'The card type: Visa, Mastercard, etc.' while the field name says how the card was presented (swipe/c…\n  cardholder_name — Name appearing on the card\n  communication_key — Undescribed in the reference — gateway plumbing, most likely a credential or session handle\n  REFERENCES\n\nsource_lightspeed.ls_discounts — one row per named Discount rule that staff or the system can apply to a sale or a sale line.\n  The catalogue of reusable discount rules — their names, amounts/percentages, and what kind of discount they are (price rule, loyalty, or manual discount rule).\n  primary key: discount_id\n  discount_id — Unique numeric identifier for the discount rule\n  name — The merchant-defined description/name staff see when applying the rule\n  discount_amount — Dollar amount off, in store currency\n  discount_percent — Percentage off stored as a FRACTION of 1 — the docs cap it at <= 1.00 (100%)\n  require_customer — True when a customer must be attached to the sale before the rule can be applied (club, trade and loyalty rules)\n  archived — True when the rule is retired\n  source_id — What KIND of discount this is\n  time_stamp — When the rule record was last modified, store-local\n  REFERENCES\n\nsource_lightspeed.ls_processing_fees — one row per ProcessingFee — one fee record the payment processor assessed against one SalePayment.\n  What card acceptance actually costs, per payment, broken into fixed/variable components with interchange and scheme sub-breakdowns.\n  primary key: sale_payment_processing_fee_id\n  sale_payment_processing_fee_id — Unique identifier of the processing fee record\n  sale_payment_id — The SalePayment the fee was assessed on. joins ls_sale_payments\n  processing_fee_ref — The processor's external reference id for this fee line — the key for tying a fee back to a line on a processor statement\n  processor — Name of the payment processor handling the transaction\n  amount — TRAP: this is the total PAYMENT amount the fee was linked to, NOT the fee itself\n  fixed_fee — The fixed, per-transaction component of the fee, in store currency\n  variable_fee — The rate-based component of the fee, in store currency\n  variable_pct — The rate used to calculate variable_fee\n  interchange_fees_fixed_fee — Fixed portion of the interchange component (the part paid to the card-issuing bank)\n  interchange_fees_variable_fee — Variable portion of interchange, in currency\n  interchange_fees_variable_pct — The rate behind the variable interchange portion\n  scheme_fees_fixed_fee — Fixed portion of card-scheme fees (the part paid to the Visa/Mastercard network, distinct from interchange)\n  scheme_fees_variable_fee — Variable portion of card-scheme fees, in currency\n  scheme_fees_variable_pct — The rate behind the variable scheme portion\n  processing_time — When the processor remotely processed the fee — the settlement-side date\n  create_time — When the fee record was created inside Lightspeed\n  update_time — Last modification of the fee record\n  REFERENCES\n\nsource_lightspeed.ls_quotes — one row per Quote — one saved, uncompleted sale held for a customer so it can be reloaded at the register later.\n  The pre-sale pipeline: quotes/invoices staff saved for customers.\n  primary key: quote_id\n  quote_id — Unique numeric id of the quote — the ONLY stable identifier here\n  issue_date — When the quote was issued, store-local\n  notes — Free-text notes on the quote\n  archived — True when the quote is retired\n  employee_id — Employee who started the quote. joins ls_employees\n  sale_id — The Sale record CURRENTLY holding this quote's contents. joins ls_sales\n  REFERENCES\n\nsource_lightspeed.ls_sale_accounts — one row per SaleAccount — one gift-card (CreditAccount) association linking a single SalePayment to the SaleLine that created or funded it.\n  The bridge that makes gift cards and store credit interpretable: it ties the negative payment that funded a card to the sale line that sold it and to the CreditAccount that holds the balance.\n  primary key: sale_account_id\n  sale_account_id — Primary key of the link record\n  credit_account_id — The CreditAccount (gift card / store credit account) used in the SalePayment. joins ls_credit_accounts\n  sale_payment_id — The SalePayment linked to the sale line — specifically the NEGATIVE-amount payment that created or topped up the gift card. joins ls_sale_payments\n  sale_line_id — The SaleLine that sold the gift card. joins ls_sale_lines\n  REFERENCES\n\nsource_lightspeed.ls_sale_line_inventory_allocations — one row per InventorySale — one allocation of units from ONE inventory lot to ONE sale line.\n  The bridge from a sale line to the specific inventory lots it consumed or reserved.\n  primary key: inventory_sale_id\n  inventory_sale_id — Unique numeric identifier for the allocation\n  quantity — Units drawn from this lot\n  create_time — When the allocation or reservation was made, store-local\n  inventory_id — The Inventory lot the units were pulled from\n  sale_line_id — The sale line this allocation belongs to. joins ls_sale_lines\n  sale_id — The sale the allocation ultimately belongs to, carried down from the top-level Sale envelope. joins ls_sales\n  REFERENCES\n\nsource_lightspeed.ls_sale_lines — one row per SaleLine — one charge on one sale.\n  The product-level truth for the domain: units, per-product revenue, per-line discounts and per-line cost basis.\n  primary key: sale_line_id\n  sale_line_id — Unique numeric id for the line\n  sale_id — The sale this line sits on. joins ls_sales\n  create_time — When the line was first added to the ticket, store-local\n  time_stamp — When the line was last modified\n  unit_quantity — Units on the line\n  unit_price — Per-unit price actually charged, after price rules\n  normal_unit_price — Per-unit price before any price rules were applied — the 'was' price\n  discount_amount — Dollar discount entered on the line\n  discount_percent — Percentage discount on the line, expressed as a FRACTION of 1 (0.2 = 20%), matching the Discount object's documented <= 1.00 cap\n  avg_cost — Weighted-average cost of the product on this line, ex tax\n  fifo_cost — FIFO cost for the line, ex tax — the basis Lightspeed's own profit reports use\n  tax — Whether the line is taxed at all\n  tax1_rate — First tax rate for THIS line as a fraction, after TaxClass and TaxCategory customisation\n  tax2_rate — Second tax rate for this line as a fraction, where the jurisdiction has one\n  is_layaway — Line sits on a layaway: goods are reserved (see ls_sale_line_inventory_allocations) and paid for over time, so the money is a balance rather than set…\n  is_workorder — Line originated from a workshop/service job — the marker that separates SERVICE revenue from goods revenue\n  is_special_order — Line is a special order (stock brought in for a named customer); setting it creates a SpecialOrder record\n  displayable_subtotal — Receipt-facing line subtotal, documented as (unitQuantity * unitPrice) - discount\n  displayable_unit_price — The unit price shown to the customer after price-rule PERCENTAGE discounts ONLY — fixed-amount price rules are deliberately excluded\n  calc_line_discount — Money taken off by the line's own discount, in currency\n  calc_transaction_discount — This line's allocated share of a whole-sale (transaction-level) discount\n  calc_total — Line revenue INCLUDING tax, after all discounts\n  calc_subtotal — Line revenue excluding tax\n  calc_tax1 — Tax charged on this line at the first rate, in currency\n  calc_tax2 — Tax charged on this line at the second rate, in currency; 0 in single-tax jurisdictions\n  tax_class_id — TaxClass of the line, which determines its specific rates. joins ls_tax_classes\n  customer_id — Customer on the LINE — populated ONLY for layaway, special-order and workorder lines. joins ls_customers\n  discount_id — The named Discount rule applied to this line specifically. joins ls_discounts\n  employee_id — Employee responsible for this line, which can differ from the sale's employee when staff split a ticket or a workshop tech adds parts. joins ls_employees\n  item_id — Catalog item the line charges for; maps to the `product`/`product_variant` canonical entities. joins ls_items\n  note_id — The single Note object attached to this line; notes print on the receipt. joins ls_customer_notes\n  parent_sale_line_id — For a REFUND line, the original sale line it reverses — the API uses it to stop cumulative refunds exceeding the original quantity\n  shop_id — Shop where the line was added. joins ls_shops\n  tax_category_id — TaxCategory applied to this line — the jurisdiction-level container that sits above TaxClass. joins ls_tax_categories\n  item_fee_id — The ItemFee this line represents, when the line is a fee rather than merchandise (e.g. a recycling or environmental levy attached by category). joins ls_item_fees\n  line_type — Descriptor of what the line represents\n  require_full_reservation — Request-payload-only flag that makes a write FAIL if there is not enough inventory to reserve the whole unitQuantity\n  completed — Parent-projected and not authoritative\n  voided — Parent-projected and not authoritative\n  complete_time — Parent-projected and not authoritative\n  REFERENCES\n\nsource_lightspeed.ls_sale_payment_signatures — one row per SalePaymentSignature — one captured signature image belonging to one sale payment.\n  Evidence that a customer signed for a payment, stored as a pointer into Lightspeed's image storage service.\n  primary key: sale_payment_signature_id\n  sale_payment_signature_id — Primary key of the signature record\n  file_path — Path to the signature image inside Lightspeed's image storage service\n  create_time — When the signature was captured, store-local\n  sale_payment_id — The payment this signature was captured for — the ONLY link this table has to the rest of the domain. joins ls_sale_payments\n  REFERENCES\n\nsource_lightspeed.ls_sale_payments — one row per SalePayment — one tender applied to, or refunded from, one sale.\n  How money actually moved: cash, card, gift card, store credit, cheque, on-account.\n  primary key: sale_payment_id\n  sale_payment_id — Unique numeric id for this tender line\n  amount — Amount tendered in store currency, INCLUDING any tip (see tip_amount)\n  create_time — When the payment was taken, store-local\n  archived — Archived payments are effectively voided and, per the docs, must NOT count toward totals\n  remote_reference — Optional client-generated unique identifier supplied by an integration when creating the payment — an idempotency key for reconciling against an exte…\n  tip_amount — Tip portion of this tender, negative for a refund\n  payment_id — Reference to the charge held by the payment SERVICE (the processor's own handle)\n  sale_id — The sale this payment settles. joins ls_sales\n  payment_type_id — Tender type of this payment or refund (Cash, Credit Card, Gift Card, Credit Account, ...). joins ls_payment_types\n  cc_charge_id — The CCCharge (gateway transaction) backing this payment, when the card ran through Lightspeed's integrated processing. joins ls_cc_charges\n  ref_payment_id — Points at the ORIGINAL salePaymentID this row reverses; set when refunding a previous credit card charge\n  register_id — Register the payment was received at. joins ls_registers\n  employee_id — Employee who received the payment; may differ from the employee who rang the sale. joins ls_employees\n  credit_account_id — The CreditAccount (store credit or gift card) this deposit/withdrawal applies to. joins ls_credit_accounts\n  completed — Parent-projected and potentially sparse\n  voided — Parent-projected and potentially sparse\n  complete_time — Parent-projected; unreliable\n  shop_id — Parent-projected shop; unreliable coverage. joins ls_shops\n  REFERENCES\n\nsource_lightspeed.ls_sale_voids — one row per SaleVoid — one void event recorded against one sale, with the operator's stated reason.\n  The audit trail for voided transactions: who voided what, where, when and why.\n  primary key: sale_void_id\n  sale_void_id — Unique numeric id of the void record\n  create_time — When the void happened, store-local\n  reason — Free-text note the operator gave for the void\n  sale_id — The sale that was voided; joins ls_sales where voided = true. joins ls_sales\n  employee_id — Employee who PERFORMED the void — frequently NOT the employee who rang the original sale (that is ls_sales.employee_id). joins ls_employees\n  shop_id — Shop where the void was performed. joins ls_shops\n  REFERENCES\n\nsource_lightspeed.ls_sales — one row per Sale record — one register ticket/transaction, in any state (open, completed, voided, archived).\n  The transaction header for the whole domain: totals, tax, discounts, cost of goods, and every foreign key that gives a sale its who/where/when.\n  primary key: sale_id\n  sale_id — Immutable numeric ticket id, unique within the account\n  completed — True once the ticket was finalised: inventory has been deducted and payments sum to the total\n  voided — True when the sale was voided\n  archived — True when the sale is archived (hidden from the POS UI)\n  create_time — When the ticket was first opened at the register, store-local, read-only\n  complete_time — When the sale was completed — THE canonical revenue timestamp, store-local\n  updatetime — Last modification, read-only, store-local\n  time_stamp — Marked *legacy* in the reference. deprecated\n  reference_number — Order number assigned by the external system that created the sale (webstore, Amazon, marketplace)\n  reference_number_source — Name of the external system that owns reference_number\n  tax1_rate — Default first tax rate for the sale, expressed as a FRACTION (0.1 = 10%, not 10)\n  tax2_rate — Default second tax rate as a fraction, for jurisdictions with two components (e.g. GST + PST)\n  change — Cash handed back to the customer; cash sales only\n  tip_enabled — True when the tipping feature was active on this ticket\n  enable_promotions — True when automatic Promotions were run against every line added to this sale\n  calc_discount — Total money discounted on the sale, store currency, as a POSITIVE number representing value given away\n  calc_total — The grand total the customer pays: after discounts, INCLUDING tax\n  calc_subtotal — Sale total EXCLUDING tax, after discounts\n  calc_taxable — Subtotal of only the lines that were actually taxed (SaleLine.tax = true AND their TaxClass carries a rate)\n  calc_non_taxable — Subtotal of the non-taxable lines (tax-exempt customers, zero-rated goods, some labour classes)\n  calc_avg_cost — Cost of goods for the whole sale at weighted-average unit cost, ex tax, summed across lines\n  calc_fifo_cost — Cost of goods at FIFO, ex tax — the basis that matches Lightspeed's native profit reports\n  calc_tax1 — Tax collected at the first rate across all lines, in store currency\n  calc_tax2 — Tax collected at the second rate, in currency; 0 in single-tax jurisdictions\n  calc_payments — Sum of every SalePayment.amount on this sale, tips included\n  calc_tips — Sum of SalePayment.tipAmount across the sale\n  total — The documented arithmetic restatement: calcSubtotal - calcDiscount + calcTax1 + calcTax2\n  total_due — Total minus credit-account and gift-card deposits (deposits subtract, withdrawals add) minus credit-card refunds\n  displayable_total — total plus gift-card deposits\n  balance — total - calc_payments: money still owed on the ticket\n  customer_id — Customer attached to the ticket. joins ls_customers\n  discount_id — DEPRECATED per the reference. deprecated. joins ls_discounts\n  discount_percent — DEPRECATED per the reference. deprecated\n  employee_id — Employee who processed (rang up) the ticket — the attribution for 'sales by staff member'. joins ls_employees\n  tip_employee_id — Employee assigned the whole tip amount for this sale\n  quote_id — The Quote this sale was created from. joins ls_quotes\n  register_id — Register (till) the sale was processed on. joins ls_registers\n  ship_to_id — The ShipTo (shipment/delivery) record for this sale, present when goods were shipped rather than carried out. joins ls_ship_tos\n  shop_id — Shop (physical location) where the sale was processed — the `location` dimension for every revenue split. joins ls_shops\n  tax_category_id — TaxCategory governing which tax rates apply to this sale; it is what determines the tax1_rate/tax2_rate defaults. joins ls_tax_categories\n  REFERENCES",
  "taxreports": "source_lightspeed.ls_payment_types — one tender method configured on the account.\n  The tender methods available at the register (Cash, Credit Card, Gift Card, Credit Account, ...), including their refund routing and whether a customer must be attached.\n  primary key: payment_type_id\n  payment_type_id — Unique id of the tender method; the join target for SalePayment.paymentTypeID, RegisterWithdraw, RegisterCount and ls_report_payments_by_day.payment_…\n  name — Display name of the tender as staff see it at the register ('Cash', 'Credit Card', 'Debit Card', 'Gift Card', 'Check')\n  require_customer — true when a customer record must be attached to the sale before this tender may be used\n  archived — true when the tender has been retired from the register\n  internal_reserved — true for predefined system tenders that a store cannot edit or delete (the set published in the API's Defined Values section)\n  type — The tender FAMILY, used for grouping takings into cash/card/gift/account buckets\n  refund_as_payment_type_id — The tender that refunds of this tender must be issued as (e.g. Gift Card refunds as Gift Card, Credit Account as Credit Account)\n  REFERENCES\n\nsource_lightspeed.ls_report_discounts_by_day — one shop per day.\n  Lightspeed-computed daily discount totals by shop, built for accounting-package export.\n  primary key: date, shop_id\n  date — The aggregation day the discounts were given on\n  shop_id — The shop where the discounts were given. joins ls_shops\n  discount — Total value of sale discounts given on this day at this shop (the docs call it the subtotal of sale discounts)\n  REFERENCES\n\nsource_lightspeed.ls_report_orders_by_tax_class — one tax-class cost subtotal within one received purchase order.\n  Lightspeed-computed accounting report of purchase orders RECEIVED from vendors, broken down per order and subtotaled by tax class, with vendor identification.\n  primary key: order_id, tax_class_id\n  date — The day the order was RECEIVED, not the day it was placed\n  shop_id — The shop the order belongs to. joins ls_shops\n  vendor_id — The vendor (supplier) this line is for. joins ls_vendors\n  vendor_name — Denormalised vendor name as of report generation\n  tax_class_id — The tax class the cost subtotal belongs to. joins ls_tax_classes\n  tax_class_name — Denormalised tax class name for this subtotal\n  cost — Subtotal COST (what you paid the vendor) for items of this tax class on this order - not retail value, not landed cost\n  order_id — The purchase order this row is part of. joins ls_purchase_orders\n  total_ship_cost — The ENTIRE order's shipping cost, repeated verbatim on every tax-class row of that order - the docs say explicitly not to sum it\n  total_other_cost — The ENTIRE order's other/ancillary charges, repeated on every tax-class row exactly like total_ship_cost, with the same explicit do-not-sum warning i…\n  REFERENCES\n\nsource_lightspeed.ls_report_payments_by_day — one payment type per shop per day, split by the layaway flag.\n  Lightspeed-computed daily takings totals by payment type, shop and layaway flag, built for accounting-package export.\n  primary key: date, shop_id, payment_type_id, layaway\n  date — The aggregation day these payments were taken on\n  shop_id — The shop where the money was taken. joins ls_shops\n  layaway — true when the row totals payments taken against a LAYAWAY (a deposit toward goods not yet handed over), false for ordinary sale payments\n  amount — Total money taken under this payment type on this day at this shop (the docs call it the subtotal for the payment type)\n  payment_type_name — Denormalised tender name as of report generation\n  payment_type_id — The tender this total is for. joins ls_payment_types\n  REFERENCES\n\nsource_lightspeed.ls_report_tax_class_sales_by_day — one tax class per shop per day.\n  Lightspeed-computed daily sales subtotals broken down by tax class and shop, carrying BOTH a FIFO and an average cost basis for the same goods.\n  primary key: date, shop_id, tax_class_id\n  date — The aggregation day of these sale totals\n  shop_id — The shop these sales were rung at. joins ls_shops\n  tax_class_id — The tax class the totals belong to. joins ls_tax_classes\n  tax_class_name — Denormalised class name as of report generation ('Item', 'Labor', 'Gift Card')\n  subtotal — Sales subtotal for this class on this day at this shop, EX TAX\n  fifo_cost — Cost of goods sold in this group valued First In First Out - an EXTENDED total for the group, not a unit cost\n  avg_cost — Cost of the same goods valued at weighted-average cost - the ALTERNATIVE basis to fifo_cost for the identical sales, not an additional cost\n  REFERENCES\n\nsource_lightspeed.ls_report_taxes_by_day — one tax category per shop per day.\n  Lightspeed-computed daily tax totals by tax category and shop, built for accounting-package export and marked read-only in the docs.\n  primary key: date, shop_id, tax_category_id\n  date — The aggregation day the taxes were collected on\n  shop_id — The shop where the tax was collected. joins ls_shops\n  tax_category_id — The tax category (rate/authority) the total belongs to. joins ls_tax_categories\n  tax_category_name — Denormalised category name as of report generation\n  tax — Total tax collected for this category on this day at this shop\n  REFERENCES\n\nsource_lightspeed.ls_tax_categories — one sales-tax configuration (TaxCategory, labelled \"Sales Tax\" in the Lightspeed UI) on the account.\n  The account's sales-tax definitions: up to two named component rates plus the tax-inclusive pricing convention.\n  primary key: tax_category_id\n  tax_category_id — Unique id of the sales-tax configuration; the join target for Sale.taxCategoryID, Shop.taxCategoryID and ls_report_taxes_by_day.tax_category_id\n  is_tax_inclusive — true when prices under this category are entered and displayed WITH tax already inside them (AU/NZ/UK convention), false when tax is added on top at…\n  tax1_name — Label of the first component rate as printed on receipts and reports (e.g. 'GST', 'Sales Tax', 'State')\n  tax2_name — Label of the second component rate (e.g. 'PST', 'County')\n  tax1_rate — First component rate as a FRACTION OF 1, not a percentage: 0.1 means 10%\n  tax2_rate — Second component rate, also a fraction of 1; 0 on single-tax accounts\n  time_stamp — When the category record was last modified, in store-local time\n  REFERENCES\n\nsource_lightspeed.ls_tax_category_classes — one per-tax-class rate override inside one tax category.\n  Rate overrides: the rate a specific tax class attracts under a specific tax category, replacing that category's default tax1_rate/tax2_rate.\n  primary key: tax_category_id, tax_class_id\n  tax_category_id — The owning tax category. joins ls_tax_categories\n  tax_category_class_id — Surrogate id of the override row itself\n  tax_class_id — The tax class this override applies to. joins ls_tax_classes\n  tax1_rate — First-component rate for this class under this category, as a FRACTION OF 1 (0.1 = 10%)\n  tax2_rate — Second-component override, also a fraction of 1\n  REFERENCES\n\nsource_lightspeed.ls_tax_classes — one tax class label that items and sale lines can carry.\n  Labels that group items for tax treatment (Item, Labor, Gift Card, ...).\n  primary key: tax_class_id\n  tax_class_id — Unique id of the tax class\n  name — Human label of the class, e.g. 'Item', 'Labor', 'Gift Card'\n  time_stamp — When the class record was last modified, in store-local time\n  REFERENCES",
  "workshop": "source_lightspeed.ls_workorder_images — one row per image attached to one workorder.\n  Reference photos attached to a job — damage on intake, before/after shots, a picture of the serial plate.\n  primary key: workorder_image_id\n  workorder_image_id — Unique numeric id of the image attachment\n  workorder_id — FK to the job the image is attached to. joins ls_workorders\n  description — Staff-entered caption for the image (e.g. 'scratch on down tube at intake')\n  filename — Stored filename of the image\n  ordering — Display position of this image within the job's image list — a rank, not a count and not a quantity\n  public_id — Public identifier of the stored asset, combined with base_image_url to build a retrievable URL\n  base_image_url — Base/CDN URL the image is served from\n  size — Documented only as 'the size of the image' with no unit — conventionally bytes for a stored asset, but the docs do not state it and it could be a pix…\n  create_time — When the image was uploaded\n  time_stamp — When the attachment record was last modified (caption edits, reordering)\n  REFERENCES\n\nsource_lightspeed.ls_workorder_items — one row per part/product charge on one workorder.\n  The physical goods consumed on a job: tubes, chains, cables, cassettes.\n  primary key: workorder_item_id\n  workorder_item_id — Unique numeric id of the part line\n  workorder_id — FK to the parent job. joins ls_workorders\n  approved — True when the customer has approved this part charge\n  unit_price — Per-unit RETAIL price the part is quoted at on the job sheet — a per-unit figure, not a line total, and not necessarily the catalog price (staff can…\n  unit_quantity — Quantity of the part being used/sold on the job\n  warranty — True when this part is supplied under warranty and the customer is NOT charged for it\n  tax — True when this part line is taxed\n  is_special_order — True when the part is not in stock and is being special-ordered for this job; Lightspeed then creates a special order reached through the linked sale…\n  note — Free-text note on the part line\n  employee_id — FK to the employee responsible for this part line — usually whoever added the part rather than who fitted it. joins ls_employees\n  sale_line_id — FK to the SaleLine this part becomes on the register at checkout. joins ls_sale_lines\n  sale_id — FK to the Sale where the part was billed. joins ls_sales\n  item_id — FK to the catalog Item this charge is for — the actual product. joins ls_items\n  discount_id — FK to a Discount applied to this part charge. joins ls_discounts\n  time_stamp — When this part line was last modified\n  REFERENCES\n\nsource_lightspeed.ls_workorder_lines — one row per labour task or misc (non-part) charge on one workorder.\n  The work itself: each task performed or to be performed on a job, with its price, time estimate, assigned employee and done flag.\n  primary key: workorder_line_id\n  workorder_line_id — Unique numeric id of the task/charge, account-scoped (not per-workorder), so it is safe as a standalone primary key\n  workorder_id — FK to the parent job. joins ls_workorders\n  note — Free text for the task\n  hours — Whole-hours component of the task's duration\n  minutes — Minutes component of the task duration, complementing hours (a 90-minute task is hours=1, minutes=30)\n  unit_price_override — Per-unit retail price for this charge\n  unit_quantity — Units of this charge, documented as integer and usually 1 for tasks\n  unit_cost — Per-unit cost to the business for this task (internal labour cost basis)\n  done — True when this individual task is complete\n  approved — True when the customer approved this charge\n  warranty — True when this task is covered by warranty and the customer will NOT be charged for it\n  tax — True when this charge is taxed\n  employee_id — FK to the employee responsible for this task — the correct grain for per-mechanic workload and throughput. joins ls_employees\n  sale_line_id — FK to the SaleLine that represents this task on the register once checked out. joins ls_sale_lines\n  sale_id — FK to the Sale where this task was billed and paid. joins ls_sales\n  item_id — FK to the Non-Inventory / TaxClass=Labor Item used to create this task — i.e. the store's service-menu entry ('Full Service', 'Puncture Repair'). joins ls_items\n  discount_id — FK to a Discount applied to this charge. joins ls_discounts\n  tax_class_id — FK to the TaxClass governing this line — for genuine labour this is the store's 'Labor' class, which is also the routing signal that put the charge o…. joins ls_tax_classes\n  time_stamp — When this task/charge was last modified\n  REFERENCES\n\nsource_lightspeed.ls_workorder_statuses — one row per workorder status configured on the account (system-defined and store-created).\n  The lookup for the workshop pipeline: every status a job can be in, including system states and merchant-defined boards.\n  primary key: workorder_status_id\n  workorder_status_id — Unique numeric id of the status\n  name — Display name shown in the POS\n  sort_order — Position in POS dropdowns and boards — a display ordering, not a pipeline stage number, and not monotonic with progress\n  html_color — Hex colour the POS paints this status with (e.g. #FF0000)\n  system_value — Stable internal identifier for statuses Lightspeed defines and locks (the store cannot rename or delete them)\n  REFERENCES\n\nsource_lightspeed.ls_workorders — one row per workorder — one service/repair ticket for one customer item (a Serialized entry) at one shop.\n  The header of a workshop job: who it is for, which item is being worked on, where it is in the shop's status pipeline, when it came in and when it was promised.\n  primary key: workorder_id\n  workorder_id — Unique numeric id of the job, account-scoped\n  time_in — When the item was received/booked in\n  eta_out — The promise date: when the job is expected to be finished\n  note — Customer-facing notes for the whole job: what was asked for, what was quoted, what the customer reported\n  internal_note — Staff-only notes never shown to the customer\n  warranty — True when the WHOLE job is warranty work and the customer will not be charged\n  tax — Documented as 'does this workorder have tax charged on it'\n  archived — True when the job is archived: hidden in the POS and explicitly excluded from every total Lightspeed reports\n  hook_in — Free-text storage location (hook/rack/bay number) where the item waits for work to START\n  hook_out — Free-text storage location where the finished item waits for customer PICKUP\n  save_parts — True when the customer asked to keep the parts removed from the item, to be handed back with the job\n  assign_employee_to_all — Admin behaviour flag: when true the job's employee_id is auto-stamped onto every line\n  customer_id — FK to the customer the job is for. joins ls_customers\n  discount_id — FK to a job-level Discount applied to the whole workorder. joins ls_discounts\n  employee_id — FK to the employee IN CHARGE of the job (service writer / owner), not necessarily the person who performed the tasks. joins ls_employees\n  serialized_id — FK to the Serialized entry for the customer's item being worked on (the bike/machine, tracked by serial). joins ls_serialized\n  shop_id — FK to the Shop (physical location) where the work is to be performed. joins ls_shops\n  sale_id — FK to the Sale this job was checked out and paid on. joins ls_sales\n  sale_line_id — FK to the single SaleLine that represents this job on the register once billed. joins ls_sale_lines\n  workorder_status_id — FK to the store's current status for this job. joins ls_workorder_statuses\n  customer — Denormalised convenience: the customer's display name (first + last, falling back to company) taken from the embedded Customer relation\n  name — Denormalised current status display name\n  system_value — Denormalised stable status identifier for system-defined statuses\n  description — Denormalised description of the customer's item being worked on (e.g. the bike make/model) from the Serialized relation\n  serial — Denormalised serial/frame number of the customer's item\n  time_stamp — Last modification of the record, store-local\n  REFERENCES"
});

/** Full per-table dictionaries for progressive agent discovery. */
export const LIGHTSPEED_TABLE_DICTIONARIES: Readonly<Record<string, string>> = Object.freeze({
  "ls_account": "source_lightspeed.ls_account — one row -- the Lightspeed Retail (R-Series) account associated with the access token (singleton).\n  The merchant account itself: its id, trading name, subscription status, employee licence usage and base currency.\n  primary key: account_id\n  account_id — The account's unique id\n  name — The merchant account name, i.e. the business as Lightspeed bills it\n  link — Self-referencing API URL for this account resource, as returned in the example payload\n  system_customer_id — Lightspeed's platform-level identifier for the merchant, the same value as Session.systemCustomerID\n  status — Subscription/lifecycle state of the account\n  employee_count — Number of employees counted against the account's licence\n  employee_limit — Maximum employees the account's plan permits\n  unique_subscription_identifier — Opaque identifier of the billing subscription behind the account, from the example payload\n  code — ISO code of the account's BASE currency (USD, CAD, AUD...)\n  symbol — Display symbol for the base currency ($, £, €)\n  REFERENCES",
  "ls_account_purchasing_currencies": "source_lightspeed.ls_account_purchasing_currencies — one row per purchasing currency enabled on the account.\n  The non-base currencies the account is configured to PURCHASE in (i.e. buy stock from overseas suppliers), each with the exchange rate recorded against it.\n  primary key: account_id, code\n  account_id — The account these purchasing currencies belong to, carried down from the parent Account object. joins ls_account\n  code — ISO code of a currency the account may raise purchase orders in (USD, EUR...)\n  symbol — Display symbol for the purchasing currency\n  rate — Exchange rate recorded for this purchasing currency\n  REFERENCES",
  "ls_catalog_vendor_items": "source_lightspeed.ls_catalog_vendor_items — one product entry in one configured vendor catalogue.\n  What the shop's suppliers say is available to ORDER: supplier part numbers, tiered costs, bulk price breaks, MSRPs, availability status and supersession.\n  primary key: catalog_vendor_item_id\n  catalog_vendor_item_id — Primary key of the catalogue entry\n  catalog_vendor_id — Which vendor CATALOGUE the entry belongs to\n  vendor_number — The part number the VENDOR assigns — what goes on a purchase order to that supplier\n  manufacturer_number — The part number the MANUFACTURER assigns\n  description — Name/description of the product as the vendor writes it\n  category — The VENDOR's suggested category as free text (e.g. 'Trunk Racks')\n  brand — Brand of the product per the catalogue\n  model — Model designation; the docs note it is usually a year\n  year — Model year of the item as text (not a number, so no arithmetic or range filters without casting)\n  upc — Universal Product Code\n  ean — International Article Number for the entry; the international counterpart of upc\n  ean2 — An alternate EAN\n  color_name — Colour as published by the vendor\n  size_name — Size as published by the vendor\n  retail_unit — How many SELLABLE units come per order unit (e.g. inner tubes supplied in boxes of 50)\n  unit_of_measurement — How multiple quantities are grouped for ordering — EA, box, pair\n  cost — Base cost per ORDER UNIT from the vendor, in the CATALOGUE's own currency (which may not be the store's)\n  cost_level2 — First discounted cost tier (a dealer-terms tier, not a volume break)\n  cost_level3 — Second discounted cost tier\n  cost_level4 — Final discounted cost tier — the best published terms\n  msrp — Manufacturer's suggested retail price per the catalogue, in the catalogue's currency\n  break_qty — Order quantity at which the first bulk price break applies\n  break_price — Unit price once at least break_qty is ordered\n  break_qty2 — Second bulk break quantity\n  break_price2 — Unit cost at the second break quantity\n  break_qty3 — Third bulk break quantity\n  break_price3 — Unit cost at the third break quantity\n  status — The vendor's lifecycle status for the entry\n  replacement — Vendor part number of the suggested successor when this entry is superseded\n  replacement_description — Description of the suggested replacement\n  last_price_change — When the vendor last changed pricing on this entry\n  last_qoh — Last reported quantity on hand AT THE VENDOR's warehouse — not in the shop\n  archived — True when the catalogue entry itself is archived\n  catalog_vendor — Raw catalogue-owner object\n  REFERENCES",
  "ls_categories": "source_lightspeed.ls_categories — one category node in the item category tree.\n  The hierarchical category tree used to organise items, structured like a directory.\n  primary key: category_id\n  category_id — Primary key of the node\n  name — The node's OWN name only, not its path (e.g. 'Service')\n  full_path_name — Slash-delimited path from the root to this node (e.g. 'Workshop/Service')\n  parent_id — The node directly above this one\n  node_depth — How many ancestors the node has: 0 = top level, 1 = one parent, and so on\n  left_node — Nested-set left bound\n  right_node — Nested-set right bound, the closing partner of left_node\n  create_time — When the node was created\n  time_stamp — When the node was last modified\n  REFERENCES",
  "ls_cc_charges": "source_lightspeed.ls_cc_charges — one row per CCCharge — one credit-card transaction ATTEMPT at the processing gateway, including declines, gateway voids and authorisation-only holds.\n  Gateway-side truth for integrated card payments: what was authorised, captured, declined, voided or refunded, and the reference ids needed to reconcile against a processor statement.\n  primary key: cc_charge_id\n  cc_charge_id — Unique numeric id for the charge attempt\n  gateway_trans_id — The processor's own transaction id — the key for reconciling against a merchant statement\n  xnum — Last four digits of the customer's card\n  response — Raw response received from the gateway\n  voided — The charge was voided AT THE GATEWAY before settlement — no money ever moved\n  refunded — CUMULATIVE amount refunded back to this card so far — a running total restated on the same row, NOT a per-refund event\n  amount — The original amount authorised/captured on the card\n  exp — Expiration date of the credit card as recorded by the gateway\n  auth_only — True when the transaction was an AUTHORISATION HOLD only and was never captured\n  auth_code — Authorisation code returned by the gateway on approval\n  time_stamp — When the record was last modified, store-local\n  declined — True when the gateway declined the charge\n  sale_id — The sale this card payment belongs to. joins ls_sales\n  entry_method — CONFLICTED FIELD: the reference documents it as 'The card type: Visa, Mastercard, etc.' while the field name says how the card was presented (swipe/c…\n  cardholder_name — Name appearing on the card\n  communication_key — Undescribed in the reference — gateway plumbing, most likely a credential or session handle\n  REFERENCES",
  "ls_cc_gateways": "source_lightspeed.ls_cc_gateways — one row per legacy credit-card gateway configuration referenced by a shop.\n  Legacy per-shop credit-card gateway setup: which processor, its credentials, terminal/market identifiers, enabled and test-mode switches, and the mapping from card brands to PaymentType ids.\n  primary key: cc_gateway_id\n  cc_gateway_id — Unique numeric id of the gateway configuration\n  gateway — Name of the payment gateway/processor this shop is wired to\n  enabled — True when the gateway is switched on\n  test_mode — True when the gateway is in test/sandbox mode\n  allow_credits — Whether credit-card charges (credits back to a card) are permitted through this gateway\n  market_type — Market type value sent in the transaction XML (retail, e-commerce, MOTO and similar processor-defined categories)\n  device_type — Numeric code for the type of device used to process card transactions\n  terminal_num — Terminal ID sent in the transaction XML\n  login — Gateway credential (merchant login)\n  trans_key — Gateway credential (transaction key)\n  account_num — Gateway credential (merchant account number)\n  hash_value — MD5 hash used to validate the transaction\n  other_credentials1 — Spare credential slot, used when a processor needs a field beyond login/transKey/accountNum\n  other_credentials2 — Second spare credential slot\n  visa_payment_type_id — PaymentType id that Visa transactions on this gateway are recorded against (/Account/{accountID}/PaymentType/{visaPaymentTypeID})\n  master_payment_type_id — PaymentType id used for MasterCard transactions on this gateway (/Account/{accountID}/PaymentType/{masterPaymentTypeID})\n  discover_payment_type_id — PaymentType id used for Discover Card transactions (/Account/{accountID}/PaymentType/{discoverPaymentTypeID})\n  american_payment_type_id — PaymentType id used for American Express transactions (/Account/{accountID}/PaymentType/{americanPaymentTypeID})\n  debit_payment_type_id — PaymentType id used for debit-card transactions (/Account/{accountID}/PaymentType/{debitPaymentTypeID})\n  REFERENCES",
  "ls_contact_emails": "source_lightspeed.ls_contact_emails — one row per email address held on a contact.\n  The multi-valued email addresses of a contact, one row each, with the documented Primary/Secondary use type.\n  primary key: contact_id, contact_email\n  contact_id — Owning contact block. joins ls_contacts\n  contact_email — Zero-based position of this address inside the parent's email container, needed only because the API gives email entries no id of their own\n  address — The email address itself\n  use_type — Which slot this address occupies: Primary or Secondary\n  REFERENCES",
  "ls_contact_phones": "source_lightspeed.ls_contact_phones — one row per phone number held on a contact.\n  The multi-valued phone numbers of a contact, one row each, tagged with the documented Home/Work/Mobile/Pager/Fax use type.\n  primary key: contact_id, contact_phone\n  contact_id — Owning contact block. joins ls_contacts\n  contact_phone — Zero-based position within the parent's phone container; phone entries carry no id of their own\n  number — The phone number exactly as typed: spaces, dashes, brackets and missing country codes all occur\n  use_type — What kind of number this is: Home, Work, Mobile, Pager or Fax\n  REFERENCES",
  "ls_contact_websites": "source_lightspeed.ls_contact_websites — one row per website URL held on a contact.\n  The multi-valued website URLs attached to a contact.\n  primary key: contact_id, contact_website\n  contact_id — Owning contact block. joins ls_contacts\n  contact_website — Zero-based position within the parent's website container; website entries carry no id\n  url — The URL as typed\n  REFERENCES",
  "ls_contacts": "source_lightspeed.ls_contacts — one row per Contact record (the single contact block attached to a Customer, CreditAccount or ShipTo).\n  The shared contact block: exactly one postal address plus the three marketing opt-out flags, and the parent of the multi-valued email, phone and website child tables.\n  primary key: contact_id\n  contact_id — Unique numeric id of the contact block\n  address1 — The contact's street address, first line\n  address2 — Second address line: apartment, suite, unit, care-of\n  city — Postal address city or suburb, free text and unnormalised (spelling and case vary), so group with lower(trim(city)) for catchment analysis\n  state — Postal address state/province as free text, e.g. 'Victoria'\n  state_code — ISO code for the state/province, e.g. 'VIC'\n  zip — Postal/zip code\n  country — Postal address country as free text; often the store's own country by default rather than a deliberate entry\n  country_code — ISO code for the country\n  no_email — True when the contact has opted OUT of email messages\n  no_mail — True when the contact has opted OUT of postal mail\n  no_phone — True when the contact has opted OUT of phone calls\n  time_stamp — Last modification of the contact block\n  REFERENCES\n  contact\n  ship_to_id — joins ls_ship_tos",
  "ls_credit_accounts": "source_lightspeed.ls_credit_accounts — one row per credit account: either a customer store account or a gift card.\n  Two different instruments share this endpoint and this table.\n  primary key: credit_account_id\n  credit_account_id — Unique numeric id of the credit account or gift card\n  name — Label for the account\n  code — For gift cards, the barcode or numeric id scanned at the point of sale; documented as 8 to 32 characters and empty for customer credit accounts\n  description — Free-text description of the account, typically empty\n  gift_card — True = a gift card (bearer code with monetary value, no customer), false = a customer store account\n  archived — True when the account is archived\n  customer_id — Foreign key to the owning customer. joins ls_customers\n  balance — Current balance in store currency, signed from the STORE'S receivable viewpoint per the official reference: POSITIVE = the customer owes the store (o…\n  contact_id — Contact block attached to the account, available only when the Contact relation is requested. joins ls_contacts\n  time_stamp — Last modification of the record, which in practice means the last time the balance moved\n  REFERENCES",
  "ls_currency_denominations": "source_lightspeed.ls_currency_denominations — one physical currency denomination available in a locale.\n  The note and coin denominations defined for a locale.\n  primary key: locale_id, currency_denominations\n  locale_id — Owning locale\n  currency_denominations — Face value of the note or coin in the locale currency\n  REFERENCES",
  "ls_currency_rates": "source_lightspeed.ls_currency_rates — one row per foreign currency exchange rate the merchant maintains.\n  Manually maintained foreign-exchange rates used for multi-currency work.\n  primary key: currency_rate_id\n  currency_rate_id — Unique numeric id of the rate record (/Account/{accountID}/CurrencyRate/{currencyRateID})\n  currency_code — ISO currency code the rate applies to (USD, CAD...)\n  rate — Exchange rate of the given currency relative to the account's base currency, documented as (given currency / account currency)\n  create_time — When the currency-rate record was created, in the shop's timezone\n  time_stamp — When the rate record was last modified, in the shop's timezone\n  REFERENCES",
  "ls_custom_field_choices": "source_lightspeed.ls_custom_field_choices — one row per selectable option on a single_choice or multi_choice custom field.\n  The picklist options behind choice-typed custom fields: the option's id, its display name, an optional distinct stored value, and whether it can still be deleted.\n  primary key: custom_field_choice_id\n  custom_field_choice_id — Unique numeric id of the choice\n  custom_field_id — Foreign key to the owning custom field definition in ls_custom_fields. joins ls_custom_fields\n  name — The label shown to staff for this option\n  value — An optional stored string value that differs from the display name (e.g. name 'Gold Member', value 'GOLD')\n  can_be_deleted — False when the choice is in use somewhere and therefore cannot be removed\n  time_stamp — Last modification of the choice\n  REFERENCES",
  "ls_custom_fields": "source_lightspeed.ls_custom_fields — one row per custom field definition available on customers.\n  The schema for store-defined customer attributes: name, data type, units, rounding precision, archive state and default value.\n  primary key: custom_field_id\n  custom_field_id — Unique numeric id of the custom field definition\n  type — The declared data type, which controls both the validation applied on write and how the stored value must be parsed on read\n  name — The label staff see for the field\n  uom — Unit of measure for the field, up to four characters (e.g. 'kg', 'cm')\n  decimal_precision — Number of decimal places floats are rounded to\n  archived — True when the field definition is archived\n  default — The default CustomFieldValue applied when the field is first set, typed according to type (so it may be a scalar or a CustomFieldChoice object — stor…\n  REFERENCES",
  "ls_customer_custom_field_values": "source_lightspeed.ls_customer_custom_field_values — one row per custom field value recorded on one customer.\n  The store-defined attributes actually recorded against customers: one row per (customer, custom field) pair, carrying the value plus a snapshot of the field's name and type at read time.\n  primary key: custom_field_value_id\n  custom_field_value_id — Primary key of this individual value record\n  customer_id — The customer this value belongs to, taken from the parent record the relation was loaded on. joins ls_customers\n  custom_field_id — Foreign key to the field definition in ls_custom_fields. joins ls_custom_fields\n  name — The field's name copied onto the value for convenience\n  type — The field's type copied onto the value, also only updatable on the definition\n  value — The stored value, preserved as JSON because its shape depends on the field type: a scalar for string/text/url/email/integer/float/boolean/date/dateti…\n  custom_field_choice_id — For single_choice fields, the selected choice id lifted out of value_raw so it can be joined to ls_custom_field_choices. joins ls_custom_field_choices\n  deleted — The delete flag: setting it true on an update of the parent is how a value is removed\n  time_stamp — Last modification of this value\n  REFERENCES",
  "ls_customer_notes": "source_lightspeed.ls_customer_notes — one row per note attached to a customer.\n  Free-text notes staff attach to a customer record, with a flag controlling whether the text is printed on receipts.\n  primary key: note_id\n  note_id — Unique numeric id of the note\n  customer_id — The customer this note hangs off, taken from the parent record the relation was loaded on. joins ls_customers\n  note — The note text\n  is_public — True when the note is shown on receipts and other customer-facing output; false when it is internal-only\n  time_stamp — Last modification of the note\n  REFERENCES",
  "ls_customer_types": "source_lightspeed.ls_customer_types — one row per customer type (segment definition).\n  Lookup of customer segments such as VIP, Club, Wholesale or Staff.\n  primary key: customer_type_id\n  customer_type_id — Unique numeric id of the segment\n  name — Description/name of the customer type as shown in the POS Type field\n  tax_category_id — Foreign key to the TaxCategory automatically applied at the register when a customer of this type is attached — the mechanism behind tax-exempt segme…. joins ls_tax_categories\n  discount_id — Foreign key to the Discount automatically applied at the register for this type. joins ls_discounts\n  REFERENCES",
  "ls_customers": "source_lightspeed.ls_customers — one row per Customer record (one POS customer identity, account-wide, not one human being).\n  The CRM master record: names, company/tax identifiers, date of birth, archive state, and the foreign keys that drive register behaviour (customer type, discount, tax category, store credit account).\n  primary key: customer_id\n  customer_id — Unique numeric id of this POS customer identity\n  first_name — Customer's given name\n  last_name — Customer's family name\n  dob — Documented as the customer's date of birth, stored as a datetime at store-local midnight, so only the date part is meaningful\n  archived — True when the customer has been archived\n  title — The customer's JOB title (e.g. Purchasing Manager) — not an honorific like Mr/Ms, and not a record label\n  company — Name of the company this customer belongs to\n  company_registration_number — The customer's company registration number (ABN/company number depending on locale)\n  vat_number — The customer's VAT/GST registration number, as text\n  create_time — When the customer record was created, i.e. when this identity first entered the system\n  time_stamp — Last modification of the record\n  credit_account_id — Foreign key to the customer's store credit account in ls_credit_accounts. joins ls_credit_accounts\n  customer_type_id — Foreign key to ls_customer_types (the segment: VIP, Club, Wholesale, Staff...). joins ls_customer_types\n  discount_id — Foreign key to the Discount (pricing domain) auto-applied at the register for this customer. joins ls_discounts\n  tax_category_id — Foreign key to the TaxCategory (tax domain, canonical tax_code) that overrides normal tax for this customer, e.g. tax-exempt bodies or export custome…. joins ls_tax_categories\n  contact_id — Id of the Contact block carrying this customer's emails, phones, postal address and marketing opt-outs. joins ls_contacts\n  contact — Raw Contact subtree kept verbatim for anything the normalised tables do not flatten\n  custom_field_values — Raw CustomFieldValues subtree, NULL when the customer has none\n  REFERENCES",
  "ls_discounts": "source_lightspeed.ls_discounts — one row per named Discount rule that staff or the system can apply to a sale or a sale line.\n  The catalogue of reusable discount rules — their names, amounts/percentages, and what kind of discount they are (price rule, loyalty, or manual discount rule).\n  primary key: discount_id\n  discount_id — Unique numeric identifier for the discount rule\n  name — The merchant-defined description/name staff see when applying the rule\n  discount_amount — Dollar amount off, in store currency\n  discount_percent — Percentage off stored as a FRACTION of 1 — the docs cap it at <= 1.00 (100%)\n  require_customer — True when a customer must be attached to the sale before the rule can be applied (club, trade and loyalty rules)\n  archived — True when the rule is retired\n  source_id — What KIND of discount this is\n  time_stamp — When the rule record was last modified, store-local\n  REFERENCES",
  "ls_employee_hours": "source_lightspeed.ls_employee_hours — one row per clock-in/clock-out entry for one employee at one shop.\n  Time-clock entries recorded when employees clock in and out of the POS.\n  primary key: employee_hours_id\n  employee_hours_id — Unique numeric id of the clock entry (/Account/{accountID}/EmployeeHours/{employeeHoursID})\n  check_in — Start of the clock-in entry, in the shop's timezone\n  check_out — End of the clock-in entry, in the shop's timezone\n  employee_id — Foreign key to the Employee this entry belongs to (/Account/{accountID}/Employee/{employeeID}). joins ls_employees\n  shop_id — Foreign key to the Shop where the clock in/out physically happened (/Account/{accountID}/Shop/{shopID}). joins ls_shops\n  REFERENCES",
  "ls_employee_rights": "source_lightspeed.ls_employee_rights — one row per (employee, right) grant made directly to an employee -- effective only when that employee has no role.\n  Per-employee rights, exploded from the EmployeeRights collection nested directly under Employee.\n  primary key: employee_id, employee_right_id\n  employee_id — The employee the right is attached to directly, carried down from the parent Employee object. joins ls_employees\n  employee_right_id — Unique numeric id of the right/privilege, from the same catalogue as ls_employee_role_rights.employee_right_id\n  name — The right's name as Lightspeed defines it\n  REFERENCES",
  "ls_employee_role_rights": "source_lightspeed.ls_employee_role_rights — one row per (role, right) grant -- one right conferred by one role.\n  The bridge between a role and the individual rights/privileges it confers, exploded from the EmployeeRights collection nested under EmployeeRole.\n  primary key: employee_role_id, employee_right_id\n  employee_role_id — The role conferring this right, carried down from the parent EmployeeRole object during the explode. joins ls_employee_roles\n  employee_right_id — Unique numeric id of the right/privilege\n  name — The right's name as Lightspeed defines it (e.g. discount-application, void, price-override, reporting access)\n  REFERENCES",
  "ls_employee_roles": "source_lightspeed.ls_employee_roles — one row per employee role defined on the account.\n  Named permission roles (e.g. Manager, Sales Associate) that bundle a set of rights and are assigned to employees via Employee.employeeRoleID.\n  primary key: employee_role_id\n  employee_role_id — Unique numeric id for the role\n  name — Display name of the role as configured by the merchant (e.g. 'Manager', 'Cashier')\n  REFERENCES",
  "ls_employees": "source_lightspeed.ls_employees — one row per employee login on the account, including archived former staff.\n  Biographical and account-login information for staff: names, lock-out and archive state, which role (and therefore which rights) they hold, which shop they are restricted to, and a set of live 'currently attached to' po….\n  primary key: employee_id\n  employee_id — Unique numeric id for the staff login\n  first_name — Employee's given name\n  last_name — Employee's family name\n  lock_out — True when the employee is locked out of the system and cannot log in to the POS\n  archived — True for former staff\n  contact_id — Foreign key to the Contact record with the employee's phone, email and address. joins ls_contacts\n  clock_in_employee_hours_id — Foreign key to the EmployeeHours record the employee is CURRENTLY clocked in under (/Account/{accountID}/EmployeeHours/{clockInEmployeeHoursID})\n  employee_role_id — Foreign key to the employee's role, which specifies their rights. joins ls_employee_roles\n  limit_to_shop_id — Foreign key to the single Shop this login is restricted to (/Account/{accountID}/Shop/{limitToShopID})\n  last_shop_id — The shop the employee is currently -- or was most recently -- attached to (/API/Account/Shop/{lastShopID})\n  last_sale_id — The sale the employee is currently, or was last, working on (/Account/{accountID}/Sale/{lastSaleID})\n  last_register_id — The register the employee is currently, or was last, attached to (/Account/{accountID}/Register/{lastRegisterID})\n  time_stamp — When the employee record was last modified, in the shop's timezone\n  contact — The employee's full Contact record from load_relations=Contact: Phones.ContactPhone, Emails.ContactEmail, Addresses.ContactAddress\n  REFERENCES",
  "ls_images": "source_lightspeed.ls_images — one product image, attached to EITHER an item or a matrix (exactly one of the two).\n  Product photo metadata hosted on Lightspeed's Cloudinary account.\n  primary key: image_id\n  image_id — Primary key of the image record\n  item_id — The single item this photo belongs to, or NULL/0 when the photo is attached at matrix level instead. joins ls_items\n  item_matrix_id — The variant family this photo belongs to, or NULL/0 when it is attached to a single item. joins ls_item_matrices\n  description — Caption or alt text for the image\n  filename — Original filename of the upload\n  ordering — Display sequence among a product's images\n  public_id — The Cloudinary public id used to retrieve the image\n  REFERENCES",
  "ls_industries": "source_lightspeed.ls_industries — one row per Lightspeed catalog industry vertical, with its enabled state for this account.\n  Lightspeed's built-in retail verticals (Bicycles, Jewelry, Pet, Golf...) and whether each is switched on for this account.\n  primary key: industry_id\n  industry_id — Unique numeric id for the industry vertical\n  name — Name of the industry vertical (Bicycles, Skateboards, Motorcycles...)\n  enabled — True when the vertical is switched on for THIS account\n  REFERENCES",
  "ls_inventory_count_calcs": "source_lightspeed.ls_inventory_count_calcs — one item within one inventory count (the system-vs-physical rollup for that item/count pair).\n  The scoreboard of a stocktake: for each item in a count, what the system thought was on hand (calc_qoh) versus what people physically found (counted_qoh).\n  primary key: inventory_count_calc_id\n  inventory_count_calc_id — Unique id of this item's rollup within a count\n  time_stamp — Modified date/time of this rollup: the last time a count entry was recorded for THIS item in THIS count\n  calc_qoh — What the system believed the business should have in stock — the 'book' side of the variance\n  counted_qoh — The physical amount counted — the sum of every ls_inventory_count_items.qty entry for this item in this count\n  inventory_count_id — The stocktake this rollup belongs to\n  item_id — The item this rollup is for. joins ls_items\n  REFERENCES",
  "ls_inventory_count_items": "source_lightspeed.ls_inventory_count_items — one physical counting act — one item counted once by one employee at one moment (counting the same item three times creates three rows).\n  The keystroke-level record of a stocktake: each quantity an employee entered, when, for which item.\n  primary key: inventory_count_item_id\n  inventory_count_item_id — Unique id of this single count entry\n  qty — The quantity found in this one counting act\n  time_stamp — The date/time at which the count was made\n  inventory_count_id — The stocktake this entry belongs to\n  item_id — The item that was counted. joins ls_items\n  employee_id — Employee who physically made this count entry. joins ls_employees\n  REFERENCES",
  "ls_inventory_count_reconciles": "source_lightspeed.ls_inventory_count_reconciles — one reconcile posting — one item's stock and cost adjustment applied when a count was reconciled.\n  The posted result of a stocktake: the adjustment actually written to the books for each item, in units and in cost value.\n  primary key: inventory_count_reconcile_id\n  inventory_count_reconcile_id — Unique id of this reconcile posting\n  create_time — When the reconcile was performed — the moment the books actually moved\n  cost_change — The cost VALUE of the adjustment: the amount lost (negative) or gained (positive) to the books for this item, ex tax, in store currency\n  qoh_change — The stock-level change applied by the reconcile: negative means the count found FEWER units than the books claimed (shrinkage written off), positive…\n  inventory_count_id — The stocktake being reconciled\n  item_id — The item adjusted. joins ls_items\n  REFERENCES",
  "ls_inventory_logs": "source_lightspeed.ls_inventory_logs — one inventory change event — one item's stock level changing in one shop, for one reason, at one moment.\n  The inventory movement ledger: every stock change with why it happened (sale, purchase-order receive, transfer, manual adjustment, stocktake correction, refund, auto-add, bulk import) and who caused it.\n  primary key: inventory_log_id\n  inventory_log_id — Unique id of the movement event\n  create_time — When the stock change happened, store-local time\n  qoh_change — Units added (positive) or removed (negative) by this event\n  cost_change — Despite the '-Change' name this is NOT a delta: documented as 'the updated unit cost for the Item', i.e. the item's unit cost AFTER this event, ex ta…\n  automated — true when Lightspeed itself made the change (a sale deducting stock, a PO receive posting); false when a human typed an adjustment\n  reason — Machine-named cause of the change\n  caused_negative — true when this specific event pushed the item's on-hand below zero in that shop — the exact moment an oversell happened\n  employee_id — Employee who made or triggered the change. joins ls_employees\n  item_id — Item whose stock changed. joins ls_items\n  shop_id — Shop where the change happened; 0/NULL means unattributed. joins ls_shops\n  order_id — Purchase order whose receiving caused the change. joins ls_purchase_orders\n  transfer_id — Inter-shop transfer that caused the change. joins ls_transfers\n  sale_id — Sale that caused the change. joins ls_sales\n  inventory_count_id — Stocktake that caused the change\n  customer_id — Customer associated with the change — set on special-order and layaway reservation movements. joins ls_customers\n  vendor_return_id — Vendor return (RMA) that caused the change: stock sent back to a supplier, so qoh_change is normally negative. joins ls_vendor_returns\n  item_import_id — Bulk item import that caused the change — a spreadsheet load setting stock levels\n  REFERENCES",
  "ls_item_attribute_sets": "source_lightspeed.ls_item_attribute_sets — one attribute-set definition (the schema of a matrix's variant axes).\n  Tiny lookup that names what the attribute1/2/3 slots on items and matrices MEAN — e.g. attribute1 = Color, attribute2 = Size.\n  primary key: item_attribute_set_id\n  item_attribute_set_id — Primary key\n  name — Name of the set\n  attribute_name1 — Label for the first axis — documented as 'Color' or the generic 'Attribute 1'\n  attribute_name2 — Label for the second axis — documented as 'Size' or 'Attribute 2'\n  attribute_name3 — Label for the third axis — 'Attribute 3'\n  REFERENCES",
  "ls_item_components": "source_lightspeed.ls_item_components — one component line: the link between one assembly/box item and one of the items it is made from.\n  The bill of materials for box and assembly products — which single items make up a box, and how many of each.\n  primary key: item_component_id\n  item_component_id — Primary key of the component line\n  assembly_item_id — The parent: the box or assembly item being built\n  component_item_id — The child: the single item consumed to build the parent\n  quantity — How many units of component_item_id it takes to build ONE assembly_item_id\n  component_group — Discriminates the two relationship kinds that share this table\n  REFERENCES",
  "ls_item_fees": "source_lightspeed.ls_item_fees — one configured item fee definition.\n  The configuration list of fixed-amount surcharges that attach to item categories — tyre recycling levies, e-bike environmental fees and similar.\n  primary key: item_fee_id\n  item_fee_id — Primary key of the fee definition\n  name — Fee name as shown at the register and on the receipt line\n  calculation_method — How the fee amount is derived\n  fee_value — The monetary amount of the fee in store currency\n  taxable — True when tax is charged ON the fee itself\n  discountable — Nominally whether the fee can be discounted, but documented as currently providing NO extra functionality. deprecated\n  non_refundable — Nominally whether the fee can be refunded; documented as currently not in use. deprecated\n  archived — True when the fee is retired and can no longer be used within a transaction\n  create_time — When the fee was configured — the earliest date its sale lines can appear\n  timestamp — When the fee was last updated\n  item_fee_categories — Raw list of the item categories the fee attaches to\n  REFERENCES",
  "ls_item_matrices": "source_lightspeed.ls_item_matrices — one matrix — one variant family of items (e.g. one jersey that exists in five sizes).\n  The product-family layer above ls_items: family-level identity, defaults and the attribute set that defines the variant axes.\n  primary key: item_matrix_id\n  item_matrix_id — Primary key of the variant family\n  description — Family-level product name\n  item_type — Type default inherited by the family's items\n  serialized — True when units in this family carry serial numbers (typical for bike model families)\n  tax — Whether tax is charged on this family's items\n  default_cost — Family-level reorder cost, ex tax, used to seed inventory cost\n  model_year — Model year of the family (e.g. 2024)\n  archived — True when the family is retired\n  category_id — Category default for the family. joins ls_categories\n  tax_class_id — Tax class default for the family. joins ls_tax_classes\n  department_id — Legacy department grouping. deprecated\n  manufacturer_id — Brand of the family (who makes it), not the supplier. joins ls_manufacturers\n  season_id — Legacy season grouping; Seasons are deprecated by Lightspeed. deprecated. joins ls_seasons\n  default_vendor_id — Default supplier for the family\n  item_attribute_set_id — Which attribute-set definition shapes the family's variant axes (Color/Size, Size, Color, 3 Attributes). joins ls_item_attribute_sets\n  time_stamp — When the matrix record was last modified\n  attribute_name1 — Label of the family's first variant axis (typically 'Color'); pairs with ls_items.attribute_1 on the children\n  attribute_name2 — Label of the second variant axis (typically 'Size')\n  attribute_name3 — Label of the third variant axis; only meaningful for the '3 Attributes' set\n  tax_class — Raw tax-class object\n  department — Raw department object for the family. deprecated\n  custom_field_values — Raw account-defined custom field values on the matrix\n  REFERENCES\n  full_path_name\n  name",
  "ls_item_prices": "source_lightspeed.ls_item_prices — one price level amount on one item — the unique key is (item_id, use_type_id), not item_id alone.\n  Every configured price level for every item: Default, MSRP, Online and any account-defined level.\n  primary key: item_id, use_type_id\n  item_id — The item the price belongs to. joins ls_items\n  use_type_id — Numeric FK to the pricing level definition (ls_price_levels.price_level_id)\n  use_type — Human name of the price level, which also indicates how the level is applied\n  amount — The price at this level, in store currency, following the account's tax-inclusive setting (tax-inclusive jurisdictions: it INCLUDES tax, unlike costs…\n  REFERENCES\n  archived\n  description",
  "ls_item_shops": "source_lightspeed.ls_item_shops — one item's stock record at one location; shop_id = 0 is the account-wide aggregate, so use it alone for whole-business stock and only shop_id > 0 for per-shop breakdowns.\n  The current stock position per item per shop: quantity on hand, what is sellable, what is on order, and the reorder thresholds.\n  primary key: item_shop_id\n  item_shop_id — Primary key of this item-in-shop stock record\n  item_id — The item this stock row belongs to. joins ls_items\n  shop_id — The shop holding the stock — EXCEPT 0, which is documented as a summary record containing the QOH for all shops combined. joins ls_shops\n  qoh — Units physically on hand\n  sellable — Units the POS will let you sell: identical to qoh except it clamps at 0 when qoh is negative\n  backorder — Units already committed on a purchase order but not yet received — 'on order' in shop language\n  component_qoh — Additional units of this item that could be produced by breaking down or building up boxes/assemblies that are themselves in stock\n  component_backorder — Additional units obtainable from boxes/assemblies that are currently on order rather than in stock\n  reorder_point — Threshold: when qoh is at or below this, the item is considered due for reorder in this shop\n  reorder_level — Target stock level to reach when reordering: an automatic reorder adds (reorder_level - qoh) units\n  time_stamp — When this stock record last changed\n  description — Denormalised product name from the parent item, so stock rows are readable without a join\n  archived — Parent item's archived flag\n  item_type — Parent item type, carried here because non_inventory rows must be excluded from every stock count and valuation — their quantities are meaningless\n  avg_cost — Parent item's account-wide weighted average unit cost, ex tax\n  category_id — Parent item's category. joins ls_categories\n  manufacturer_id — Parent item's brand, for brand-level stock rollups without a join. joins ls_manufacturers\n  REFERENCES",
  "ls_item_vendor_nums": "source_lightspeed.ls_item_vendor_nums — one vendor-specific SKU: one item as catalogued by one vendor.\n  The cross-reference between the shop's items and the part numbers its suppliers use, with the per-vendor buy cost when vendor-cost functionality is enabled.\n  primary key: item_vendor_num_id\n  item_vendor_num_id — Primary key of the item-vendor cross-reference row\n  item_id — The shop's item this vendor SKU refers to. joins ls_items\n  vendor_id — The supplier that uses this SKU. joins ls_vendors\n  value — The vendor's own part number for the item — the string you put on a purchase order\n  cost — The buy cost from THIS vendor, ex tax\n  time_stamp — When this cross-reference row was last modified\n  REFERENCES",
  "ls_items": "source_lightspeed.ls_items — one catalogue item — a single sellable SKU.\n  The product master: identity, SKUs/barcodes, categorisation, current price levels, cost basis and the flags that govern tax, discounting and stock behaviour.\n  primary key: item_id\n  item_id — Stable primary key of the SKU across the whole account; the join target for sale lines, stock rows, images, serial numbers and order lines\n  system_sku — The barcode Lightspeed generates and prints on shelf labels (e.g. 210000000004)\n  default_cost — Expected per-unit reorder cost from the supplier, EXCLUSIVE of tax\n  avg_cost — Weighted average unit cost of ALL purchases of this item ever, including stock already sold, EXCLUSIVE of tax\n  tax — True when sales tax/GST is charged on this item at the register\n  archived — True when the item has been retired\n  discountable — True when cashiers may apply a discount to this line at the register\n  item_type — What kind of thing the SKU is, which decides whether its stock number means anything\n  serialized — True when every unit gets a serial number captured at sale\n  description — The product name printed on receipts and labels\n  model_year — Model year of the product (e.g. 2008, 2024). deprecated\n  upc — UPC barcode, 11-14 digits\n  ean — EAN barcode, 11-14 digits — the international sibling of upc, usually empty when upc is populated\n  custom_sku — The shop's own internal SKU, entered by staff\n  manufacturer_sku — The manufacturer's own part number\n  time_stamp — When the item RECORD was last edited\n  create_time — When the SKU was first created in the catalogue\n  publish_to_ecom — Flag requesting publication to Lightspeed eCom\n  category_id — The single category node this item hangs off, at any depth of the tree. joins ls_categories\n  tax_class_id — Which tax class governs the item's rate. joins ls_tax_classes\n  department_id — Legacy department grouping. deprecated\n  item_matrix_id — The variant family this SKU belongs to: all sizes/colours of one product share it. joins ls_item_matrices\n  manufacturer_id — Who MAKES the product (brand). joins ls_manufacturers\n  season_id — Legacy season grouping. deprecated. joins ls_seasons\n  default_vendor_id — The supplier the shop reorders this item from by default\n  tax_class — Raw tax-class object as returned\n  note — Raw note object attached to the item (staff notes; public notes also print on receipts)\n  custom_field_values — Raw account-defined custom field values\n  attribute1 — First variant axis VALUE for a matrix item, conventionally the colour\n  attribute2 — Second variant axis value, conventionally the size\n  attribute3 — Third variant axis value; only used by the '3 Attributes' attribute set\n  item_attribute_set_id — Which attribute-set definition explains this item's attribute_1/2/3. joins ls_item_attribute_sets\n  attribute_name1 — Label for variant axis 1 (typically 'Color')\n  attribute_name2 — Label for variant axis 2 (typically 'Size')\n  attribute_name3 — Label for variant axis 3 ('Attribute 3')\n  item_e_commerce_id — Id of the item's eCommerce info record\n  long_description — Long-form marketing copy for the item\n  short_description — Short marketing blurb\n  weight — Item weight\n  width — Item width, unitless per the API — same unit caveat as weight\n  height — Item height, unitless per the API\n  length — Item length, unitless per the API\n  list_on_store — Whether the item is flagged to be sold online\n  amount_where_use_type_default — TODAY's shelf/register selling price at the Default price level\n  amount_where_use_type_msrp — Manufacturer's suggested retail price level\n  REFERENCES\n  full_path_name\n  name",
  "ls_locales": "source_lightspeed.ls_locales — one row per locale Lightspeed publishes globally (a global catalogue, not the account's own setting).\n  The global list of locales available across Lightspeed and their formatting/currency attributes: currency symbol and code, decimal precision, cash-rounding increment, tax naming, date formats and language tag.\n  primary key: name\n  name — Name of the locale\n  country — Country the locale belongs to\n  states — States/provinces within the locale, published as a string rather than a structured collection\n  currency_symbol — Currency symbol used for display in this locale\n  currency_code — ISO currency code of the locale\n  currency_precision — Number of decimal places the currency is stored/displayed to\n  cash_rounding_precision — Smallest unit of currency actually used in CASH transactions -- e.g. 0.05 where 1c and 2c coins were withdrawn (AU, CA, NZ)\n  include_tax_on_labels — Whether product labels in this locale print tax-inclusive prices\n  language_tag — Language tag per ISO 639-1 (e.g. 'en', 'fr')\n  date_format — Date format string for the locale, in the API's own format syntax (e.g. 'd/m/Y' style PHP tokens, not strftime and not ISO)\n  datetime_format — Date-and-time format string for the locale, same token syntax caveat as date_format\n  tax_name1 — Name of the locale's first tax (GST, VAT, State Tax, TPS...)\n  tax_name2 — Name of the locale's second tax, for two-tier regimes such as Canadian GST + PST/QST\n  currency_denominations — The locale's note and coin denominations, kept as a JSON blob\n  REFERENCES",
  "ls_manufacturers": "source_lightspeed.ls_manufacturers — one manufacturer (brand).\n  The brand list: who MAKES the products.\n  primary key: manufacturer_id\n  manufacturer_id — Primary key of the brand\n  name — Brand name\n  create_time — When the brand was added to the account\n  time_stamp — When the brand record was last modified (typically a rename)\n  REFERENCES",
  "ls_options": "source_lightspeed.ls_options — one account option: a name/value pair the account has turned on.\n  The account's feature switches as name/value strings.\n  primary key: name\n  name — The option's identifier\n  value — The option's value, always delivered as a string even when it represents a boolean or a number\n  REFERENCES",
  "ls_order_shipment_items": "source_lightspeed.ls_order_shipment_items — one product's receipt within one shipment (one row per ShipmentItem).\n  One row per item received in a shipment: how many units of that product landed in that delivery, its cost before freight, its allocated freight and discount, and its final landed cost.\n  primary key: order_shipment_item_id\n  order_shipment_item_id — Unique id of this item-within-shipment row\n  order_shipment_id — Parent shipment; joins ls_order_shipments.order_shipment_id. joins ls_order_shipments\n  qty_received — Units of this item received in THIS delivery — a per-delivery event quantity, safe to sum over time, unlike the running counters on ls_purchase_order…\n  vendor_cost — Item cost in the VENDOR's currency before freight and discount\n  cost — Item cost in the merchant's default currency before freight and discount\n  total_vendor_cost — Total LANDED cost of this item within this shipment, in the vendor's currency — goods plus allocated freight, net of allocated discount\n  total_cost — Total LANDED cost of this item within this shipment in merchant currency — the true inventory value added by this receipt, and the numerator for real…\n  shipping_cost — Freight allocated to this item in merchant currency, already included in total_cost\n  shipping_vendor_cost — Freight allocated to this item in the vendor's currency; the currency twin of shipping_cost, not an extra charge\n  discount_money_value — Discount allocated to this item in merchant currency, already netted off total_cost\n  discount_money_vendor_value — Discount allocated to this item in the vendor's currency — currency twin of discount_money_value\n  discount_percent_value — Discount percentage applied to this item, in whole-percent units (5 = 5%)\n  currency_code — The merchant's default currency code for this row's non-vendor money columns, frozen when the shipment was created\n  vendor_currency_code — The vendor's currency code — the unit for every *_vendor_* money column on this row\n  vendor_currency_rate — Exchange rate from vendor to merchant currency captured AT SHIPMENT CREATION — historic and frozen, so re-converting old receipts at a current rate i…\n  create_time — When this item row was created, i.e. when the line was keyed during check-in\n  time_stamp — Last update of this item row and the sync high-water mark\n  item_id — The product received; joins the products domain (canonical `product_variant`). joins ls_items\n  item_vendor_id — The VENDOR's own SKU for this item — a STRING despite the '...ID' name, and not a foreign key to anything in Lightspeed\n  item_description — The item's description as captured on this receipt — a point-in-time snapshot, so it can differ from the product's current name after a rename\n  REFERENCES",
  "ls_order_shipments": "source_lightspeed.ls_order_shipments — one shipment (receiving event) against one purchase order.\n  One row per delivery received against a purchase order: how many units landed, the landed cost of that delivery, the freight and discount allocated to it, and who received it when.\n  primary key: order_shipment_id\n  order_shipment_id — Unique id of the shipment across the whole account (not per order — that is sequence_number)\n  order_id — The purchase order this delivery was received against; joins ls_purchase_orders.order_id. joins ls_purchase_orders\n  sequence_number — The delivery's number WITHIN its purchase order (1 = first delivery, 2 = second)\n  total_qty_received — Total units received in THIS delivery, summing its items\n  total_vendor_cost — Total LANDED cost of everything in this shipment expressed in the VENDOR's currency — goods plus allocated freight, net of allocated discount\n  total_cost — Total LANDED cost of this shipment in the merchant's default currency — goods plus allocated freight, net of allocated discount\n  currency_code — The merchant's DEFAULT currency code at the time this shipment was created (e.g. 'AUD') — the unit for every non-vendor money column here\n  vendor_currency_code — The vendor's currency code, the unit for every *_vendor_cost / *_vendor_value column on this row\n  vendor_currency_rate — Exchange rate from vendor currency to merchant currency CAPTURED AT SHIPMENT CREATION\n  create_time — When the shipment RECORD was created (keyed by staff)\n  payment_due_date — Date the supplier's invoice for this delivery falls due — a DATE with no time component, populated only when the receiver entered the invoice terms\n  shipment_packing_ref_num — Reference number for the shipment as typed by staff — in practice the packing slip or supplier invoice number\n  time_stamp — Last update of the shipment record and the incremental-sync high-water mark\n  employee_id — Employee who received/checked in this delivery; joins the workforce domain (canonical `worker`). joins ls_employees\n  reception_date — When the goods were actually received\n  shipping_cost_method — How the freight charged to this shipment was spread across its items\n  shipping_vendor_cost — Freight allocated to THIS shipment, in the vendor's currency\n  shipping_cost — Freight allocated to THIS shipment, in merchant currency, and already included inside total_cost\n  shipping_cost_order_full_value — The FULL freight applied to the whole purchase order, in merchant currency, repeated on every shipment row of that order as context\n  shipping_cost_order_full_vendor_value — The full whole-PO freight in the vendor's currency, repeated on every shipment row\n  discount_method — How the discount charged to this shipment was spread across its items, mirroring shipping_cost_method\n  discount_money_vendor_value — Discount allocated to THIS shipment in the vendor's currency\n  discount_money_value — Discount allocated to THIS shipment in merchant currency, already netted off total_cost\n  discount_percent_value — Discount percentage applied on the shipment, in whole-percent units (5 = 5%)\n  discount_order_full_money_value — The FULL discount applied to the whole purchase order in merchant currency, repeated on every shipment row as context\n  discount_order_full_money_vendor_value — The full whole-PO discount in the vendor's currency, repeated on every shipment row\n  cost — Goods cost of the items in this shipment BEFORE freight and discount, merchant currency\n  vendor_cost — Goods cost of the items in this shipment before freight and discount, in the VENDOR's currency\n  status — Lifecycle state of the shipment, constrained by the docs to two values\n  REFERENCES",
  "ls_payment_types": "source_lightspeed.ls_payment_types — one tender method configured on the account.\n  The tender methods available at the register (Cash, Credit Card, Gift Card, Credit Account, ...), including their refund routing and whether a customer must be attached.\n  primary key: payment_type_id\n  payment_type_id — Unique id of the tender method; the join target for SalePayment.paymentTypeID, RegisterWithdraw, RegisterCount and ls_report_payments_by_day.payment_…\n  name — Display name of the tender as staff see it at the register ('Cash', 'Credit Card', 'Debit Card', 'Gift Card', 'Check')\n  require_customer — true when a customer record must be attached to the sale before this tender may be used\n  archived — true when the tender has been retired from the register\n  internal_reserved — true for predefined system tenders that a store cannot edit or delete (the set published in the API's Defined Values section)\n  type — The tender FAMILY, used for grouping takings into cash/card/gift/account buckets\n  refund_as_payment_type_id — The tender that refunds of this tender must be issued as (e.g. Gift Card refunds as Gift Card, Credit Account as Credit Account)\n  REFERENCES",
  "ls_price_levels": "source_lightspeed.ls_price_levels — one price level definition on the account.\n  The definitions behind the price levels that ls_item_prices rows reference: their names, whether they are archived, their type, and the calculation parameters used to derive prices from cost.\n  primary key: price_level_id\n  price_level_id — Primary key of the price level\n  name — Display name of the level (Default, MSRP, Online, or an account-defined label)\n  archived — True when the level is retired\n  can_be_archived — Whether Lightspeed permits archiving this level — false on built-in levels such as Default\n  type — The kind of price level\n  calculation — Raw parameters used to derive a price from cost (markup/margin rules)\n  REFERENCES",
  "ls_processing_fees": "source_lightspeed.ls_processing_fees — one row per ProcessingFee — one fee record the payment processor assessed against one SalePayment.\n  What card acceptance actually costs, per payment, broken into fixed/variable components with interchange and scheme sub-breakdowns.\n  primary key: sale_payment_processing_fee_id\n  sale_payment_processing_fee_id — Unique identifier of the processing fee record\n  sale_payment_id — The SalePayment the fee was assessed on. joins ls_sale_payments\n  processing_fee_ref — The processor's external reference id for this fee line — the key for tying a fee back to a line on a processor statement\n  processor — Name of the payment processor handling the transaction\n  amount — TRAP: this is the total PAYMENT amount the fee was linked to, NOT the fee itself\n  fixed_fee — The fixed, per-transaction component of the fee, in store currency\n  variable_fee — The rate-based component of the fee, in store currency\n  variable_pct — The rate used to calculate variable_fee\n  interchange_fees_fixed_fee — Fixed portion of the interchange component (the part paid to the card-issuing bank)\n  interchange_fees_variable_fee — Variable portion of interchange, in currency\n  interchange_fees_variable_pct — The rate behind the variable interchange portion\n  scheme_fees_fixed_fee — Fixed portion of card-scheme fees (the part paid to the Visa/Mastercard network, distinct from interchange)\n  scheme_fees_variable_fee — Variable portion of card-scheme fees, in currency\n  scheme_fees_variable_pct — The rate behind the variable scheme portion\n  processing_time — When the processor remotely processed the fee — the settlement-side date\n  create_time — When the fee record was created inside Lightspeed\n  update_time — Last modification of the fee record\n  REFERENCES",
  "ls_purchase_order_lines": "source_lightspeed.ls_purchase_order_lines — one product line on one purchase order (one row per OrderLine).\n  One row per item line on a purchase order: which product, how many units were ordered, at what unit cost, and how many of them have physically landed.\n  primary key: order_line_id\n  order_line_id — Unique id of the PO line\n  order_id — Parent purchase order; joins ls_purchase_orders.order_id. joins ls_purchase_orders\n  item_id — The product being ordered; joins the products domain (canonical `product_variant`, since a Lightspeed Item is the sellable variant). joins ls_items\n  quantity — Units ORDERED on this line\n  price — Unit COST in the merchant's default currency, ALREADY adjusted for any order-level discount\n  original_price — Unit cost in merchant currency BEFORE any order-level discount\n  vendor_cost — Unit cost BEFORE order discount in the VENDOR's currency — the vendor-currency counterpart of unit_cost_original, and per the docs it should be used…\n  checked_in — Units checked in, meaning ADDED TO INVENTORY — the stock is on the shelf and counted in quantity-on-hand\n  num_received — Units received at the door but NOT yet added to inventory — physically present, invisible to stock-on-hand\n  total — Documented as quantity x price, so it is the discounted goods cost of the line in merchant currency and EXCLUDES the allocated shipping_cost\n  shipping_cost — This line's share of the PO-level freight, calculated down from the header in merchant currency\n  shipping_vendor_cost — The same allocated freight share expressed in the vendor's currency\n  discount_money_value — This line's share of the order-level discount as money in merchant currency\n  discount_money_vendor_value — This line's allocated discount share in the vendor's currency — the currency twin of discount_money_value, not a second discount\n  discount_percent_value — The order-level discount percentage as it lands on this line, in whole-percent units (5 = 5%)\n  create_time — When the line was added to the PO — which can be later than the order's own created_at when a buyer appends items, and can be the migration timestamp…\n  time_stamp — Last modification of the line and the sync high-water mark\n  vendor_id — Parent-projected and potentially unpopulated. joins ls_vendors\n  shop_id — Parent-projected and potentially unpopulated. joins ls_shops\n  complete — Parent-projected and potentially unpopulated\n  ordered_date — Parent-projected and potentially unpopulated\n  received_date — Parent-projected and potentially unpopulated\n  archived — Parent-projected and potentially unpopulated\n  vendor_currency_code — Parent-projected and potentially unpopulated\n  REFERENCES",
  "ls_purchase_orders": "source_lightspeed.ls_purchase_orders — one purchase order raised with one vendor for one shop (Lightspeed resource `Order`).\n  One row per PURCHASE ORDER: stock the business is buying from a supplier, with the header-level costs, discounts, currency and lifecycle flags.\n  primary key: order_id\n  order_id — Unique id of the purchase order and the join key for every child table (lines, shipments)\n  ordered_date — When the order was placed WITH the vendor\n  received_date — The date the order actually arrived\n  arrival_date — The date the order is EXPECTED to arrive — a promise/ETA typed by staff, not a system-computed date and not evidence anything arrived\n  ref_num — Free-text external reference, often the vendor's own order or invoice number\n  ship_instructions — Free-text instructions for the VENDOR or shipper about how to ship the order (carrier, consolidation, drop-ship address)\n  stock_instructions — Free-text instructions for the RECEIVING employees about how to stock the goods once they land (which bay, label runs, hold for customer)\n  ship_cost — Freight the vendor added to the order, in the MERCHANT's default currency\n  ship_vendor_cost — The same freight expressed in the VENDOR's currency\n  other_cost — Other vendor-added costs (handling, surcharges, duty recharges) in merchant currency\n  other_vendor_cost — Other vendor-added costs in the vendor's currency; same negative-means-discount convention as other_cost\n  complete — True once the order is marked complete, which usually happens after check-in finishes\n  archived — True when the PO is archived\n  total_discount — Total MONEY value of all discounts on the order, merchant currency — the realised sum, whichever discount family produced it\n  total_quantity — Total units ORDERED across all lines — a header rollup of ls_purchase_order_lines.quantity, and never units received\n  vendor_id — Supplier the PO is for; joins ls_vendors.vendor_id. joins ls_vendors\n  name — Denormalised supplier name from the embedded Vendor relation, for readable grouping without a join\n  note_id — Foreign key to the Note record holding the PO's free-text note. joins ls_customer_notes\n  shop_id — The shop (location) the stock is being ordered FOR, i.e. where it will be checked in — not necessarily where the buyer sits. joins ls_shops\n  created_by_employee_id — Employee who CREATED the PO — the buyer, not the person who later received it (that is ls_order_shipments.employee_id)\n  custom_field_values — Raw JSON of the account-defined custom fields attached to this PO\n  create_time — When the PO RECORD was created\n  time_stamp — Last modification of the record — the correct high-water mark for incremental syncs, and meaningless as a business date (a PO from 2019 touched yeste…\n  vendor_currency_rate — Exchange rate captured on the PO, defaulting to the vendor's rate: multiply vendor-currency amounts by this to reach merchant currency\n  vendor_currency_code — Currency code of the purchase order, defaulting to the vendor's currency (e.g. 'USD')\n  shipping_cost_method — How ship_cost is distributed to the lines\n  has_shipments — True when the PO has any shipment records\n  discount_method — How the order-level discount is distributed to the lines, mirroring shipping_cost_method\n  discount_money_value — The order-level discount expressed as MONEY in the merchant's currency\n  discount_money_vendor_value — The same order-level discount in the VENDOR's currency\n  discount_is_percent — True when the buyer typed the order discount as a percentage, false when as a fixed amount\n  discount_percent_value — Order-level discount percentage in whole-percent units (5 = 5%, not 0.05)\n  costs_modified_after_shipment — True when the shipping cost or discount changed AFTER the first shipment was created\n  b2b_order_uid — Opaque unique identifier of this order in NuORDER (Lightspeed's B2B wholesale platform)\n  b2b_order_number — Human-readable order number in NuORDER, the display counterpart to b2b_order_uid\n  REFERENCES\n  discount",
  "ls_quotes": "source_lightspeed.ls_quotes — one row per Quote — one saved, uncompleted sale held for a customer so it can be reloaded at the register later.\n  The pre-sale pipeline: quotes/invoices staff saved for customers.\n  primary key: quote_id\n  quote_id — Unique numeric id of the quote — the ONLY stable identifier here\n  issue_date — When the quote was issued, store-local\n  notes — Free-text notes on the quote\n  archived — True when the quote is retired\n  employee_id — Employee who started the quote. joins ls_employees\n  sale_id — The Sale record CURRENTLY holding this quote's contents. joins ls_sales\n  REFERENCES",
  "ls_receipt_setups": "source_lightspeed.ls_receipt_setups — one row per receipt setup configuration referenced by a shop.\n  Receipt print configuration: the header block, the general footer message, the workorder and credit-card agreement texts, and the logo image with its pixel dimensions.\n  primary key: receipt_setup_id\n  receipt_setup_id — Unique numeric id of the receipt configuration\n  header — Text printed at the TOP of the receipt\n  general_msg — General text printed at the end of ALL receipts (return policy, thanks, opening hours)\n  workorder_agree — Text printed at the end of workorder receipts, invoices and quotes only\n  creditcard_agree — Text printed at the end of a sales receipt that includes credit-card charges -- the cardholder agreement/signature wording\n  logo — RELATIVE URL of the logo image file, not an absolute URL and not the image bytes\n  logo_height — Logo image height in PIXELS as stored, not print millimetres\n  logo_width — Logo image width in PIXELS\n  REFERENCES",
  "ls_register_calculated": "source_lightspeed.ls_register_calculated — one payment type's live running total for one register's CURRENTLY OPEN session, as at the instant the endpoint was called.\n  The live 'what should be in this drawer right now' figure, broken down per payment type into the payments taken, the cash added and the cash withdrawn since the register was opened.\n  primary key: register_calculated_path_parameter_register_id, payment_type_id\n  register_calculated_path_parameter_register_id — The register these running totals belong to\n  payment_type_id — The tender this running total is for. joins ls_payment_types\n  payment — Running total of PAYMENTS taken on this tender since the register was opened — the sales-driven component of the expected drawer\n  add — Running total of the POSITIVE register-withdraw rows since open: the opening float plus any change top-ups\n  withdraw — Running total of the NEGATIVE register-withdraw rows since open: payouts and safe drops\n  REFERENCES",
  "ls_register_count_amounts": "source_lightspeed.ls_register_count_amounts — one payment type's expected-versus-counted pair inside one register close-out.\n  The per-tender detail of every till close-out: what the system calculated the drawer should hold for a payment type, against what a human physically counted.\n  primary key: register_count_amount_id\n  register_count_amount_id — Unique id for this one tender line of one close-out\n  register_count_id — The close-out this tender line belongs to. joins ls_register_counts\n  payment_type_id — The tender being counted (Cash, Credit Card, Gift Card, ...). joins ls_payment_types\n  calculated — The 'should have' side: what the system computed the drawer holds for this tender, built from payments taken on it during the session PLUS the signed…\n  actual — The physical amount a human counted for this tender at close\n  REFERENCES",
  "ls_register_counts": "source_lightspeed.ls_register_counts — one register close-out — the open-to-close session of a single till, written at the moment the closing count is submitted.\n  End-of-day (or end-of-shift) till close-out headers.\n  primary key: register_count_id\n  register_count_id — Unique id of this close-out\n  create_time — The moment the till was CLOSED and the count submitted\n  open_time — When this till session was opened\n  notes — Free text typed by staff at close\n  register_id — The till that was counted. joins ls_registers\n  open_employee_id — Employee who OPENED the session\n  close_employee_id — Employee who submitted the count and closed the till\n  REFERENCES",
  "ls_register_withdraws": "source_lightspeed.ls_register_withdraws — one cash add or payout at one register (a single signed drawer movement outside of sales).\n  Cash moving in and out of a till for reasons other than a sale: opening floats, change top-ups, safe drops and petty-cash payouts.\n  primary key: register_withdraw_id\n  register_withdraw_id — Unique id for this add/payout\n  amount — SIGNED drawer movement\n  create_time — When the add/payout was recorded, store-local wall time with no timezone offset\n  notes — Reason staff typed for the movement\n  employee_id — Employee who made the add/payout. joins ls_employees\n  payment_type_id — Tender that moved. joins ls_payment_types\n  register_id — Till the movement happened at. joins ls_registers\n  REFERENCES",
  "ls_registers": "source_lightspeed.ls_registers — one row per point-of-sale register (till) configured on the account.\n  A Register is a single point of sale -- a place where money is received -- and each register keeps a separate cash count per payment type.\n  primary key: register_id\n  register_id — Unique numeric id for the till\n  name — Human label for the till as shown in the POS, e.g. 'Front Register', 'Counter'\n  open — True when the till is open for trading AT THE MOMENT THE ROW WAS FETCHED\n  open_time — When the CURRENT session was opened, in the shop's timezone\n  tip_enabled — True when the Tipping feature is permitted on this register\n  open_employee_id — Foreign key to the Employee who opened the current session (/Account/{accountID}/Employee/{openEmployeeID})\n  shop_id — Foreign key to the Shop this register physically sits in (/Account/{accountID}/Shop/{shopID}). joins ls_shops\n  REFERENCES",
  "ls_report_discounts_by_day": "source_lightspeed.ls_report_discounts_by_day — one shop per day.\n  Lightspeed-computed daily discount totals by shop, built for accounting-package export.\n  primary key: date, shop_id\n  date — The aggregation day the discounts were given on\n  shop_id — The shop where the discounts were given. joins ls_shops\n  discount — Total value of sale discounts given on this day at this shop (the docs call it the subtotal of sale discounts)\n  REFERENCES",
  "ls_report_orders_by_tax_class": "source_lightspeed.ls_report_orders_by_tax_class — one tax-class cost subtotal within one received purchase order.\n  Lightspeed-computed accounting report of purchase orders RECEIVED from vendors, broken down per order and subtotaled by tax class, with vendor identification.\n  primary key: order_id, tax_class_id\n  date — The day the order was RECEIVED, not the day it was placed\n  shop_id — The shop the order belongs to. joins ls_shops\n  vendor_id — The vendor (supplier) this line is for. joins ls_vendors\n  vendor_name — Denormalised vendor name as of report generation\n  tax_class_id — The tax class the cost subtotal belongs to. joins ls_tax_classes\n  tax_class_name — Denormalised tax class name for this subtotal\n  cost — Subtotal COST (what you paid the vendor) for items of this tax class on this order - not retail value, not landed cost\n  order_id — The purchase order this row is part of. joins ls_purchase_orders\n  total_ship_cost — The ENTIRE order's shipping cost, repeated verbatim on every tax-class row of that order - the docs say explicitly not to sum it\n  total_other_cost — The ENTIRE order's other/ancillary charges, repeated on every tax-class row exactly like total_ship_cost, with the same explicit do-not-sum warning i…\n  REFERENCES",
  "ls_report_payments_by_day": "source_lightspeed.ls_report_payments_by_day — one payment type per shop per day, split by the layaway flag.\n  Lightspeed-computed daily takings totals by payment type, shop and layaway flag, built for accounting-package export.\n  primary key: date, shop_id, payment_type_id, layaway\n  date — The aggregation day these payments were taken on\n  shop_id — The shop where the money was taken. joins ls_shops\n  layaway — true when the row totals payments taken against a LAYAWAY (a deposit toward goods not yet handed over), false for ordinary sale payments\n  amount — Total money taken under this payment type on this day at this shop (the docs call it the subtotal for the payment type)\n  payment_type_name — Denormalised tender name as of report generation\n  payment_type_id — The tender this total is for. joins ls_payment_types\n  REFERENCES",
  "ls_report_tax_class_sales_by_day": "source_lightspeed.ls_report_tax_class_sales_by_day — one tax class per shop per day.\n  Lightspeed-computed daily sales subtotals broken down by tax class and shop, carrying BOTH a FIFO and an average cost basis for the same goods.\n  primary key: date, shop_id, tax_class_id\n  date — The aggregation day of these sale totals\n  shop_id — The shop these sales were rung at. joins ls_shops\n  tax_class_id — The tax class the totals belong to. joins ls_tax_classes\n  tax_class_name — Denormalised class name as of report generation ('Item', 'Labor', 'Gift Card')\n  subtotal — Sales subtotal for this class on this day at this shop, EX TAX\n  fifo_cost — Cost of goods sold in this group valued First In First Out - an EXTENDED total for the group, not a unit cost\n  avg_cost — Cost of the same goods valued at weighted-average cost - the ALTERNATIVE basis to fifo_cost for the identical sales, not an additional cost\n  REFERENCES",
  "ls_report_taxes_by_day": "source_lightspeed.ls_report_taxes_by_day — one tax category per shop per day.\n  Lightspeed-computed daily tax totals by tax category and shop, built for accounting-package export and marked read-only in the docs.\n  primary key: date, shop_id, tax_category_id\n  date — The aggregation day the taxes were collected on\n  shop_id — The shop where the tax was collected. joins ls_shops\n  tax_category_id — The tax category (rate/authority) the total belongs to. joins ls_tax_categories\n  tax_category_name — Denormalised category name as of report generation\n  tax — Total tax collected for this category on this day at this shop\n  REFERENCES",
  "ls_sale_accounts": "source_lightspeed.ls_sale_accounts — one row per SaleAccount — one gift-card (CreditAccount) association linking a single SalePayment to the SaleLine that created or funded it.\n  The bridge that makes gift cards and store credit interpretable: it ties the negative payment that funded a card to the sale line that sold it and to the CreditAccount that holds the balance.\n  primary key: sale_account_id\n  sale_account_id — Primary key of the link record\n  credit_account_id — The CreditAccount (gift card / store credit account) used in the SalePayment. joins ls_credit_accounts\n  sale_payment_id — The SalePayment linked to the sale line — specifically the NEGATIVE-amount payment that created or topped up the gift card. joins ls_sale_payments\n  sale_line_id — The SaleLine that sold the gift card. joins ls_sale_lines\n  REFERENCES",
  "ls_sale_line_inventory_allocations": "source_lightspeed.ls_sale_line_inventory_allocations — one row per InventorySale — one allocation of units from ONE inventory lot to ONE sale line.\n  The bridge from a sale line to the specific inventory lots it consumed or reserved.\n  primary key: inventory_sale_id\n  inventory_sale_id — Unique numeric identifier for the allocation\n  quantity — Units drawn from this lot\n  create_time — When the allocation or reservation was made, store-local\n  inventory_id — The Inventory lot the units were pulled from\n  sale_line_id — The sale line this allocation belongs to. joins ls_sale_lines\n  sale_id — The sale the allocation ultimately belongs to, carried down from the top-level Sale envelope. joins ls_sales\n  REFERENCES",
  "ls_sale_lines": "source_lightspeed.ls_sale_lines — one row per SaleLine — one charge on one sale.\n  The product-level truth for the domain: units, per-product revenue, per-line discounts and per-line cost basis.\n  primary key: sale_line_id\n  sale_line_id — Unique numeric id for the line\n  sale_id — The sale this line sits on. joins ls_sales\n  create_time — When the line was first added to the ticket, store-local\n  time_stamp — When the line was last modified\n  unit_quantity — Units on the line\n  unit_price — Per-unit price actually charged, after price rules\n  normal_unit_price — Per-unit price before any price rules were applied — the 'was' price\n  discount_amount — Dollar discount entered on the line\n  discount_percent — Percentage discount on the line, expressed as a FRACTION of 1 (0.2 = 20%), matching the Discount object's documented <= 1.00 cap\n  avg_cost — Weighted-average cost of the product on this line, ex tax\n  fifo_cost — FIFO cost for the line, ex tax — the basis Lightspeed's own profit reports use\n  tax — Whether the line is taxed at all\n  tax1_rate — First tax rate for THIS line as a fraction, after TaxClass and TaxCategory customisation\n  tax2_rate — Second tax rate for this line as a fraction, where the jurisdiction has one\n  is_layaway — Line sits on a layaway: goods are reserved (see ls_sale_line_inventory_allocations) and paid for over time, so the money is a balance rather than set…\n  is_workorder — Line originated from a workshop/service job — the marker that separates SERVICE revenue from goods revenue\n  is_special_order — Line is a special order (stock brought in for a named customer); setting it creates a SpecialOrder record\n  displayable_subtotal — Receipt-facing line subtotal, documented as (unitQuantity * unitPrice) - discount\n  displayable_unit_price — The unit price shown to the customer after price-rule PERCENTAGE discounts ONLY — fixed-amount price rules are deliberately excluded\n  calc_line_discount — Money taken off by the line's own discount, in currency\n  calc_transaction_discount — This line's allocated share of a whole-sale (transaction-level) discount\n  calc_total — Line revenue INCLUDING tax, after all discounts\n  calc_subtotal — Line revenue excluding tax\n  calc_tax1 — Tax charged on this line at the first rate, in currency\n  calc_tax2 — Tax charged on this line at the second rate, in currency; 0 in single-tax jurisdictions\n  tax_class_id — TaxClass of the line, which determines its specific rates. joins ls_tax_classes\n  customer_id — Customer on the LINE — populated ONLY for layaway, special-order and workorder lines. joins ls_customers\n  discount_id — The named Discount rule applied to this line specifically. joins ls_discounts\n  employee_id — Employee responsible for this line, which can differ from the sale's employee when staff split a ticket or a workshop tech adds parts. joins ls_employees\n  item_id — Catalog item the line charges for; maps to the `product`/`product_variant` canonical entities. joins ls_items\n  note_id — The single Note object attached to this line; notes print on the receipt. joins ls_customer_notes\n  parent_sale_line_id — For a REFUND line, the original sale line it reverses — the API uses it to stop cumulative refunds exceeding the original quantity\n  shop_id — Shop where the line was added. joins ls_shops\n  tax_category_id — TaxCategory applied to this line — the jurisdiction-level container that sits above TaxClass. joins ls_tax_categories\n  item_fee_id — The ItemFee this line represents, when the line is a fee rather than merchandise (e.g. a recycling or environmental levy attached by category). joins ls_item_fees\n  line_type — Descriptor of what the line represents\n  require_full_reservation — Request-payload-only flag that makes a write FAIL if there is not enough inventory to reserve the whole unitQuantity\n  completed — Parent-projected and not authoritative\n  voided — Parent-projected and not authoritative\n  complete_time — Parent-projected and not authoritative\n  REFERENCES",
  "ls_sale_payment_signatures": "source_lightspeed.ls_sale_payment_signatures — one row per SalePaymentSignature — one captured signature image belonging to one sale payment.\n  Evidence that a customer signed for a payment, stored as a pointer into Lightspeed's image storage service.\n  primary key: sale_payment_signature_id\n  sale_payment_signature_id — Primary key of the signature record\n  file_path — Path to the signature image inside Lightspeed's image storage service\n  create_time — When the signature was captured, store-local\n  sale_payment_id — The payment this signature was captured for — the ONLY link this table has to the rest of the domain. joins ls_sale_payments\n  REFERENCES",
  "ls_sale_payments": "source_lightspeed.ls_sale_payments — one row per SalePayment — one tender applied to, or refunded from, one sale.\n  How money actually moved: cash, card, gift card, store credit, cheque, on-account.\n  primary key: sale_payment_id\n  sale_payment_id — Unique numeric id for this tender line\n  amount — Amount tendered in store currency, INCLUDING any tip (see tip_amount)\n  create_time — When the payment was taken, store-local\n  archived — Archived payments are effectively voided and, per the docs, must NOT count toward totals\n  remote_reference — Optional client-generated unique identifier supplied by an integration when creating the payment — an idempotency key for reconciling against an exte…\n  tip_amount — Tip portion of this tender, negative for a refund\n  payment_id — Reference to the charge held by the payment SERVICE (the processor's own handle)\n  sale_id — The sale this payment settles. joins ls_sales\n  payment_type_id — Tender type of this payment or refund (Cash, Credit Card, Gift Card, Credit Account, ...). joins ls_payment_types\n  cc_charge_id — The CCCharge (gateway transaction) backing this payment, when the card ran through Lightspeed's integrated processing. joins ls_cc_charges\n  ref_payment_id — Points at the ORIGINAL salePaymentID this row reverses; set when refunding a previous credit card charge\n  register_id — Register the payment was received at. joins ls_registers\n  employee_id — Employee who received the payment; may differ from the employee who rang the sale. joins ls_employees\n  credit_account_id — The CreditAccount (store credit or gift card) this deposit/withdrawal applies to. joins ls_credit_accounts\n  completed — Parent-projected and potentially sparse\n  voided — Parent-projected and potentially sparse\n  complete_time — Parent-projected; unreliable\n  shop_id — Parent-projected shop; unreliable coverage. joins ls_shops\n  REFERENCES",
  "ls_sale_voids": "source_lightspeed.ls_sale_voids — one row per SaleVoid — one void event recorded against one sale, with the operator's stated reason.\n  The audit trail for voided transactions: who voided what, where, when and why.\n  primary key: sale_void_id\n  sale_void_id — Unique numeric id of the void record\n  create_time — When the void happened, store-local\n  reason — Free-text note the operator gave for the void\n  sale_id — The sale that was voided; joins ls_sales where voided = true. joins ls_sales\n  employee_id — Employee who PERFORMED the void — frequently NOT the employee who rang the original sale (that is ls_sales.employee_id). joins ls_employees\n  shop_id — Shop where the void was performed. joins ls_shops\n  REFERENCES",
  "ls_sales": "source_lightspeed.ls_sales — one row per Sale record — one register ticket/transaction, in any state (open, completed, voided, archived).\n  The transaction header for the whole domain: totals, tax, discounts, cost of goods, and every foreign key that gives a sale its who/where/when.\n  primary key: sale_id\n  sale_id — Immutable numeric ticket id, unique within the account\n  completed — True once the ticket was finalised: inventory has been deducted and payments sum to the total\n  voided — True when the sale was voided\n  archived — True when the sale is archived (hidden from the POS UI)\n  create_time — When the ticket was first opened at the register, store-local, read-only\n  complete_time — When the sale was completed — THE canonical revenue timestamp, store-local\n  updatetime — Last modification, read-only, store-local\n  time_stamp — Marked *legacy* in the reference. deprecated\n  reference_number — Order number assigned by the external system that created the sale (webstore, Amazon, marketplace)\n  reference_number_source — Name of the external system that owns reference_number\n  tax1_rate — Default first tax rate for the sale, expressed as a FRACTION (0.1 = 10%, not 10)\n  tax2_rate — Default second tax rate as a fraction, for jurisdictions with two components (e.g. GST + PST)\n  change — Cash handed back to the customer; cash sales only\n  tip_enabled — True when the tipping feature was active on this ticket\n  enable_promotions — True when automatic Promotions were run against every line added to this sale\n  calc_discount — Total money discounted on the sale, store currency, as a POSITIVE number representing value given away\n  calc_total — The grand total the customer pays: after discounts, INCLUDING tax\n  calc_subtotal — Sale total EXCLUDING tax, after discounts\n  calc_taxable — Subtotal of only the lines that were actually taxed (SaleLine.tax = true AND their TaxClass carries a rate)\n  calc_non_taxable — Subtotal of the non-taxable lines (tax-exempt customers, zero-rated goods, some labour classes)\n  calc_avg_cost — Cost of goods for the whole sale at weighted-average unit cost, ex tax, summed across lines\n  calc_fifo_cost — Cost of goods at FIFO, ex tax — the basis that matches Lightspeed's native profit reports\n  calc_tax1 — Tax collected at the first rate across all lines, in store currency\n  calc_tax2 — Tax collected at the second rate, in currency; 0 in single-tax jurisdictions\n  calc_payments — Sum of every SalePayment.amount on this sale, tips included\n  calc_tips — Sum of SalePayment.tipAmount across the sale\n  total — The documented arithmetic restatement: calcSubtotal - calcDiscount + calcTax1 + calcTax2\n  total_due — Total minus credit-account and gift-card deposits (deposits subtract, withdrawals add) minus credit-card refunds\n  displayable_total — total plus gift-card deposits\n  balance — total - calc_payments: money still owed on the ticket\n  customer_id — Customer attached to the ticket. joins ls_customers\n  discount_id — DEPRECATED per the reference. deprecated. joins ls_discounts\n  discount_percent — DEPRECATED per the reference. deprecated\n  employee_id — Employee who processed (rang up) the ticket — the attribution for 'sales by staff member'. joins ls_employees\n  tip_employee_id — Employee assigned the whole tip amount for this sale\n  quote_id — The Quote this sale was created from. joins ls_quotes\n  register_id — Register (till) the sale was processed on. joins ls_registers\n  ship_to_id — The ShipTo (shipment/delivery) record for this sale, present when goods were shipped rather than carried out. joins ls_ship_tos\n  shop_id — Shop (physical location) where the sale was processed — the `location` dimension for every revenue split. joins ls_shops\n  tax_category_id — TaxCategory governing which tax rates apply to this sale; it is what determines the tax1_rate/tax2_rate defaults. joins ls_tax_categories\n  REFERENCES",
  "ls_seasons": "source_lightspeed.ls_seasons — one season label.\n  Legacy organiser: season labels that older accounts used to group items.\n  primary key: season_id\n  season_id — Primary key of the season label. deprecated\n  name — The season's label text. deprecated\n  REFERENCES",
  "ls_serialized": "source_lightspeed.ls_serialized — one serial-number record — one physical serialized unit, whether it came from stock or was logged as a customer's own property.\n  The register of serialized units: bikes, frames, e-bikes and anything else tracked by serial number.\n  primary key: serialized_id\n  serialized_id — Primary key of the serial record\n  serial — The serial number stamped on the unit\n  description — Free-text identity used when the record is NOT connected to a catalogue item — typically a customer's own bike ('black planet x')\n  color_name — Colour of the unit as typed by staff\n  size_name — Size of the unit (frame size for bikes) as typed by staff\n  item_id — The catalogue item this serial is an instance of, when the unit was sold from stock. joins ls_items\n  sale_line_id — The sale line where this unit was sold, or 0/NULL if it never went through the POS. joins ls_sale_lines\n  customer_id — The customer who owns this unit. joins ls_customers\n  time_stamp — When the record last changed\n  REFERENCES",
  "ls_session": "source_lightspeed.ls_session — one row -- the identity behind the access token currently in use (singleton).\n  Describes the current API session derived from the access token: which employee granted it, which account and API client it belongs to, and a couple of account-wide facts (shop count, linked eCom URL).\n  primary key: system_api_key_id\n  session_id — Legacy cookie-session identifier. deprecated\n  session_cookie — Legacy cookie-session value. deprecated\n  employee_id — Foreign key to the Employee who granted the access token (/Account/{accountID}/Employee/{employeeID}). joins ls_employees\n  system_customer_id — The account ID (/Account/{accountID})\n  system_user_id — The employee's identifier at the Lightspeed platform level, unique ACROSS ALL ACCOUNTS -- unlike employeeID, which is only unique within one account\n  system_api_client_id — Unique identifier of the API client (the registered application) associated with the access token\n  system_api_key_id — Unique identifier of the access token itself\n  ecom_url — URL of the associated Lightspeed eCom (C-Series) store, if the account has one linked\n  shop_count — Number of shops on the account, as counted by the platform\n  REFERENCES",
  "ls_ship_tos": "source_lightspeed.ls_ship_tos — one row per ShipTo record (one shipment destination created for a sale that needs sending).\n  The store's shipping queue and history: a record is created when a sale has to be shipped to the customer, carrying the recipient name, a free-text note, the shipped flag and the destination address via the Contact rela….\n  primary key: ship_to_id\n  ship_to_id — Unique numeric id of the shipment record\n  shipped — True once the parcel has gone out, false while it still needs to ship\n  ship_note — Free-text delivery instructions for the parcel (leave at door, call on arrival, gift message)\n  first_name — Recipient's first name for this shipment\n  last_name — Recipient's last name for this shipment\n  customer_id — Foreign key to the customer this shipment is for. joins ls_customers\n  sale_id — Foreign key to the sale being shipped. joins ls_sales\n  time_stamp — Last modification of the shipment record\n  contact — The destination address, i.e. where the parcel is going, taken from the Contact relation\n  contact_id — Id of the destination contact block; join to ls_contacts.contact_id where owner_object = 'ShipTo' for a normalised address. joins ls_contacts\n  REFERENCES",
  "ls_shops": "source_lightspeed.ls_shops — one row per shop (physical store location) on the account, including archived ones.\n  The physical store locations on the account.\n  primary key: shop_id\n  shop_id — Unique numeric id for the store location\n  name — Store name as it appears on receipts, labels and in the POS shop picker\n  service_rate — Default hourly labour/service rate for this location, in the account's base currency (Account.defaultCurrency.code)\n  time_zone — The store's IANA timezone\n  tax_labor — True when service/labour lines at this shop attract sales tax\n  label_title — What heading is printed at the top of product labels for this shop\n  label_msrp — True when a product label should also print the MSRP, but only for items where MSRP is filled in AND MSRP exceeds this shop's own selling price\n  archived — True when the location has been archived (closed down / retired)\n  contact_id — Foreign key to the Contact record holding the store's street address, phone, email and website. joins ls_contacts\n  tax_category_id — Foreign key to the TaxCategory this shop applies to new sales by default (/Account/{accountID}/TaxCategory/{taxCategoryID}). joins ls_tax_categories\n  receipt_setup_id — Foreign key to the ReceiptSetup record (header/footer text and logo) used by this shop. joins ls_receipt_setups\n  cc_gateway_id — Foreign key to the LEGACY credit-card gateway configuration for this shop (ls_cc_gateways). deprecated. joins ls_cc_gateways\n  price_level_id — Foreign key to the default PriceLevel this shop sells at (/Account/{accountID}/PriceLevel/{priceLevelID}). joins ls_price_levels\n  contact — The shop's full Contact record as returned by load_relations=Contact: Addresses.ContactAddress (address1, address2, city, state, zip, country), Phone…\n  REFERENCES",
  "ls_special_orders": "source_lightspeed.ls_special_orders — one special order — one item a named customer asked the shop to bring in, tracked from the sale line it was raised on to the purchase order line or transfer that fulfils it.\n  Customer special orders: a customer wants something the shop does not stock, the shop optionally takes a deposit and orders it in.\n  primary key: special_order_id\n  special_order_id — Unique id of the special order\n  unit_quantity — How many units the customer asked the shop to bring in\n  contacted — true once someone has told the customer their special order has arrived\n  completed — true when the special order has been closed out (collected and rung up on the originating sale line)\n  customer_id — The customer waiting for the item. joins ls_customers\n  shop_id — Shop where the special order was raised and where the customer will collect. joins ls_shops\n  sale_line_id — The sale line the special order was started from and where it will be completed — the customer's side of the deal, carrying the price, deposit and sa…. joins ls_sale_lines\n  order_line_id — The purchase order line where the item is being bought from the supplier — the supply side. joins ls_purchase_order_lines\n  transfer_item_id — The transfer line fulfilling this special order when another shop supplies it rather than a supplier. joins ls_transfer_items\n  REFERENCES",
  "ls_tag_groups": "source_lightspeed.ls_tag_groups — one tag group name for the account.\n  Helper list of the tag groups configured on the account.\n  primary key: name\n  name — The tag group's name\n  REFERENCES",
  "ls_tags": "source_lightspeed.ls_tags — one tag in the account's tag vocabulary.\n  The list of tags staff can attach to items and matrices for ad-hoc grouping.\n  primary key: tag_id\n  tag_id — Primary key of the tag\n  name — The tag text itself\n  REFERENCES",
  "ls_tax_categories": "source_lightspeed.ls_tax_categories — one sales-tax configuration (TaxCategory, labelled \"Sales Tax\" in the Lightspeed UI) on the account.\n  The account's sales-tax definitions: up to two named component rates plus the tax-inclusive pricing convention.\n  primary key: tax_category_id\n  tax_category_id — Unique id of the sales-tax configuration; the join target for Sale.taxCategoryID, Shop.taxCategoryID and ls_report_taxes_by_day.tax_category_id\n  is_tax_inclusive — true when prices under this category are entered and displayed WITH tax already inside them (AU/NZ/UK convention), false when tax is added on top at…\n  tax1_name — Label of the first component rate as printed on receipts and reports (e.g. 'GST', 'Sales Tax', 'State')\n  tax2_name — Label of the second component rate (e.g. 'PST', 'County')\n  tax1_rate — First component rate as a FRACTION OF 1, not a percentage: 0.1 means 10%\n  tax2_rate — Second component rate, also a fraction of 1; 0 on single-tax accounts\n  time_stamp — When the category record was last modified, in store-local time\n  REFERENCES",
  "ls_tax_category_classes": "source_lightspeed.ls_tax_category_classes — one per-tax-class rate override inside one tax category.\n  Rate overrides: the rate a specific tax class attracts under a specific tax category, replacing that category's default tax1_rate/tax2_rate.\n  primary key: tax_category_id, tax_class_id\n  tax_category_id — The owning tax category. joins ls_tax_categories\n  tax_category_class_id — Surrogate id of the override row itself\n  tax_class_id — The tax class this override applies to. joins ls_tax_classes\n  tax1_rate — First-component rate for this class under this category, as a FRACTION OF 1 (0.1 = 10%)\n  tax2_rate — Second-component override, also a fraction of 1\n  REFERENCES",
  "ls_tax_classes": "source_lightspeed.ls_tax_classes — one tax class label that items and sale lines can carry.\n  Labels that group items for tax treatment (Item, Labor, Gift Card, ...).\n  primary key: tax_class_id\n  tax_class_id — Unique id of the tax class\n  name — Human label of the class, e.g. 'Item', 'Labor', 'Gift Card'\n  time_stamp — When the class record was last modified, in store-local time\n  REFERENCES",
  "ls_transfer_from": "source_lightspeed.ls_transfer_from — one origin record for one stock transfer.\n  The sending side of a stock transfer.\n  primary key: transfer_from_id\n  transfer_from_id — Primary key of the origin record\n  REFERENCES",
  "ls_transfer_items": "source_lightspeed.ls_transfer_items — one line on one transfer — one item on one inter-shop transfer document.\n  The lines of an inter-shop transfer: which item, how many were meant to go, how many actually left, how many the destination counted, how many landed, and the cost value on each side.\n  primary key: transfer_item_id\n  transfer_item_id — Unique id of this transfer line\n  transfer_id — The transfer document this line belongs to. joins ls_transfers\n  item_id — The item being transferred. joins ls_items\n  to_send — The quantity the origin shop INTENDS to send — the picking instruction\n  to_receive — The quantity the receiving shop has counted as received during check-in\n  sent — The actual number dispatched from the origin shop\n  received — The actual number that landed at the destination\n  sent_value — TOTAL inventory cost value of the quantity sent, ex tax, in store currency — not a unit cost\n  received_value — TOTAL inventory cost value of the quantity received, ex tax\n  comment — Free-text note on the line — usually where staff explain a short shipment or damage\n  time_stamp — Last modification to this line, store-local\n  REFERENCES",
  "ls_transfer_to": "source_lightspeed.ls_transfer_to — one destination record for one stock transfer.\n  The receiving side of a stock transfer, mirroring ls_transfer_from.\n  primary key: transfer_to_id\n  transfer_to_id — Primary key of the destination record\n  REFERENCES",
  "ls_transfers": "source_lightspeed.ls_transfers — one inter-shop transfer document (header), with its origin-side and destination-side records flattened in.\n  Transfers of stock between shops: one row per transfer document, carrying whether it has been sent and received, which shops and staff were on each end, and the send/receive dates.\n  primary key: transfer_id\n  transfer_id — Unique id of the transfer document\n  sent — true once the origin store has dispatched the transfer\n  received — true once the receiving store has checked the transfer in\n  note — Free-text note for the store\n  archived — true when the transfer is filed away as done\n  transfer_from_id — Key of the origin-side sub-record whose three payload fields are flattened onto this row as sent_on, sent_by_employee_id and from_shop_id. joins ls_transfer_from\n  transfer_to_id — Key of the destination-side sub-record, flattened onto this row as need_by, received_by_employee_id and to_shop_id. joins ls_transfer_to\n  order_id — Purchase Order this transfer was attached to for centralized ordering (head office buys once, then transfers stock out to shops). joins ls_purchase_orders\n  sent_on — Date/time the transfer left the origin shop\n  employee_id — Employee who sent the transfer from the origin shop. joins ls_employees\n  shop_id — Origin shop — where the stock leaves. joins ls_shops\n  need_by — OVERLOADED, exactly as documented: while pending it is the date the transfer must be received BY; once received it is the date it WAS received\n  time_stamp — Last modification to the transfer record, store-local\n  REFERENCES",
  "ls_vendor_returns": "source_lightspeed.ls_vendor_returns — one vendor return document raised at one shop for one vendor.\n  One row per return of stock BACK TO a supplier — warranty batches, faulty goods, agreed stock swaps — with the cost value the shop expects to be credited.\n  primary key: vendor_return_id\n  vendor_return_id — Unique id of the vendor return document\n  vendor_id — Supplier the stock is being sent back TO; joins ls_vendors.vendor_id. joins ls_vendors\n  shop_id — The shop the stock is LEAVING — the location that loses the inventory, not the vendor's address. joins ls_shops\n  ref_num — Free-text external reference, in practice the supplier's RMA or credit-note number\n  status — Lifecycle state of the return\n  sent_date — When the return was dispatched to the vendor\n  ship_cost — Shipping cost incurred on the return, in the shop's currency\n  other_cost — Other costs on the return (restocking fees, handling)\n  hide_vendor_details — True when the vendor's details are suppressed on the printed return document\n  archived — True when the return has been archived\n  subtotal — Cost value of the goods being returned, before ship_cost/other_cost adjustments\n  total — Total cost value of the return INCLUDING adjustments — the credit the shop expects from the supplier\n  name — Denormalised supplier name from the embedded Vendor relation for readable grouping\n  time_stamp — Last modification of the record and the incremental-sync high-water mark\n  REFERENCES",
  "ls_vendors": "source_lightspeed.ls_vendors — one supplier the account buys from.\n  One row per supplier: the party that fulfils purchase orders and receives vendor returns, with the trading terms the shop holds with them (account number, price level, purchasing currency) and the catalogue-sync behavio….\n  primary key: vendor_id\n  vendor_id — Unique supplier id; the target of ls_purchase_orders.vendor_id and ls_vendor_returns.vendor_id\n  name — Supplier name exactly as the shop typed it — a brand or a distributor\n  archived — True when the supplier is retired from the picker\n  account_number — The shop's own account number WITH this supplier (our customer number at their end), not an internal id\n  price_level — Name of the pricing tier the business trades on with this supplier — usually '1','2','3' running from HIGHEST price to lowest, so a numerically large…\n  update_price — Behaviour switch: when true, adding a catalogue item to a purchase order refreshes the item's RETAIL price from the catalogue MSRP\n  update_cost — Behaviour switch: when true, adding a catalogue item to a purchase order refreshes the item's COST from the catalogue entry\n  update_description — Behaviour switch: when true, adding a catalogue item to a purchase order overwrites the item's description from the catalogue entry — which is how ca…\n  share_sell_through — True when the shop has agreed that this vendor may receive sell-through data\n  b2b_seller_uid — The vendor's unique identifier in NuORDER (Lightspeed's B2B platform)\n  contact — Raw JSON of the supplier's contact record — addresses, phone numbers, emails, websites\n  code — Currency the shop buys from this supplier in (e.g. 'USD')\n  symbol — Display symbol for the purchasing currency (e.g. '$')\n  rate — The vendor's CURRENT default exchange rate, used to seed new purchase orders\n  time_stamp — Last modification of the vendor record and the incremental-sync high-water mark\n  REFERENCES",
  "ls_workorder_images": "source_lightspeed.ls_workorder_images — one row per image attached to one workorder.\n  Reference photos attached to a job — damage on intake, before/after shots, a picture of the serial plate.\n  primary key: workorder_image_id\n  workorder_image_id — Unique numeric id of the image attachment\n  workorder_id — FK to the job the image is attached to. joins ls_workorders\n  description — Staff-entered caption for the image (e.g. 'scratch on down tube at intake')\n  filename — Stored filename of the image\n  ordering — Display position of this image within the job's image list — a rank, not a count and not a quantity\n  public_id — Public identifier of the stored asset, combined with base_image_url to build a retrievable URL\n  base_image_url — Base/CDN URL the image is served from\n  size — Documented only as 'the size of the image' with no unit — conventionally bytes for a stored asset, but the docs do not state it and it could be a pix…\n  create_time — When the image was uploaded\n  time_stamp — When the attachment record was last modified (caption edits, reordering)\n  REFERENCES",
  "ls_workorder_items": "source_lightspeed.ls_workorder_items — one row per part/product charge on one workorder.\n  The physical goods consumed on a job: tubes, chains, cables, cassettes.\n  primary key: workorder_item_id\n  workorder_item_id — Unique numeric id of the part line\n  workorder_id — FK to the parent job. joins ls_workorders\n  approved — True when the customer has approved this part charge\n  unit_price — Per-unit RETAIL price the part is quoted at on the job sheet — a per-unit figure, not a line total, and not necessarily the catalog price (staff can…\n  unit_quantity — Quantity of the part being used/sold on the job\n  warranty — True when this part is supplied under warranty and the customer is NOT charged for it\n  tax — True when this part line is taxed\n  is_special_order — True when the part is not in stock and is being special-ordered for this job; Lightspeed then creates a special order reached through the linked sale…\n  note — Free-text note on the part line\n  employee_id — FK to the employee responsible for this part line — usually whoever added the part rather than who fitted it. joins ls_employees\n  sale_line_id — FK to the SaleLine this part becomes on the register at checkout. joins ls_sale_lines\n  sale_id — FK to the Sale where the part was billed. joins ls_sales\n  item_id — FK to the catalog Item this charge is for — the actual product. joins ls_items\n  discount_id — FK to a Discount applied to this part charge. joins ls_discounts\n  time_stamp — When this part line was last modified\n  REFERENCES",
  "ls_workorder_lines": "source_lightspeed.ls_workorder_lines — one row per labour task or misc (non-part) charge on one workorder.\n  The work itself: each task performed or to be performed on a job, with its price, time estimate, assigned employee and done flag.\n  primary key: workorder_line_id\n  workorder_line_id — Unique numeric id of the task/charge, account-scoped (not per-workorder), so it is safe as a standalone primary key\n  workorder_id — FK to the parent job. joins ls_workorders\n  note — Free text for the task\n  hours — Whole-hours component of the task's duration\n  minutes — Minutes component of the task duration, complementing hours (a 90-minute task is hours=1, minutes=30)\n  unit_price_override — Per-unit retail price for this charge\n  unit_quantity — Units of this charge, documented as integer and usually 1 for tasks\n  unit_cost — Per-unit cost to the business for this task (internal labour cost basis)\n  done — True when this individual task is complete\n  approved — True when the customer approved this charge\n  warranty — True when this task is covered by warranty and the customer will NOT be charged for it\n  tax — True when this charge is taxed\n  employee_id — FK to the employee responsible for this task — the correct grain for per-mechanic workload and throughput. joins ls_employees\n  sale_line_id — FK to the SaleLine that represents this task on the register once checked out. joins ls_sale_lines\n  sale_id — FK to the Sale where this task was billed and paid. joins ls_sales\n  item_id — FK to the Non-Inventory / TaxClass=Labor Item used to create this task — i.e. the store's service-menu entry ('Full Service', 'Puncture Repair'). joins ls_items\n  discount_id — FK to a Discount applied to this charge. joins ls_discounts\n  tax_class_id — FK to the TaxClass governing this line — for genuine labour this is the store's 'Labor' class, which is also the routing signal that put the charge o…. joins ls_tax_classes\n  time_stamp — When this task/charge was last modified\n  REFERENCES",
  "ls_workorder_statuses": "source_lightspeed.ls_workorder_statuses — one row per workorder status configured on the account (system-defined and store-created).\n  The lookup for the workshop pipeline: every status a job can be in, including system states and merchant-defined boards.\n  primary key: workorder_status_id\n  workorder_status_id — Unique numeric id of the status\n  name — Display name shown in the POS\n  sort_order — Position in POS dropdowns and boards — a display ordering, not a pipeline stage number, and not monotonic with progress\n  html_color — Hex colour the POS paints this status with (e.g. #FF0000)\n  system_value — Stable internal identifier for statuses Lightspeed defines and locks (the store cannot rename or delete them)\n  REFERENCES",
  "ls_workorders": "source_lightspeed.ls_workorders — one row per workorder — one service/repair ticket for one customer item (a Serialized entry) at one shop.\n  The header of a workshop job: who it is for, which item is being worked on, where it is in the shop's status pipeline, when it came in and when it was promised.\n  primary key: workorder_id\n  workorder_id — Unique numeric id of the job, account-scoped\n  time_in — When the item was received/booked in\n  eta_out — The promise date: when the job is expected to be finished\n  note — Customer-facing notes for the whole job: what was asked for, what was quoted, what the customer reported\n  internal_note — Staff-only notes never shown to the customer\n  warranty — True when the WHOLE job is warranty work and the customer will not be charged\n  tax — Documented as 'does this workorder have tax charged on it'\n  archived — True when the job is archived: hidden in the POS and explicitly excluded from every total Lightspeed reports\n  hook_in — Free-text storage location (hook/rack/bay number) where the item waits for work to START\n  hook_out — Free-text storage location where the finished item waits for customer PICKUP\n  save_parts — True when the customer asked to keep the parts removed from the item, to be handed back with the job\n  assign_employee_to_all — Admin behaviour flag: when true the job's employee_id is auto-stamped onto every line\n  customer_id — FK to the customer the job is for. joins ls_customers\n  discount_id — FK to a job-level Discount applied to the whole workorder. joins ls_discounts\n  employee_id — FK to the employee IN CHARGE of the job (service writer / owner), not necessarily the person who performed the tasks. joins ls_employees\n  serialized_id — FK to the Serialized entry for the customer's item being worked on (the bike/machine, tracked by serial). joins ls_serialized\n  shop_id — FK to the Shop (physical location) where the work is to be performed. joins ls_shops\n  sale_id — FK to the Sale this job was checked out and paid on. joins ls_sales\n  sale_line_id — FK to the single SaleLine that represents this job on the register once billed. joins ls_sale_lines\n  workorder_status_id — FK to the store's current status for this job. joins ls_workorder_statuses\n  customer — Denormalised convenience: the customer's display name (first + last, falling back to company) taken from the embedded Customer relation\n  name — Denormalised current status display name\n  system_value — Denormalised stable status identifier for system-defined statuses\n  description — Denormalised description of the customer's item being worked on (e.g. the bike make/model) from the Serialized relation\n  serial — Denormalised serial/frame number of the customer's item\n  time_stamp — Last modification of the record, store-local\n  REFERENCES"
});

/** Xero raw staging catalogue (financial truth). Inject only for finance questions. */
export const XERO_SCHEMA_DOC = "source_xero.xero_1099_contacts — one 1099 summary row per contact per report tax year\n  Per-contact 1099 box amounts for a US tax year, exploded from the report's Contacts array: what the org paid each reportable vendor, bucketed into IRS form boxe.\n  columns: report_year, contact_id, box1, box7\nsource_xero.xero_1099_reports — one 1099 report header per requested tax year\n  Header of the US 1099 report (GET /Reports/TenNinetyNine), fetched once per reportYear the scan iterates.\n  columns: report_year\nsource_xero.xero_accounts — one chart-of-accounts entry per AccountID\n  The org's chart of accounts — the dimension every financial number in the connector eventually joins to.\n  columns: account_id, type, status, class, system_account\nsource_xero.xero_asset_settings — one fixed-asset settings record per organisation (unkeyed API singleton)\n  Per-organisation fixed-asset configuration: register numbering, the date asset depreciation started in Xero, the date depreciation was last run, and the default.\n  columns: singleton_id, last_depreciation_date\nsource_xero.xero_asset_types — one asset type (depreciation class) per assetTypeId\n  Depreciation classes that categorise fixed assets and — critically — carry the three GL account mappings that turn depreciation into ledger truth: the fixed-ass.\n  columns: asset_type_id\nsource_xero.xero_assets — one fixed-asset register entry per assetId (Draft, Registered or Disposed)\n  The fixed-asset register: every capitalised asset Xero tracks, with its acquisition cost, its own depreciation policy (flattened from assets:BookDepreciationSet.\n  columns: asset_id, purchase_price, disposal_price, asset_status, book_depreciation_setting_depreciation_rate, book_depreciation_detail_cost_limit, book_depreciation_detail_residual_value, book_depreciation_detail_prior_accum_depreciation_amount, book_depreciation_detail_current_accum_depreciation_amount, book_depreciation_detail_current_capital_gain, book_depreciation_detail_current_gain_loss, accounting_book_value\nsource_xero.xero_attachments — one attachment on one parent record, keyed by parent endpoint + parent id + attachment id\n  Single cross-parent catalog of file attachments across every attachment-capable accounting endpoint (Invoices, CreditNotes, BankTransactions, BankTransfers, Con.\n  columns: parent_endpoint, parent_id, attachment_id\nsource_xero.xero_bank_transaction_line_item_tracking — one tracking category/option assignment on one bank transaction line item\n  Tracking category and option assignments stamped on bank transaction lines — Xero's department/region/cost-centre dimensions applied to directly-coded cash.\n  columns: bank_transaction_id, line_index, tracking_index, tracking_category_id\nsource_xero.xero_bank_transaction_line_items — one GL coding line per bank transaction, keyed by its zero-based position in the LineItems array\n  GL coding detail of each bank transaction: how one cash movement was split across accounts, tax rates, items and (via the tracking child table) departments and .\n  columns: bank_transaction_id, line_index, account_code, account_id, tax_amount, line_amount\nsource_xero.xero_bank_transactions — one money-in or money-out movement on one Xero bank account per BankTransactionID\n  The spend-and-receive money ledger of every Xero bank account: cash coded straight to GL accounts rather than applied to an invoice or bill.\n  columns: bank_transaction_id, type, bank_account_account_id, is_reconciled, date, currency_code, currency_rate, status, line_amount_types, sub_total, total_tax, total, prepayment_id, overpayment_id\nsource_xero.xero_bank_transfers — one instruction moving funds between two bank accounts of the same organisation per BankTransferID\n  Movements of funds between two of the organisation's own bank accounts.\n  columns: bank_transfer_id, from_bank_account_account_id, to_bank_account_account_id, amount, date, currency_rate, from_bank_transaction_id, to_bank_transaction_id, status\nsource_xero.xero_batch_payments — one batch payment header per BatchPaymentID, grouping member payments into a single bank movement\n  Header for a group of bill payments (PAYBATCH) or invoice collections (RECBATCH) that hit the bank as one consolidated transaction.\n  columns: batch_payment_id, type, status, date, total_amount\nsource_xero.xero_branding_themes — one branding theme per BrandingThemeID\n  The org's document templates (logo, layout) referenced by invoices, credit notes, quotes and repeating templates via branding_theme_id.\n  columns: branding_theme_id\nsource_xero.xero_budget_balances — one budgeted period amount per (budget, account, period)\n  The numbers of the planning layer: one row per month bucket ('2019-08') per budgeted account per budget.\n  columns: budget_id, account_id, period, amount\nsource_xero.xero_budget_lines — one budgeted account per (budget, account)\n  The membership bridge between a budget and the chart of accounts: one row per account the budget plans, with the period amounts hanging off xero_budget_balances.\n  columns: budget_id, account_id\nsource_xero.xero_budget_tracking — one tracking category/option pair scoping a budget per (budget, tracking category)\n  The scope declaration of a TRACKING budget: which tracking option (e.g.\n  columns: budget_id, tracking_category_id, tracking_option_id\nsource_xero.xero_budgets — one budget definition per BudgetID\n  The org's planning layer: the OVERALL budget covers the whole org, while TRACKING budgets re-plan the same org sliced to specific tracking option pairs (see xer.\n  columns: budget_id, type\nsource_xero.xero_connections — one authorized app-to-tenant connection per connection id\n  The authorization roster from the identity API: one row per Xero tenant the user has currently consented to share with Albert.\n  columns: id, connection_tenant_id, tenant_type\nsource_xero.xero_contact_addresses — one address per contact per address type (POBOX or STREET)\n  Typed address slots exploded from the contact record.\n  columns: contact_id, address_type, country\nsource_xero.xero_contact_balances — one current AR/AP balance snapshot per contact, as of the latest sync\n  Xero's own answer to 'what does this contact owe us, and what do we owe them, right now': outstanding and overdue amounts for accounts receivable (their unpaid .\n  columns: contact_id, accounts_receivable_outstanding, accounts_receivable_overdue, accounts_payable_outstanding, accounts_payable_overdue\nsource_xero.xero_contact_cis_settings — one CIS deduction profile per contact (UK Construction Industry Scheme orgs only)\n  Per-contact UK Construction Industry Scheme configuration, fetched by fan-out per contact: whether the contact is a CIS subcontractor and the deduction rate Xer.\n  columns: contact_id, cis_enabled, rate\nsource_xero.xero_contact_group_members — one membership edge per (contact group, contact) pair\n  The many-to-many bridge between contacts and their groups, exploded from the per-group fan-out fetch — the list endpoint never includes members.\n  columns: contact_group_id, contact_id\nsource_xero.xero_contact_groups — one contact group per ContactGroupID\n  User-curated contact segments ('VIP', 'Wholesale', 'North region') — the cheapest segmentation dimension Xero offers, maintained by hand in the org.\n  columns: contact_group_id\nsource_xero.xero_contact_persons — one additional contact person per contact per array position\n  The ADDITIONAL people attached to a contact — the primary person lives on xero_contacts (first_name/last_name/email_address), so a complete people-extract is th.\n  columns: contact_id, person_ordinal\nsource_xero.xero_contact_phones — one phone entry per contact per phone type\n  Typed phone slots exploded from the contact record: DEFAULT (what the Xero UI displays), DDI (direct dial), MOBILE, FAX and OFFICE.\n  columns: contact_id, phone_type\nsource_xero.xero_contacts — one Xero contact record per ContactID, including ACTIVE, ARCHIVED, GDPRREQUEST and merged-away records\n  The master directory behind every money table: customers, suppliers and everyone in between share this single namespace, distinguished only by the derived is_cu.\n  columns: contact_id, merged_to_contact_id, contact_status, is_supplier, is_customer, default_currency, updated_date_utc\nsource_xero.xero_credit_note_allocations — one allocation of one credit note against one invoice, per credit note and array position\n  Application evidence exploded from CreditNote.Allocations: each row spreads part of a credit note's value onto one invoice, reducing that invoice's amount_due w.\n  columns: credit_note_id, allocations, allocations_invoice_invoice_id, allocations_amount, allocations_date\nsource_xero.xero_credit_note_line_items — one line item on one credit note per LineItemID\n  The contra side of xero_invoice_line_items: what was credited back, per product and GL account.\n  columns: line_items_line_item_id, credit_note_id, line_items_line_amount, line_items_account_code, line_items_account_id, line_items_tracking\nsource_xero.xero_credit_notes — one credit note document (customer credit ACCRECCREDIT or supplier credit ACCPAYCREDIT) per CreditNoteID\n  Negative-document header mirroring xero_invoices: ACCRECCREDIT reduces what a customer owes (contra revenue), ACCPAYCREDIT reduces what the org owes a supplier .\n  columns: credit_note_id, type, status, date, line_amount_types, currency_code, currency_rate, sub_total, total, remaining_credit\nsource_xero.xero_currencies — one currency per ISO code enabled in the org's subscription\n  Tiny reference list of the currencies the org has ever enabled — the decode table for every CurrencyCode column in the connector.\n  columns: code\nsource_xero.xero_expense_claim_payments — one reimbursement payment applied to one expense claim\n  Reimbursement cash events, exploded from the Payments array embedded in each expense claim.\n  columns: payment_id, expense_claim_id, date, amount, status\nsource_xero.xero_expense_claim_receipts — one attachment of one receipt to one expense claim\n  The authoritative claim-to-receipt mapping, exploded from the Receipts array embedded in each expense claim.\n  columns: expense_claim_id, receipt_id\nsource_xero.xero_expense_claims — one expense claim submitted by one org user for reimbursement\n  The reimbursement wrapper of Xero's classic expense-claims workflow: who is owed money, how much is outstanding, and which accounting period it reports under.\n  columns: expense_claim_id, status, user_user_id, total, amount_due, amount_paid, reporting_date\nsource_xero.xero_file_associations — one row per attachment of one file to one Xero business record — a file attached to N records yields N rows\n  The bridge that turns the file library into audit evidence: each row attaches one file to one business record, addressed by the polymorphic (object_group, objec.\n  columns: file_id, object_id, object_group, object_type, send_with_object, association_date_utc\nsource_xero.xero_files — one row per file stored in the tenant's Xero Files library, Inbox included\n  The tenant's document library: every file uploaded to or emailed into Xero Files, with content metadata and the uploader's identity flattened from the nested fi.\n  columns: id, created_date_utc\nsource_xero.xero_folders — one row per folder in the tenant's Xero Files library, including the system Inbox\n  The flat (non-nested) folder structure of the Files library, dominated by one special row: the Inbox, where emailed-in and unfiled documents accumulate until so.\n  columns: id, file_count, is_inbox\nsource_xero.xero_history_records — one audit/history event per parent record per array position at sync time\n  Single cross-parent audit trail: who did what, when, to which document (created, approved, voided, edited, emailed, notes), fetched by per-record fan-out from G.\n  columns: parent_endpoint, parent_id, ordinal\nsource_xero.xero_invoice_line_items — one line item on one invoice or bill per LineItemID\n  The revenue and spend fact at its true grain: what was billed, for which product/service, posted to which GL account, carrying which tracking dimensions.\n  columns: line_items_line_item_id, invoice_id, line_items_unit_amount, line_items_line_amount, line_items_tax_amount, line_items_account_code, line_items_account_id, line_items_tracking\nsource_xero.xero_invoice_reminders — one invoice-reminder settings record per organisation\n  Org-level toggle from GET /InvoiceReminders/Settings: whether Xero's automatic invoice reminder emails are switched on.\n  columns: settings_key\nsource_xero.xero_invoices — one invoice document (sales invoice ACCREC or bill ACCPAY) per InvoiceID\n  Document-header fact for BOTH sides of the ledger: one Xero Invoice object is a sales invoice (Type=ACCREC, money owed to the org) or a supplier bill (Type=ACCP.\n  columns: invoice_id, type, status, date, line_amount_types, currency_code, currency_rate, sub_total, total, amount_due\nsource_xero.xero_items — one product or service item in the org's catalog, identified by ItemID\n  The product/service dimension and the only inventory-balance surface in the accounting API.\n  columns: item_id, code, is_tracked_as_inventory, sales_details_unit_price, quantity_on_hand, total_cost_pool\nsource_xero.xero_journal_line_tracking — one tracking category/option pair applied to one journal line (at most two pairs per line)\n  How the org's analysis dimensions (Department, Region…) attach to the statutory ledger: each row pins one journal line to one option of one tracking category.\n  columns: journal_lines_journal_line_id, tracking_category_id, tracking_option_id, name, option\nsource_xero.xero_journal_lines — one signed debit or credit ledger line per JournalLineID (a globally unique uuid)\n  The atoms of the statutory ledger: balanced debit/credit lines, ALWAYS in the org's base currency regardless of the source document's currency — the one place i.\n  columns: journal_line_id, journal_id, account_id, account_type, net_amount, gross_amount, tax_amount\nsource_xero.xero_journals — one immutable statutory journal header per posted transaction event (JournalID)\n  The statutory general ledger feed: every posted transaction in Xero — invoices, payments, bank lines, payroll, manual journals — becomes exactly one immutable j.\n  columns: journal_id, journal_date, source_id, source_type\nsource_xero.xero_linked_transactions — one billable-expense link from one source purchase line to (at most) one target sales invoice line\n  The rebilling wiring: each row connects a purchase-side line — an ACCPAY bill line or a SPEND bank-transaction line — to the customer it is recoverable from and.\n  columns: linked_transaction_id, status, source_transaction_id, source_line_item_id, source_transaction_type_code, target_transaction_id, target_line_item_id, contact_id\nsource_xero.xero_manual_journal_line_tracking — one tracking category/option pair per (manual journal, line position, tracking category)\n  Tracking pairs attached to manual journal document lines — at most two per line, mirroring the ledger convention.\n  columns: manual_journal_id, line_ordinal, tracking_category_id, tracking_option_id\nsource_xero.xero_manual_journal_lines — one entry line per (manual journal, zero-based array position)\n  The debit/credit lines of manual journal documents.\n  columns: manual_journal_id, journal_lines, line_amount, account_id, tax_amount\nsource_xero.xero_manual_journals — one manual journal document per ManualJournalID\n  Hand-keyed ledger adjustments — accruals, corrections, opening balances — as editable documents with a status lifecycle.\n  columns: manual_journal_id, date, status, line_amount_types\nsource_xero.xero_online_invoices — one online-invoice sharing URL per invoice\n  Per-invoice fan-out from GET /Invoices/{InvoiceID}/OnlineInvoice: the public 'view your invoice online' link Xero hosts for sales invoices.\n  columns: invoice_id\nsource_xero.xero_organisation_actions — one entitlement action per organisation per action name\n  The org's capability/entitlement matrix from GET /Organisation/Actions: named features (e.g.\n  columns: organisation_id, name, status\nsource_xero.xero_organisation_addresses — one address per organisation per address type (POBOX, STREET or DELIVERY)\n  Normalized explode of Organisation.Addresses.\n  columns: organisation_id, address_type\nsource_xero.xero_organisation_cis_settings — one CIS configuration record per organisation\n  UK Construction Industry Scheme posture per org, fetched by fan-out from GET /Organisation/{OrganisationID}/CISSettings: whether the org operates as CIS contrac.\n  columns: organisation_id, rate\nsource_xero.xero_organisation_external_links — one external profile link per organisation per array position\n  Normalized explode of Organisation.ExternalLinks — the org's website and social profiles (Facebook, Twitter, LinkedIn, GooglePlus, Website).\n  columns: organisation_id, ordinal\nsource_xero.xero_organisation_payment_terms — one default payment-term rule per organisation per document side (SALES or BILLS)\n  Normalized explode of Organisation.PaymentTerms: the org-level DEFAULT due-date rules for new sales invoices and new bills, one row per side.\n  columns: organisation_id, term_scope, bills_day, bills_type\nsource_xero.xero_organisation_phones — one phone entry per organisation per phone type slot\n  Normalized explode of Organisation.Phones, which reuses the accounting API's shared Phone shape (the same object Contacts use, owned by contacts_dir).\n  columns: organisation_id, phone_type\nsource_xero.xero_organisations — one organisation profile per connected Xero tenant\n  The legal-entity master record and the decoder ring for every number in the connector: exactly one row per connected tenant.\n  columns: organisation_id, version, base_currency, is_demo_company, financial_year_end_day, financial_year_end_month\nsource_xero.xero_overpayment_allocations — one application of overpayment credit to one invoice, keyed by parent overpayment and array position\n  The settlement edge between an overpayment and the invoices it pays down: each row moves a slice of excess-payment credit onto exactly one invoice on a given da.\n  columns: overpayment_overpayment_id, allocation_ordinal, invoice_invoice_id, amount, date\nsource_xero.xero_overpayments — one overpayment credit document per OverpaymentID\n  Credit created when someone paid MORE than was owed (or paid with nothing owed): Xero books the excess as an overpayment against the contact, to be allocated to.\n  columns: overpayment_id, type, date, status, line_amount_types, sub_total, total, currency_code, currency_rate, remaining_credit\nsource_xero.xero_payment_services — one custom online-payment service configuration per PaymentServiceID\n  Org-level configuration of 'Pay Now' services shown on Xero online invoices — the branded URL a customer clicks to pay.\n  columns: payment_service_id\nsource_xero.xero_payments — one payment or refund applied against exactly one invoice, credit note, prepayment or overpayment\n  Cash application evidence: each row records money moving between a bank/clearing account and exactly one receivable or payable document.\n  columns: payment_id, payment_type, status, date, amount, bank_amount, currency_rate, invoice_invoice_id, credit_note_credit_note_id, prepayment_prepayment_id, overpayment_overpayment_id\nsource_xero.xero_payroll_au_deduction_types — one deduction type pay item per org\n  The catalogue of deduction pay items (DeductionTypes family of GET /PayItems): what can be withheld from employees, and how each behaves against tax, super and .\n  columns: deduction_type_id, reduces_tax, reduces_super, current_record\nsource_xero.xero_payroll_au_earnings_rates — one earnings rate pay item per org\n  The catalogue of earnings pay items (from the EarningsRates family of GET /PayItems): every kind of pay the org can put on a payslip, with its ATO classificatio.\n  columns: earnings_rate_id, is_exempt_from_tax, is_exempt_from_super, is_reportable_as_w1, is_qualifying_earnings, earnings_type, rate_type, current_record\nsource_xero.xero_payroll_au_employee_bank_accounts — one net-pay disbursement split per employee per position in the employee's BankAccounts array\n  Standing instructions for where an employee's net pay lands: fixed-amount splits plus exactly one remainder account.\n  columns: employee_id, line_index, remainder, amount\nsource_xero.xero_payroll_au_employee_home_addresses — one home address per employee (the employee's single declared HomeAddress)\n  The employee's declared residential address, normalised out of the employee record.\n  columns: employee_id, region\nsource_xero.xero_payroll_au_employee_leave_balances — one current leave balance per employee per leave type\n  The employee's leave balances as reported by Xero at the moment of the last sync — the 'how much annual leave does everyone have' table.\n  columns: employee_id, leave_type_id, number_of_units, type_of_units\nsource_xero.xero_payroll_au_employee_super_memberships — one super fund membership per SuperMembershipID (an employee's enrolment in one fund)\n  The bridge between employees and superannuation funds: each row is one employee's membership of one fund, with the member number the fund knows them by.\n  columns: super_membership_id, super_fund_id\nsource_xero.xero_payroll_au_employee_tax_declarations — one tax declaration per employee\n  The employee's TFN declaration and PAYG withholding settings: residency, tax scale, threshold claim, study-loan flags and withholding variations.\n  columns: employee_id, employment_basis, residency_status, tax_scale_type, tax_free_threshold_claimed, has_loan_or_student_debt\nsource_xero.xero_payroll_au_employees — one AU payroll employee per EmployeeID\n  The worker dimension for Australian payroll: one row per person (or contractor) the organisation pays through Xero Payroll AU.\n  columns: employee_id, start_date, termination_date, termination_reason, status, employee_group_name, payroll_calendar_id, income_type, employment_type\nsource_xero.xero_payroll_au_leave_applications — one leave application per employee per requested leave span\n  Leave requests as employees and admins entered them: one row per application for a span of a leave type, with the payroll processing broken into per-pay-period .\n  columns: leave_application_id, employee_id, leave_type_id, start_date, end_date, pay_out_type\nsource_xero.xero_payroll_au_leave_periods — one leave period per leave application per pay period it spans\n  The payroll slicing of a leave application: Xero splits each request into one row per pay period it touches, each carrying the units of leave falling in that pe.\n  columns: leave_application_id, leave_periods, leave_periods_pay_period_start_date, leave_periods_pay_period_end_date, leave_periods_number_of_units, leave_periods_leave_period_status\nsource_xero.xero_payroll_au_leave_types — one leave type pay item per org\n  The catalogue of leave types (LeaveTypes family of GET /PayItems): each org-defined leave entitlement with its accrual quantum, unit of measure, statutory categ.\n  columns: leave_type_id, type_of_units, is_paid_leave, current_record, leave_category_code, sgc_exempt, is_qualifying_earnings\nsource_xero.xero_payroll_au_opening_balance_deduction_lines — one migrated YTD deduction amount per employee per position in the employee's OpeningBalances.DeductionLines array\n  Year-to-date deduction totals migrated at conversion, one row per deduction type.\n  columns: employee_id, line_index, deduction_type_id, amount\nsource_xero.xero_payroll_au_opening_balance_earnings_lines — one migrated YTD earnings amount per employee per position in the employee's OpeningBalances.EarningsLines array\n  Year-to-date earnings brought over from the previous payroll system at conversion, one row per earnings rate.\n  columns: employee_id, line_index, earnings_rate_id, amount\nsource_xero.xero_payroll_au_opening_balance_leave_lines — one migrated leave-balance amount per employee per position in the employee's OpeningBalances.LeaveLines array\n  Leave balances carried over from the previous system at conversion: leave type plus units.\n  columns: employee_id, line_index, leave_type_id, number_of_units\nsource_xero.xero_payroll_au_opening_balance_paid_leave_lines — one migrated YTD paid-leave earnings amount per employee per position in the employee's OpeningBalances.PaidLeaveEarningsLines array\n  STP2 disaggregation of migrated YTD earnings: leave actually paid in the prior system, split by leave type, with the leave-loading portions split by Super Guara.\n  columns: employee_id, line_index, leave_type_id, amount\nsource_xero.xero_payroll_au_opening_balance_reimbursement_lines — one migrated YTD reimbursement amount per employee per position in the employee's OpeningBalances.ReimbursementLines array\n  Year-to-date reimbursements migrated at conversion, one row per reimbursement type.\n  columns: employee_id, line_index, reimbursement_type_id, amount\nsource_xero.xero_payroll_au_opening_balance_super_lines — one migrated YTD superannuation amount per employee per position in the employee's OpeningBalances.SuperLines array\n  Year-to-date super contributions migrated at conversion, one row per membership/contribution type.\n  columns: employee_id, line_index, super_membership_id, contribution_type, amount\nsource_xero.xero_payroll_au_opening_balances — one opening-balance header per employee\n  Conversion-time header for an employee migrated into Xero mid-payroll-year: the as-at date and the year-to-date PAYG tax brought across.\n  columns: employee_id, opening_balance_date, tax\nsource_xero.xero_payroll_au_pay_runs — one pay run, keyed by PayRunID — one processing of one payroll calendar over one pay period\n  The header of every AU payroll processing event: each row is one run of one payroll calendar over one period, carrying org-level totals (Wages, Deductions, Tax,.\n  columns: pay_run_id, payroll_calendar_id, pay_run_period_end_date, pay_run_status, payment_date, wages, deductions, tax, super, net_pay\nsource_xero.xero_payroll_au_pay_template_deduction_lines — one standing deduction instruction per employee per position in the employee's PayTemplate.DeductionLines array\n  Recurring deductions configured on the employee's pay template — union fees, child support, salary-packaging and the like — with their calculation basis.\n  columns: employee_id, line_index, deduction_type_id, calculation_type\nsource_xero.xero_payroll_au_pay_template_earnings_lines — one standing earnings instruction per employee per position in the employee's PayTemplate.EarningsLines array\n  The employee's recurring earnings setup: which earnings rates apply and how they are calculated (annual salary, entered rate, or the rate's own default).\n  columns: employee_id, line_index, earnings_rate_id, calculation_type, annual_salary\nsource_xero.xero_payroll_au_pay_template_leave_lines — one standing leave-accrual instruction per employee per position in the employee's PayTemplate.LeaveLines array\n  How each leave type accrues for this employee: the calculation method, annual entitlement units, termination payout treatment and whether the accrual counts as .\n  columns: employee_id, line_index, leave_type_id, calculation_type, entitlement_final_pay_payout_type, is_qualifying_earnings, annual_number_of_units\nsource_xero.xero_payroll_au_pay_template_reimbursement_lines — one standing reimbursement instruction per employee per position in the employee's PayTemplate.ReimbursementLines array\n  Recurring reimbursements on the employee's pay template (e.g.\n  columns: employee_id, line_index, reimbursement_type_id, amount\nsource_xero.xero_payroll_au_pay_template_super_lines — one standing superannuation instruction per employee per position in the employee's PayTemplate.SuperLines array\n  Recurring super contributions configured per employee: the statutory SGC line plus any salary-sacrifice, employer-additional or employee-voluntary lines, each p.\n  columns: employee_id, line_index, super_membership_id, contribution_type, calculation_type\nsource_xero.xero_payroll_au_payroll_calendars — one pay schedule, keyed by PayrollCalendarID — an org can define several calendars of the same frequency, so calendar_type is not a key\n  The org's pay schedules: each row defines a frequency (WEEKLY, FORTNIGHTLY, MONTHLY...) that pay runs are generated from and employees are assigned to.\n  columns: payroll_calendar_id, calendar_type, start_date\nsource_xero.xero_payroll_au_payslip_deduction_lines — one deduction line per payslip per position in the payslip's DeductionLines array\n  Employee-side deductions withheld on a payslip (union fees, workplace giving, purchase plans...), exploded from Payslip.DeductionLines.\n  columns: payslip_id, deduction_lines, deduction_type_id, amount\nsource_xero.xero_payroll_au_payslip_earnings_lines — one earnings line per payslip per position in the payslip's EarningsLines array\n  The wage detail of a payslip: one row per earnings rate applied (ordinary time, overtime, allowances, bonuses...), exploded from Payslip.EarningsLines.\n  columns: payslip_id, earnings_lines, earnings_rate_id, calculation_type, annual_salary, number_of_units, amount\nsource_xero.xero_payroll_au_payslip_leave_accrual_lines — one leave accrual line per payslip per position in the payslip's LeaveAccrualLines array\n  Leave EARNED in the period: each row records units of a leave type accrued on one payslip, exploded from Payslip.LeaveAccrualLines.\n  columns: payslip_id, leave_accrual_lines, leave_accrual_lines_leave_type_id, leave_accrual_lines_number_of_units\nsource_xero.xero_payroll_au_payslip_leave_earnings_lines — one leave earnings line per payslip per position in the payslip's LeaveEarningsLines array\n  Wages paid for leave taken (or cashed out) in the period, exploded from Payslip.LeaveEarningsLines.\n  columns: payslip_id, leave_earnings_lines, leave_earnings_lines_earnings_rate_id, leave_earnings_lines_rate_per_unit, leave_earnings_lines_number_of_units, leave_earnings_lines_pay_out_type\nsource_xero.xero_payroll_au_payslip_reimbursement_lines — one reimbursement line per payslip per position in the payslip's ReimbursementLines array\n  Expense money returned to employees through payroll, exploded from Payslip.ReimbursementLines.\n  columns: payslip_id, reimbursement_lines, reimbursement_type_id, amount\nsource_xero.xero_payroll_au_payslip_superannuation_lines — one superannuation line per payslip per position in the payslip's SuperannuationLines array\n  The superannuation detail of a payslip, exploded from Payslip.SuperannuationLines: each row is one contribution instruction, pairing a super fund membership wit.\n  columns: payslip_id, superannuation_lines, superannuation_lines_contribution_type, superannuation_lines_payment_date_for_this_period, superannuation_lines_amount\nsource_xero.xero_payroll_au_payslip_tax_lines — one PAYG tax line per payslip per position in the payslip's TaxLines array\n  PAYG withholding detail per payslip, exploded from Payslip.TaxLines.\n  columns: payslip_id, tax_lines, tax_lines_amount, tax_lines_manual_tax_type\nsource_xero.xero_payroll_au_payslip_timesheet_earnings_lines — one timesheet-generated earnings line per payslip per position in the payslip's TimesheetEarningsLines array\n  Earnings lines that Xero generated from approved timesheets when the pay run was created, exploded from Payslip.TimesheetEarningsLines (same EarningsLine shape .\n  columns: payslip_id, timesheet_earnings_lines, earnings_rate_id, number_of_units, amount\nsource_xero.xero_payroll_au_payslips — one payslip per employee per pay run\n  The employee-level slice of a pay run: each row is one employee's pay for one run, with totals (Wages, Deductions, Tax, Super, Reimbursements, NetPay) that Xero.\n  columns: payslip_id, pay_run_id, employee_id, wages, deductions, tax, super, net_pay\nsource_xero.xero_payroll_au_reimbursement_types — one reimbursement type pay item per org\n  The catalogue of reimbursement pay items (ReimbursementTypes family of GET /PayItems): the categories of expense money an org repays through payroll, each mappe.\n  columns: reimbursement_type_id, current_record\nsource_xero.xero_payroll_au_settings — one payroll settings record per organisation (the endpoint returns exactly one)\n  Org-wide AU payroll configuration: the payroll year's day count, STP Phase 2 enablement, and which tracking categories classify employees and timesheets.\n  columns: settings_scope, days_in_payroll_year, employees_are_stp2, tracking_categories\nsource_xero.xero_payroll_au_settings_accounts — one payroll control-account wiring entry per settings singleton per AccountID + Type in Settings.Accounts\n  The GL accounts AU payroll posts to — the wiring between payroll and the general ledger: wages expense, wages payable, PAYG liability, super expense and super l.\n  columns: settings_scope, account_id, type\nsource_xero.xero_payroll_au_super_fund_products — one regulated super fund product per ABN + USI\n  Reference catalogue of APRA-regulated super fund products, fetched by looking up the ABN/USI of funds the organisation uses.\n  columns: abn, usi\nsource_xero.xero_payroll_au_super_funds — one superannuation fund per SuperFundID registered in the organisation's payroll\n  The organisation's registry of destination super funds: APRA-regulated funds (identified by USI) and self-managed funds (SMSF, identified by ABN plus their own .\n  columns: super_fund_id, type, usi\nsource_xero.xero_payroll_au_timesheet_lines — one timesheet line per timesheet per position in its TimesheetLines array — a line pairs one earnings rate with one optional tracking option\n  The per-rate detail of a timesheet: each line books hours against one earnings rate, optionally tagged to a tracking option for cost-centre attribution.\n  columns: timesheet_id, timesheet_lines, earnings_rate_id, tracking_item_id, number_of_units\nsource_xero.xero_payroll_au_timesheets — one timesheet record, keyed by TimesheetID — normally one per employee per period, but employee + period is NOT a key because a refused or s\n  Hours as entered: one timesheet record per employee per period, with a total Hours figure and per-rate daily detail in xero_payroll_au_timesheet_lines.\n  columns: timesheet_id, employee_id, start_date, status, hours\nsource_xero.xero_payroll_nz_deductions — one org-level deduction pay item per deduction id\n  The org's catalogue of voluntary deduction types (payroll giving, KiwiSaver voluntary contributions, superannuation top-ups, other) and the liability account ea.\n  columns: deduction_id, deduction_category, current_record\nsource_xero.xero_payroll_nz_earnings_rates — one org-level earnings rate (pay item) per earnings rate id\n  The org's catalogue of ways people can be paid: ordinary earnings, overtime multipliers, allowances, bonuses, holiday pay and the rest, each with its calculatio.\n  columns: earnings_rate_id, earnings_type, rate_type, type_of_units, current_record, multiple_of_ordinary_earnings_rate\nsource_xero.xero_payroll_nz_employee_bank_accounts — one wage-destination bank account per employee, keyed by employee and array position\n  The bank accounts an electronically-paid employee's net pay is split into, with the split rule per account: a FixedAmount account takes dollar_amount each pay a.\n  columns: employee_id, bank_accounts, dollar_amount, calculation_type\nsource_xero.xero_payroll_nz_employee_leave — one leave request (a dated span of one leave type) per employee\n  Leave events: each row is one employee's request to take a specific leave type over a start/end date span.\n  columns: leave_id, leave_type_id, start_date, end_date\nsource_xero.xero_payroll_nz_employee_leave_balances — one current leave balance per employee per leave type\n  Point-in-time leave balances: how many units of each leave type each employee holds as of the last sync.\n  columns: employee_id, leave_type_id, balance, type_of_units\nsource_xero.xero_payroll_nz_employee_leave_periods — one pay-period slice of one leave request, keyed by leave request and array position\n  The quantity-bearing grain of leave: each leave request is split into the pay periods it touches, with units scheduled (number_of_units) and units actually take.\n  columns: leave_id, periods, period_start_date, number_of_units, number_of_units_taken, type_of_units, period_status\nsource_xero.xero_payroll_nz_employee_leave_types — one leave-type assignment (with its accrual configuration) per employee per leave type\n  The per-employee accrual contract for each leave type the employee is enrolled in: how it accrues, at what annual quantity, caps, opening balance and NZ-specifi.\n  columns: employee_id, leave_type_id, schedule_of_accrual, units_accrued_annually, percentage_of_gross_earnings, include_holiday_pay_every_pay, annual_leave_total_amount_paid\nsource_xero.xero_payroll_nz_employee_opening_balances — one historical pay-period opening-balance line per employee, keyed by employee and array position\n  Pre-Xero earnings history typed in at migration so NZ Holidays Act calculations (ordinary weekly pay, average weekly earnings) are correct from the org's first .\n  columns: employee_id, balance_ordinal, period_end_date, gross_earnings\nsource_xero.xero_payroll_nz_employee_pay_template_earnings — one earnings template line per employee pay template, keyed by its payTemplateEarningID\n  The employee's standing pay template: the earnings lines Xero pre-loads into each new pay run draft (e.g.\n  columns: employee_id, pay_template_earning_id, earnings_rate_id, rate_per_unit, number_of_units, fixed_amount\nsource_xero.xero_payroll_nz_employee_payment_methods — one payment-method record per employee\n  How the employee is paid: Electronically (bank transfer), Cheque or Manual.\n  columns: employee_id, payment_method\nsource_xero.xero_payroll_nz_employee_tax — one current tax configuration record per employee\n  The employee's IRD tax settings and KiwiSaver membership: tax code, special rates, student loan position and contribution percentages.\n  columns: employee_id, tax_code, is_eligible_for_kiwi_saver, esct_rate_percentage, kiwi_saver_contributions, kiwi_saver_employee_contribution_rate_percentage, kiwi_saver_employer_contribution_rate_percentage\nsource_xero.xero_payroll_nz_employee_working_patterns — one effective-dated working pattern per employee\n  Header of an employee's regular-week working pattern, effective from a date; the actual hours-per-weekday grid lives in xero_payroll_nz_employee_working_weeks.\n  columns: payee_working_pattern_id, effective_from\nsource_xero.xero_payroll_nz_employee_working_weeks — one week of a working pattern's repeating cycle, keyed by pattern and array position\n  The hours grid of a working pattern: hours to be worked on each weekday.\n  columns: payee_working_pattern_id, working_weeks, monday, tuesday, wednesday, thursday, friday, saturday, sunday\nsource_xero.xero_payroll_nz_employees — one employee record per person employed under the tenant's NZ payroll\n  The worker master for NZ Payroll v2: identity, home address, employment dates and the payroll calendar the person is paid on.\n  columns: employee_id, start_date, end_date, payroll_calendar_id, engagement_type\nsource_xero.xero_payroll_nz_leave_types — one org-level leave type per leave type id\n  The org's leave-type catalogue: annual, sick, bereavement, public holidays, unpaid and custom types, with whether they are paid and how their units are expresse.\n  columns: leave_type_id, is_paid_leave, is_active, type_of_units\nsource_xero.xero_payroll_nz_pay_run_calendars — one pay-run calendar (pay frequency definition) per payroll calendar id\n  The org's pay cycles: frequency (weekly through annual), the CURRENT period's start/end and the payment date.\n  columns: payroll_calendar_id, calendar_type, payment_date\nsource_xero.xero_payroll_nz_pay_runs — one NZ pay run — a single processing (scheduled, unscheduled, or earlier-year-update) of one payroll calendar period\n  The header record for every time NZ payroll was (or is being) processed, and the ONLY place this domain carries dates and a posting status.\n  columns: pay_run_id, period_start_date, period_end_date, payment_date, total_cost, total_pay, pay_run_status, pay_run_type, calendar_type\nsource_xero.xero_payroll_nz_payslip_deduction_lines — one voluntary/contractual deduction line on one payslip (position within PaySlip.deductionLines)\n  Non-statutory deductions withheld from pay: payroll giving, social club, union fees, employee super top-ups beyond KiwiSaver minima.\n  columns: pay_slip_id, line_index, deduction_type_id, amount, subject_to_tax\nsource_xero.xero_payroll_nz_payslip_earnings_lines — one ordinary earnings line on one payslip (position within PaySlip.earningsLines)\n  Ordinary (non-leave, non-timesheet) earnings detail: salary, ordinary hours, allowances, bonuses — one row per earnings rate applied on the payslip.\n  columns: pay_slip_id, line_index, earnings_rate_id, number_of_units, amount\nsource_xero.xero_payroll_nz_payslip_employee_tax_lines — one employee-side tax line on one payslip (position within PaySlip.employeeTaxLines)\n  Tax withheld FROM the employee — PAYE under the payslip's tax code — one row per tax component, rolling up to PaySlip.totalEmployeeTaxes.\n  columns: pay_slip_id, line_index, amount\nsource_xero.xero_payroll_nz_payslip_employer_tax_lines — one employer-side tax line on one payslip (position within PaySlip.employerTaxLines)\n  Tax the EMPLOYER owes on top of pay — in NZ practice, ESCT on employer superannuation contributions — one row per component, rolling up to PaySlip.totalEmployer.\n  columns: pay_slip_id, line_index, amount\nsource_xero.xero_payroll_nz_payslip_leave_accrual_lines — one leave accrual line on one payslip — units of one leave type accrued in one pay period (position within PaySlip.leaveAccrualLines)\n  Leave ENTITLEMENT EARNED this pay period, per leave type — the accrual side of leave, with no dollar amounts.\n  columns: pay_slip_id, line_index, leave_type_id, number_of_units\nsource_xero.xero_payroll_nz_payslip_leave_earnings_lines — one leave earnings line on one payslip (position within PaySlip.leaveEarningsLines)\n  Pay for leave TAKEN in the period — annual leave, sick leave, public holidays — one row per leave earnings rate on the payslip.\n  columns: pay_slip_id, line_index, earnings_rate_id, number_of_units, amount\nsource_xero.xero_payroll_nz_payslip_payment_lines — one bank payment split of one payslip's net pay (position within PaySlip.paymentLines)\n  How the payslip's NET pay was distributed to bank accounts — one row per destination account, summing to PaySlip.totalPay.\n  columns: pay_slip_id, line_index, amount\nsource_xero.xero_payroll_nz_payslip_reimbursement_lines — one reimbursement line on one payslip (position within PaySlip.reimbursementLines)\n  Non-taxable repayments of employee out-of-pocket expenses, paid through payroll and rolled up to PaySlip.totalReimbursements.\n  columns: pay_slip_id, line_index, reimbursement_type_id, amount\nsource_xero.xero_payroll_nz_payslip_statutory_deduction_lines — one statutory deduction line on one payslip (position within PaySlip.statutoryDeductionLines)\n  Withholdings required by law, deducted from the employee's pay and rolled up to PaySlip.totalStatutoryDeductions: student loan repayments, child support, employ.\n  columns: pay_slip_id, line_index, statutory_deduction_type_id, amount\nsource_xero.xero_payroll_nz_payslip_superannuation_lines — one superannuation line on one payslip (position within PaySlip.superannuationLines)\n  EMPLOYER superannuation contributions per payslip — in NZ practice, employer KiwiSaver — rolling up to PaySlip.totalSuperannuation.\n  columns: pay_slip_id, line_index, superannuation_type_id, amount\nsource_xero.xero_payroll_nz_payslip_timesheet_earnings_lines — one timesheet-sourced earnings line on one payslip (position within PaySlip.timesheetEarningsLines)\n  Earnings generated from approved timesheets — the third and final slice of gross pay alongside ordinary and leave earnings.\n  columns: pay_slip_id, line_index, earnings_rate_id, number_of_units, amount\nsource_xero.xero_payroll_nz_payslips — one payslip — one employee's pay within one pay run\n  The employee-level payroll fact: every totals column here is the roll-up of one typed line family below it.\n  columns: pay_slip_id, employee_id, pay_run_id, total_earnings, gross_earnings, total_pay, total_employer_taxes, total_employee_taxes, total_deductions, total_reimbursements, total_statutory_deductions, total_superannuation, payment_method, tax_settings_tax_code, tax_settings_lump_sum_amount\nsource_xero.xero_payroll_nz_reimbursements — one org-level reimbursement type per reimbursement id\n  Catalogue of expense-reimbursement pay items (mileage, tools, phone...) paid through payroll, with GST treatment and calculation mechanics.\n  columns: reimbursement_id, reimbursement_category, calculation_type\nsource_xero.xero_payroll_nz_salary_and_wages — one effective-dated salary or wage arrangement per employee, identified by its salaryAndWagesID\n  The employee's base-pay history: each row is a salary/hourly arrangement effective from a date, with status Active (current), Pending (future-dated) or History .\n  columns: salary_and_wages_id, number_of_units_per_week, rate_per_unit, effective_from, annual_salary, status, payment_type\nsource_xero.xero_payroll_nz_settings_accounts — one payroll posting role (PAYE liability, wages payable, wages expense, payroll bank) per tenant\n  The org's payroll posting map: which GL accounts NZ payroll posts PAYE liabilities, wages payable, wage expense and the payroll bank account to.\n  columns: type\nsource_xero.xero_payroll_nz_statutory_deductions — one org-level statutory deduction type per id\n  Legally-mandated deduction types the org can process: attachment/earnings orders (court fines, child support, MSD repayments, IR arrears), student loan variants.\n  columns: id, statutory_deduction_category, current_record\nsource_xero.xero_payroll_nz_superannuations — one org-level superannuation benefit scheme per id\n  Employer superannuation schemes the org contributes to: KiwiSaver, complying funds and other schemes, with the calculation rule (fixed amount vs percentage of t.\n  columns: id, category, calculation_type_nz, current_record\nsource_xero.xero_payroll_nz_timesheet_lines — one day's units against one earnings rate (and optional tracking item) within one timesheet\n  The atomic worked-time fact for NZ payroll: date, earnings rate, optional tracking category option and units (hours).\n  columns: timesheet_line_id, timesheet_id, date, earnings_rate_id, tracking_item_id, number_of_units\nsource_xero.xero_payroll_nz_timesheets — one submitted timesheet document, identified by timesheetID — an employee can hold more than one covering the same pay-calendar period when \n  Header of an employee's timesheet for one pay-calendar period, with lifecycle status and Xero's own totalHours rollup.\n  columns: timesheet_id, start_date, status, total_hours\nsource_xero.xero_payroll_nz_tracking_categories — one payroll tracking-category configuration record per tenant\n  Singleton configuration naming which of the org's two accounting tracking categories payroll uses: one to group employees (cost-center reporting of wages) and o.\n  columns: settings_key, employee_groups_tracking_category_id, timesheet_tracking_category_id\nsource_xero.xero_payroll_uk_benefits — one employer benefit (pension) pay item per benefit id\n  Org-level employer benefit definitions — in the UK API these are overwhelmingly employer PENSION schemes (the spec literally describes the fields as 'the employ.\n  columns: id, category, percentage, calculation_type, current_record, is_calculating_on_qualifying_earnings\nsource_xero.xero_payroll_uk_deductions — one deduction pay item per deductionId\n  Org-level deduction definitions: employee pension contributions, salary sacrifice, student/postgraduate loan items, childcare vouchers, court-order style repaym.\n  columns: deduction_id, deduction_category, current_record, reduces_tax_liability, calculation_type, subject_to_nic, is_reduced_by_basic_rate, is_pension\nsource_xero.xero_payroll_uk_earnings_orders — one attachment-of-earnings order pay item per earnings order id\n  Org-level attachment/earnings-order definitions — court-mandated deductions (child support, court fines, creditor orders) applied to employees' pay.\n  columns: id, statutory_deduction_category, current_record\nsource_xero.xero_payroll_uk_earnings_rates — one earnings rate pay item per earningsRateID\n  The org's catalogue of ways people earn: regular pay, overtime, bonuses, commission, tips, termination pay and the full family of statutory pay types (SSP, SMP,.\n  columns: earnings_rate_id, earnings_type, rate_type, type_of_units, current_record\nsource_xero.xero_payroll_uk_employee_bank_accounts — one net-pay destination bank account per employee per array position\n  The bank accounts an electronically-paid employee's net pay is sent to.\n  columns: employee_id, ordinal\nsource_xero.xero_payroll_uk_employee_contracts — one employment contract episode per employee per array position\n  The authoritative employment-episode history: each row is a contract (full/part-time/zero-hour, employee vs worker status, fixed-term window, optional apprentic.\n  columns: employee_id, ordinal, start_date, employment_status, contract_type\nsource_xero.xero_payroll_uk_employee_leave — one leave request per leaveID\n  Booked leave (holiday, unpaid leave, org-defined types) per employee.\n  columns: leave_id, employee_id, leave_type_id, start_date, end_date\nsource_xero.xero_payroll_uk_employee_leave_balances — one current leave balance per employee per leave type\n  The employee's leave balances as of the last sync — a point-in-time snapshot that each sync overwrites.\n  columns: employee_id, leave_type_id, balance, type_of_units\nsource_xero.xero_payroll_uk_employee_leave_periods — one pay-period slice of one leave request\n  How each leave request is carved across payroll periods, with the number of units actually deducted from the balance in each period.\n  columns: leave_id, ordinal, period_start_date, number_of_units, period_status\nsource_xero.xero_payroll_uk_employee_leave_types — one leave-type enrolment (accrual rule) per employee per leave type\n  The per-employee accrual configuration for each leave type the employee is enrolled in: accrual schedule, annual hours, caps and opening balance.\n  columns: employee_id, leave_type_id, schedule_of_accrual, hours_accrued_annually\nsource_xero.xero_payroll_uk_employee_ni_categories — one effective-dated National Insurance category assignment per employee per array position\n  The employee's NI category letter history, exploded from the employee record.\n  columns: employee_id, ordinal, start_date, ni_category\nsource_xero.xero_payroll_uk_employee_opening_balances — one migration-time opening balance record per employee\n  Fiscal year-to-date statutory pay amounts the employee had ALREADY received before the organisation started (or re-based) Xero payroll, plus the prior employer'.\n  columns: employee_id, statutory_adoption_pay, statutory_maternity_pay, statutory_paternity_pay, statutory_shared_parental_pay, statutory_sick_pay\nsource_xero.xero_payroll_uk_employee_pay_template_earnings — one standing earnings line per employee's pay template (payTemplateEarningID)\n  The employee's pay template: standing earnings instructions (regular allowances, fixed amounts, default units) that seed each new pay run.\n  columns: pay_template_earning_id, employee_id, earnings_rate_id\nsource_xero.xero_payroll_uk_employee_payment_methods — one net-pay payment method configuration per employee\n  How each employee's net pay leaves the business: electronically (BACS file), by cheque, or recorded as paid manually.\n  columns: employee_id, payment_method\nsource_xero.xero_payroll_uk_employee_salary_and_wages — one effective-dated salary or wage basis record per salaryAndWagesID\n  The employee's pay basis history: each row fixes an annual salary or hourly arrangement from an effective date, with exactly one Active row per employee at a ti.\n  columns: salary_and_wages_id, employee_id, number_of_units_per_week, rate_per_unit, effective_from, annual_salary, status, payment_type\nsource_xero.xero_payroll_uk_employee_statutory_leave_balances — one statutory leave balance per employee per statutory leave type per as-of date the scan requested\n  Remaining statutory entitlement (SSP, SMP, SPP, SAP, ShPP, bereavement, neonatal care) per employee, fetched one leave type at a time with an explicit as-of dat.\n  columns: employee_id, leave_type, as_of_date, balance_remaining\nsource_xero.xero_payroll_uk_employee_tax — one current PAYE tax configuration per employee\n  The employee's live HMRC tax settings: tax code, W1/M1 basis, starter declaration, P45 carry-in figures, student/postgraduate loan flags and director NIC treatm.\n  columns: employee_id, tax_code, w1_m1, previous_taxable_pay, is_director\nsource_xero.xero_payroll_uk_employees — one current or former UK payroll employee per employeeID within the organisation\n  The master roster of everyone the organisation pays through Xero UK Payroll: current staff, leavers, and off-payroll workers.\n  columns: employee_id, start_date, end_date, is_off_payroll_worker\nsource_xero.xero_payroll_uk_leave_types — one org-level leave type per leaveTypeID\n  The organisation's catalogue of leave types (holiday, sickness, unpaid leave...), with the flags that change how leave costs and displays: paid vs unpaid, statu.\n  columns: leave_type_id, is_paid_leave, is_active, is_statutory_leave\nsource_xero.xero_payroll_uk_pay_run_calendars — one payroll calendar (pay frequency schedule) per payrollCalendarID\n  The org's pay schedules: frequency (weekly through annual), the CURRENT period's start/end and its payment date.\n  columns: payroll_calendar_id, calendar_type\nsource_xero.xero_payroll_uk_pay_runs — one UK payroll pay run: one processing of one payroll calendar over one pay period\n  The processing container for UK payroll.\n  columns: pay_run_id, payment_date, total_cost, total_pay, pay_run_status, pay_run_type\nsource_xero.xero_payroll_uk_payslip_benefit_lines — one benefit line per payslip per position in its benefitLines array\n  Non-earnings compensation applied on the payslip — the spec's own framing is fringe benefits and perks provided in addition to normal earnings.\n  columns: pay_slip_id, benefit_lines, benefit_type_id, amount\nsource_xero.xero_payroll_uk_payslip_court_order_lines — one court order line per payslip per position in its courtOrderLines array\n  Statutory attachments the employer must divert from the employee's pay under a court or agency order — attachment of earnings orders (AEOs), child maintenance D.\n  columns: pay_slip_id, court_order_lines, court_order_type_id, amount\nsource_xero.xero_payroll_uk_payslip_deduction_lines — one deduction line per payslip per position in its deductionLines array\n  Configured deductions taken from the employee's own pay on the way from gross to net — typically employee pension contributions, salary sacrifice, union fees an.\n  columns: pay_slip_id, deduction_lines, deduction_type_id, amount, subject_to_tax\nsource_xero.xero_payroll_uk_payslip_earnings_lines — one regular earnings line per payslip per position in its earningsLines array\n  Regular (non-leave, non-timesheet) earnings detail: salary, hourly wages, bonuses, overtime and other configured earnings rates, one row per rate application on.\n  columns: pay_slip_id, earnings_lines, rate_per_unit, amount\nsource_xero.xero_payroll_uk_payslip_employee_tax_lines — one employee tax line per payslip per position in its employeeTaxLines array\n  Statutory tax withheld FROM the employee: PAYE income tax and employee (primary Class 1) National Insurance, one row per tax component.\n  columns: pay_slip_id, employee_tax_lines, description, is_employer_tax, amount\nsource_xero.xero_payroll_uk_payslip_employer_tax_lines — one employer tax line per payslip per position in its employerTaxLines array\n  Tax the EMPLOYER owes on top of gross pay: employer (secondary Class 1) National Insurance and Apprenticeship Levy, one row per component.\n  columns: pay_slip_id, employer_tax_lines, description, is_employer_tax, amount\nsource_xero.xero_payroll_uk_payslip_leave_accrual_lines — one leave accrual line per payslip per position in its leaveAccrualLines array\n  Leave entitlement EARNED in this pay run, in units (hours or days per the leave type) — no money on this table at all.\n  columns: pay_slip_id, leave_accrual_lines, leave_type_id, number_of_units\nsource_xero.xero_payroll_uk_payslip_leave_earnings_lines — one leave earnings line per payslip per position in its leaveEarningsLines array\n  Pay for leave actually taken in the period — holiday pay, statutory sick/parental pay priced through leave-linked earnings rates.\n  columns: pay_slip_id, leave_earnings_lines, rate_per_unit, amount\nsource_xero.xero_payroll_uk_payslip_payment_lines — one payment line per payslip per position in its paymentLines array\n  How the payslip's NET pay is disbursed: one row per destination bank account, carrying employee bank details (account number, sort code, account name — all PII).\n  columns: pay_slip_id, payment_lines, amount\nsource_xero.xero_payroll_uk_payslip_reimbursement_lines — one reimbursement line per payslip per position in its reimbursementLines array\n  Non-taxable repayments of out-of-pocket expenses settled through payroll.\n  columns: pay_slip_id, reimbursement_lines, amount\nsource_xero.xero_payroll_uk_payslip_timesheet_earnings_lines — one timesheet earnings line per payslip per position in its timesheetEarningsLines array\n  Earnings sourced from approved timesheets: hours captured on timesheets, priced at an earnings rate and settled on the payslip.\n  columns: pay_slip_id, timesheet_earnings_lines, rate_per_unit, number_of_units, amount\nsource_xero.xero_payroll_uk_payslips — one payslip per employee per pay run\n  The per-employee settlement of a pay run: header totals for gross, net, taxes, deductions, reimbursements, court orders and benefits, with the line-level detail.\n  columns: pay_slip_id, employee_id, pay_run_id, total_earnings, gross_earnings, total_pay, total_employer_taxes, total_employee_taxes, total_deductions, total_reimbursements, total_court_orders, total_benefits\nsource_xero.xero_payroll_uk_reimbursements — one reimbursement pay item per reimbursementID\n  Org-level reimbursement definitions — non-taxable repayments of employee expenses routed through payroll (mileage, tools, expenses).\n  columns: reimbursement_id, current_record\nsource_xero.xero_payroll_uk_settings_accounts — one payroll GL account mapping per payroll account role (type) for the organisation\n  The payroll settings' GL account map: which general-ledger accounts UK payroll posts wages expense, wages payable, PAYE and NIC liabilities and the payment bank.\n  columns: type\nsource_xero.xero_payroll_uk_statutory_leave_summaries — one statutory leave episode per statutoryLeaveID\n  Every statutory leave episode (maternity, paternity, adoption, shared parental, bereavement, neonatal care, sickness) recorded for each employee, with its date .\n  columns: statutory_leave_id, employee_id, type, start_date, is_entitled, status\nsource_xero.xero_payroll_uk_statutory_sick_leaves — one statutory sick pay (SSP) episode per statutoryLeaveID\n  Full SSP detail for sick episodes discovered in the summaries table: entitlement weeks requested/qualified/remaining, work pattern, pregnancy linkage, notice co.\n  columns: statutory_leave_id, employee_id, start_date, is_pregnancy_related, is_entitled, entitlement_weeks_remaining\nsource_xero.xero_payroll_uk_timesheet_lines — one timesheet line per timesheetLineID: one employee's units for one date and one earnings rate\n  The daily detail behind each timesheet: units (per the earnings rate's unit type, normally hours) worked on a specific date under a specific earnings rate, opti.\n  columns: timesheet_line_id, timesheet_id, date, earnings_rate_id, number_of_units\nsource_xero.xero_payroll_uk_timesheets — one timesheet per timesheetID: one employee's submitted hours for one payroll-calendar period\n  Timesheet headers, each covering one employee for one payroll-calendar period and carrying the total hours plus the approval lifecycle.\n  columns: timesheet_id, payroll_calendar_id, employee_id, start_date, status, total_hours\nsource_xero.xero_payroll_uk_tracking_categories — one payroll tracking configuration record per organisation\n  A single-row pointer table: which two ACCOUNTING tracking categories UK payroll uses — one for employee groups (org-structure reporting on pay runs) and one for.\n  columns: record_key, employee_groups_tracking_category_id, timesheet_tracking_category_id\nsource_xero.xero_prepayment_allocations — one application of prepayment credit to one invoice, keyed by parent prepayment and array position\n  The settlement edge between a prepayment and the invoices it pays down: each row moves a slice of held credit onto exactly one invoice on a given date.\n  columns: prepayment_prepayment_id, allocation_ordinal, invoice_invoice_id, amount, date\nsource_xero.xero_prepayments — one prepayment credit document per PrepaymentID\n  Money received (or paid) BEFORE any invoice exists: a prepayment is created from a bank transaction and sits as credit against the contact until allocated to in.\n  columns: prepayment_id, type, date, status, line_amount_types, sub_total, total, currency_code, currency_rate, remaining_credit\nsource_xero.xero_project_tasks — one task (a billable or non-billable work item) on one project per taskId\n  The work-item and billing-line level of a project: each task carries its charge model (charge_type plus the rate Amount pair) and Xero-maintained to-date rollup.\n  columns: task_id, charge_type, rate_value, total_minutes, minutes_invoiced, minutes_to_be_invoiced, fixed_minutes, non_chargeable_minutes, total_amount_value, amount_to_be_invoiced_value, amount_invoiced_value, status\nsource_xero.xero_project_time_entries — one logged block of minutes by one user against one task per timeEntryId\n  The only transaction-grain fact in the projects domain: one row per block of minutes a user logged against a task, fully additive across every dimension.\n  columns: time_entry_id, task_id, date_utc, date_entered_utc, duration, status\nsource_xero.xero_project_users — one Xero user with access to Xero Projects in the org per userId\n  Roster dimension of everyone who can appear in Xero Projects time data — the join target that turns a time entry's user_id into a person.\n  columns: user_id\nsource_xero.xero_projects — one Xero Projects project (a client job) per projectId\n  The client-job dimension of Xero Projects and the fastest place to answer job-profitability questions: every monetary column is a Xero-maintained to-date rollup.\n  columns: project_id, status, currency_code, minutes_logged, minutes_to_be_invoiced, total_task_amount_value, total_expense_amount_value, estimate_value, task_amount_to_be_invoiced_value, task_amount_invoiced_value, expense_amount_to_be_invoiced_value, expense_amount_invoiced_value, project_amount_invoiced_value, deposit_value, deposit_applied_value, credit_note_amount_value\nsource_xero.xero_purchase_order_line_items — one line item on one purchase order\n  The queryable grain of committed procurement: what is being ordered, from which GL account and catalog item, at what price, carrying the order's tracking dimens.\n  columns: purchase_order_id, line_ordinal, quantity, unit_amount, item_code, account_code, line_amount, tracking\nsource_xero.xero_purchase_orders — one purchase order document raised against one supplier contact\n  The commitment ledger of procurement: each row is an order placed (or drafted) with a supplier, with tax-normalized header totals in the document's own currency.\n  columns: purchase_order_id, contact_contact_id, status, date, line_amount_types, currency_code, currency_rate, sub_total, total\nsource_xero.xero_quote_line_items — one line item on one quote per LineItemID\n  Proposed-value lines exploded from Quote.LineItems: what was offered, at what price, before anything was billed.\n  columns: line_items_line_item_id, quote_id, line_items_line_amount\nsource_xero.xero_quotes — one quote document per QuoteID\n  Pre-revenue sales pipeline: quotes are offers, always customer-facing (no ACCREC/ACCPAY split here), and none of their value is billed until an invoice is raise.\n  columns: quote_id, status, date, expiry_date, currency_code, line_amount_types, sub_total, total\nsource_xero.xero_receipt_line_items — one line item on one expense receipt\n  The GL-categorized grain of employee out-of-pocket spend: each row says which account (and optionally which catalog item and tracking dimensions) a slice of a r.\n  columns: receipt_id, line_ordinal, account_code, line_amount, tracking\nsource_xero.xero_receipts — one expense receipt captured by one org user in the classic expense-claims workflow\n  Employee out-of-pocket spend documents: who spent, at which merchant, on what date, with tax-normalized totals in org base currency (receipts carry no currency .\n  columns: receipt_id, date, contact_contact_id, user_user_id, line_amount_types, sub_total, total, status\nsource_xero.xero_repeating_invoice_line_items — one line item on one repeating invoice template per LineItemID\n  The composition of each recurring template: which products/services and GL accounts every generated invoice will carry.\n  columns: line_items_line_item_id, repeating_invoice_id, line_items_line_amount, line_items_account_code\nsource_xero.xero_repeating_invoices — one repeating invoice template per RepeatingInvoiceID\n  Templates that GENERATE invoices on a schedule — recurring billing (ACCREC) or recurring bills (ACCPAY), with the Schedule object flattened into schedule_* colu.\n  columns: repeating_invoice_id, type, status, line_amount_types, currency_code, sub_total, total_tax, total, schedule_period, schedule_unit\nsource_xero.xero_tax_rate_components — one constituent component per (tax rate, zero-based array position)\n  The parts a tax rate is built from — e.g.\n  columns: tax_type, tax_components, rate, is_compound\nsource_xero.xero_tax_rates — one org tax rate per TaxType code\n  The org's tax rate definitions, keyed by the TaxType code that journal lines, document lines and account defaults all reference.\n  columns: tax_type, status, report_tax_type, display_tax_rate, effective_rate\nsource_xero.xero_tracking_categories — one tracking category (analysis dimension) per TrackingCategoryID\n  The org's self-defined analysis dimensions — 'Department', 'Region', 'Cost Centre' — of which at most two can be ACTIVE at once.\n  columns: tracking_category_id, name, status\nsource_xero.xero_tracking_options — one selectable option per TrackingOptionID within its tracking category\n  The value list of each tracking category — the 'East', 'West', 'Marketing' a line can be stamped with.\n  columns: tracking_option_id, tracking_category_id, name\nsource_xero.xero_users — one user login with access to the connected organisation\n  Everyone who can act inside the org — staff, external accountants and practice-side logins — with their permission tier.\n  columns: user_id, organisation_role";

